UPDATE public.landing_pages AS p SET title='Ürün geliştirme prototipleri: ilk numunede neyi doğrularız?',summary='Bir ürün fikrini elde tutulan numuneye taşırken ergonomi, bileşen yerleşimi ve montaj sorularını birbirinden ayırın.',sections='[{"title":"Tek numuneye tek karar görevi verin","body":"Bu aşamada çalışan elektronik veya satışa hazır yüzey şart değildir. Sonraki iterasyonda kart, pil ve bağlantı boşlukları denenir. Değerlendirilecek soruyu baştan yazmak, aynı numuneye hem görünüş hem kullanım ömrü testi yüklenmesini önler."},{"title":"Revizyonu gözlemle ilişkilendirin","body":"Deneme sırasında tespit edilen noktaları fotoğrafta işaretleyin: parmağın sıkıştığı kenar, tornavidanın giremediği yuva veya kapağın temas ettiği çıkıntı. Her bulguya bir tasarım değişikliği ve yeniden kontrol adımı bağlayın. Sonraki numunenin kabulü, önceki parçaya benzemesinden çok bu bulguların kapanmasına dayanmalıdır."}]'::jsonb,faq='[{"q":"Bir fikir eskiziyle başlanabilir mi?","a":"Evet; eskize yaklaşık dış ölçüler, kullanım biçimi ve içinde bulunacak bileşenler eklendiğinde modelleme kapsamı değerlendirilebilir. İlk teslimatın görsel model mi montaj numunesi mi olacağı seçilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir el cihazında önce kavrama biçimi, düğme erişimi ve ana hacim konuşulabilir.","takeaways":["Kullanıcının tutuş veya kullanım fotoğrafı","Yerleşecek bileşenlerin dış ölçüleri","İlk numunede yanıtlanacak üç soru"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/cozumler/urun-gelistirme-prototipleri' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Ürün geliştirme prototipleri","summary":"Tasarım kararlarını fiziksel model üzerinden değerlendirmek için form, yerleşim ve montaj prototipleri.","sections":[{"title":"Projenizin başlangıcı","body":"Tasarımınızı fiziksel olarak değerlendirin. Model revizyonu, montaj kontrolü ve sonraki iterasyon için proje kapsamını birlikte belirleyelim."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün montajı için hizalama ve yerleştirme yardımcıları',summary='Küçük seri ürün montajında parça yerini, bağlantı yönünü ve operatör erişimini belirleyen yardımcı aparatları planlayın.',sections='[{"title":"Ürünün hassas yüzeyini koruyun","body":"Tutucunun temas bölgelerini çizim üzerinde seçin; çizilmeye açık alanları ve parçanın serbest bırakılacağı yönü gösterin. Aparatın yalnızca yer belirlemesi mi yoksa kuvvet de taşıması mı beklendiğini ayırmak gerekir."},{"title":"Montaj sırasını küçük bir denemeyle görün","body":"Önce tek iş istasyonunun hareketini tarif edin. Parça oturtulduktan sonra vida, yapıştırıcı veya ikinci bileşene erişim kalmalıdır. Numunede takma ve çıkarma hareketlerini operatörle deneyin; sıkışma oluşan noktaları işaretleyin. İkinci bir ürün revizyonu geldiğinde hangi temas yüzeylerinin değiştiği ayrıca kontrol edilir."}]'::jsonb,faq='[{"q":"Bir aparat birkaç ürün varyantında kullanılabilir mi?","a":"Değişen yüzeyler sınırlıysa ayrı yerleştirme parçaları değerlendirilebilir. Varyantların ortak dayama noktaları ve karıştırılma olasılığı görülmeden tek gövde kararı verilmez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Boyanmış bir gövde veya gösterge ekranı montaj sırasında doğrudan sert dayama yüzeyine basmamalıdır.","takeaways":["Montaj adımlarını gösteren kısa video","Temas edebilecek ve korunacak yüzeyler","Ürün varyantları ve bağlantı elemanları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/cozumler/montaj-yardimcilari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Montaj yardımcıları","summary":"Tekrarlayan montaj ve konumlandırma adımları için projeye özel yardımcı parçalar.","sections":[{"title":"Projenizin başlangıcı","body":"Sahadaki ihtiyacı ölçülebilir bir parça tarifine dönüştürelim. Kullanım koşulları, bağlantı noktaları ve işlev üzerinden ilerleyelim."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Elektronik ürün prototipleri için özel muhafaza',summary='Kart, ekran, pil ve kablo girişlerini birlikte ele alan gövde prototipiyle ürününüzün erişim ve yerleşim kararlarını sınayın.',sections='[{"title":"Kart sınırından daha fazlasını ölçün","body":"Konektör yüksekliği, kablonun bükülme alanı, düğme hareketi ve pilin çıkarılma yolu da iç hacmi etkiler. Kart revizyonunu ve sabitleneceği noktaları dosyada belirtin; dış görünüş modeli ile gerçek bileşen yerleşimini aynı sürümde tutun."},{"title":"Kapanma ve servis erişimini deneyin","body":"Vidalı kapak, geçmeli bağlantı ve iki parçalı gövde farklı açılma davranışları verir. İlk üretimde kapağın oturmasını, vidalama sırasında oluşan hareketi ve bağlantı noktalarının erişimini gözleyin. Havalandırma, sızdırmazlık veya elektriksel koruma gibi beklentiler ayrıca tanımlanır; görünüş numunesinden kendiliğinden bu özellikler çıkarılmaz."}]'::jsonb,faq='[{"q":"Elektronik olmadan gövde çalışılabilir mi?","a":"Bileşenlerin ölçülü çizimleriyle başlangıç yapılabilir. Gerçek kart veya temsilî ölçü bloklarıyla son yerleşim kontrolü planlanır; eksik konektör bilgisi açık bir varsayım olarak kaydedilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Muhafaza ihtiyacı yalnızca devre kartının eni ve boyundan oluşmaz.","takeaways":["Kart revizyonu ve montaj delikleri","Düğme, ekran ve konektör konumları","Kapağı kim, hangi sıklıkla açacak?"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/cozumler/ozel-muhafaza-aparatlar' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Özel muhafaza & aparatlar","summary":"Elektronik cihazlar, test düzenekleri ve özel sistemler için geometriye uygun muhafazalar.","sections":[{"title":"Projenizin başlangıcı","body":"Teknik kapsamı, adedi ve teslimat beklentisini aynı talepte toplayın. Proje bazlı üretim değerlendirmesi ve teklif için ortak bir başlangıç oluşturun."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Az adetli ürünlerde 3D baskıyla küçük seri üretim',summary='İlk ürün onayından tekrarlı siparişe geçerken dosya sürümü, yüzey beklentisi ve örnek kabulünü aynı sipariş kaydında tutun.',sections='[{"title":"Pilot partiyi öğrenme aşaması olarak planlayın","body":"Pilot partide rastgele yalnızca bir parçaya bakmak yerine hangi özelliklerin her parçada kontrol edileceğini belirleyin. Ürün üzerindeki yön işareti, delik erişimi ve eşleşen bileşene oturma gibi maddeler sevkiyat öncesi listede yer alabilir."},{"title":"Tekrar siparişin referansını dondurun","body":"Onaylanan model, renk, üretim yönü ve son işlem kapsamı sipariş kimliğiyle ilişkilendirilmelidir. Önceki numunenin elde bulunması tekrar kontrolünü kolaylaştırır. Malzeme veya tasarım değiştiğinde bunu aynı parçanın sıradan tekrar baskısı gibi ele almayın; değişikliğin kullanım üzerindeki etkisini yeniden değerlendirin."}]'::jsonb,faq='[{"q":"Az adet her durumda daha ekonomik midir?","a":"Birim maliyet kadar hazırlık, modelleme, kontrol ve son işlem de önemlidir. Karşılaştırma aynı adet, aynı yüzey ve aynı kabul kapsamıyla yapılmalıdır; yalnızca baskı ağırlığı yeterli olmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Az sayıda parçanın bir araya gelmesiyle daha önce görülmeyen montaj veya paketleme sorunları ortaya çıkabilir.","takeaways":["İlk parti ve tekrar sipariş adetleri","Onay referansı olarak saklanacak numune","Kontrol edilecek ürün özellikleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/cozumler/kucuk-seri-uretim' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Küçük seri üretim","summary":"Kalıp yatırımından önce veya düşük adetli ihtiyaçlarda değerlendirilebilecek üretim alternatifleri.","sections":[{"title":"Projenizin başlangıcı","body":"Tasarımınızı fiziksel olarak değerlendirin. Model revizyonu, montaj kontrolü ve sonraki iterasyon için proje kapsamını birlikte belirleyelim."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ar-Ge prototipinde kapsam, revizyon ve satın alma planı',summary='Ürün geliştirme ekibiyle satın almanın aynı dosya sürümü, numune amacı ve teslimat beklentisi üzerinden ilerlemesini sağlayın.',sections='[{"title":"Teknik onay ile sipariş onayını ayırın","body":"Teknik sorumlu, bütçe sorumlusu ve teslim alacak kişi ayrı alanlarda belirtilmelidir. Dosya adındaki revizyon ile teklif ekindeki revizyon eşleştiğinde değişikliğin hangi siparişi etkilediği görülebilir."},{"title":"Karar kayıtlarını numuneye bağlayın","body":"Bir toplantıda alınan kararın üretime yansıması için değişen yüzeyi, gerekçeyi ve yeni kontrolü yazın. Eski dosyayı sessizce aynı isimle değiştirmek yerine sürüm kaydı oluşturun. Numune kabulünden sonra istenen ek yüzey işi veya yeni parça adedi, ilk kapsamdan ayrı değerlendirilecek bir değişiklik olarak görünür olmalıdır."}]'::jsonb,faq='[{"q":"Gizli ürün geliştirme dosyaları nasıl ele alınır?","a":"Dosya paylaşımından önce gizlilik sözleşmesi talebini teklif formunda belirtebilirsiniz. Paylaşılacak veri kapsamı ve yetkili kişiler proje görüşmesinde netleştirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir tasarımcının geometrik modeli uygun bulması, satın alma ekibinin fiyat ve teslim kapsamını kabul ettiği anlamına gelmez.","takeaways":["Teknik ve ticari karar sorumluları","Model sürümü ve açık revizyon listesi","Numune amacı ile sonraki karar tarihi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/cozumler/kurumsal-proje-yonetimi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Kurumsal proje ve tedarik süreci","summary":"Teknik ekip, satın alma ve üretim arasında dosya, onay ve tekrar sipariş akışını aynı proje kapsamına bağlayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Talep ve kapsam","body":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"title":"Numune ve revizyon","body":"İlk numunenin kabul maddelerini ve onay sorumlusunu belirleyin. Değişiklik taleplerini tek bir revizyon listesinde toplayın. Yeni geometri, adet veya teslim koşulu fiyat ve takvimin tekrar değerlendirilmesini gerektirebilir."},{"title":"Tekrar sipariş","body":"Onaylı dosyanın parça kodunu ve revizyonunu saklayın. Tekrar siparişte yalnızca eski fotoğraf yerine bu referansı kullanın. Çalışma ortamı veya kullanım amacı değiştiyse teknik değerlendirmeyi yenileyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Montaj istasyonu için konumlandırma fikstürü',summary='İş parçasının dayama yüzeylerini, yükleme yönünü ve operatör hareketini birlikte tanımlayan fikstür tasarımı.',sections='[{"title":"Referans noktalarını iş parçasından seçin","body":"İş parçasında her çevrimde ulaşılabilen yüzeyleri ve talaş, çapak veya kablo nedeniyle kapanabilen bölgeleri işaretleyin. Tutucunun görevini açıklarken işlem kuvvetinin nereden geldiğini ve hangi yönde aktarıldığını da gösterin."},{"title":"İstasyondaki erişimi numunede kontrol edin","body":"Sıkma kolu, sensör, tornavida ve operatör eli aynı hacmi paylaşabilir. Taslağı makine üzerindeki çalışma alanıyla karşılaştırın; yükleme ve boşaltma sırasında çarpışma olup olmadığını gözleyin. Numune kabulü gerçek çalışma koşullarında yapılacak denemelerin kapsamını içerir; yalnızca masada parçanın oturması yeterli bir üretim onayı değildir."}]'::jsonb,faq='[{"q":"Yıpranan yüzey ayrı değiştirilebilir mi?","a":"Temas elemanları uygun biçimde ayrıştırılabiliyorsa değiştirilebilir insert veya dayama parçası değerlendirilebilir. Bağlantı rijitliği ve servis erişimi bu seçimin parçasıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir fikstür, parçayı rastgele sıkıştırmak yerine tekrarlanabilir referanslara oturtmalıdır.","takeaways":["İstasyonun çalışma alanı ve hareket yönleri","İş parçasının referans yüzeyleri","Temas kuvvetleri ve çevrim beklentisi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/cozumler/montaj-konumlandirma' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Montaj & konumlandırma","summary":"Parçanın konumunu belirlemek, montaj adımlarını düzenlemek ve tekrarlayan işlemleri desteklemek için.","sections":[{"title":"Projenizin başlangıcı","body":"Montaj bağlantıları, kablo yönlendirmeleri ve özel aparat ihtiyaçlarını sistem geometrisiyle birlikte ele alıyoruz."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Numune kontrolleri için özel test ve tutma aparatları',summary='Ölçüm veya fonksiyon denemesinde parçanın konumunu sabitleyen düzenekleri kontrol yöntemiyle birlikte tarif edin.',sections='[{"title":"Ölçülecek özellik önce belirlenir","body":"Ölçüm probunun erişeceği bölge, referans ekseni ve parçanın serbest kalması gereken yüzeyler ayrı gösterilmelidir. Esnek bir parçanın sıkılması ölçülen sonucu değiştirebilir; yerleştirme kuvveti ve temas şekli kontrol prosedüründe açıklanır."},{"title":"Doğru ve hatalı örnekleri ayırın","body":"Geçer-geçmez kontrolü düşünülüyorsa sınırların hangi teknik resimden geldiği belli olmalıdır. Kabul edilen ve reddedilen örneklerle yapılacak denemeyi planlayın. Aparatın aşınması, sıcaklık değişimi ve operatörün uyguladığı kuvvet sonuca etki edebileceğinden kalibrasyon veya doğrulama gereksinimi yetkili kalite ekibi tarafından belirlenir."}]'::jsonb,faq='[{"q":"Baskı aparatını ölçüm mastarı olarak kullanabilir miyiz?","a":"Ancak ölçüm gereksinimi, tolerans bütçesi ve doğrulama yöntemi birlikte değerlendirildikten sonra karar verilir. Basılmış olması veya örneğe oturması tek başına metrolojik yeterlilik göstermez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir parçayı tutan aparat kendiliğinden ölçüm cihazı hâline gelmez.","takeaways":["Kontrol edilen özellik ve teknik resim","Ölçüm cihazının erişim hacmi","Kabul ve red örnekleriyle deneme planı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/cozumler/test-kontrol-aparatlari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Test & kontrol aparatları","summary":"Fonksiyon denemeleri ve proje içi kontrollerde kullanılacak özel tutucular ve prototip düzenekler.","sections":[{"title":"Projenizin başlangıcı","body":"Kart ölçüleri, bağlantı arayüzleri ve havalandırma gereksinimleri üzerinden muhafaza tasarımı ve prototipleme."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Sensör ve otomasyon ekipmanı için cihaz muhafazası',summary='Kablo rakoru, pano bağlantısı, sensör yönü ve bakım erişimini birlikte değerlendiren uygulamaya özel gövdeler.',sections='[{"title":"İç yerleşimi saha bağlantısıyla birlikte kurun","body":"Ray, profil veya panel bağlantısının ölçülerini ekleyin. Kablo çıkışının çekme yönünü, konektör sökme alanını ve servis sırasında kapağın açılacağı mesafeyi gösteren fotoğraflar teklif belirsizliğini azaltır."},{"title":"Koruma beklentisini açıkça yazın","body":"Toz, sıvı sıçraması, temizleyici veya sıcak yüzeye yakınlık varsa bunları yalnızca “endüstriyel ortam” olarak özetlemeyin. Belirli bir IP sınıfı, alev davranışı ya da elektriksel özellik gerekiyorsa ilgili gereksinim ve doğrulama kapsamı baştan değerlendirilir. Görünüşü kapalı bir kutu bu sınıfları otomatik sağlamaz."}]'::jsonb,faq='[{"q":"Mevcut kutuya yeni kapak yapılabilir mi?","a":"Kapak yatağı, conta yüzeyi ve bağlantı noktalarının ölçüleri gerekir. Eski gövdeyle ilk eşleştirme denemesi, tüm muhafazayı yeniden tasarlamaya gerek olup olmadığını gösterir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Cihaz gövdesi masa üzerindeki kartı taşıdığı kadar sahadaki kablo ve montaj bağlantılarını da karşılamalıdır.","takeaways":["Saha montajının ölçülü fotoğrafları","Kablo rakoru ve konektör çeşitleri","Ortam koşulları ve istenen doğrulamalar"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/cozumler/cihaz-muhafazalari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Cihaz muhafazaları","summary":"Elektronik kart, sensör ve ekipman yerleşimine göre tasarlanan plastik gövdeler ve kapaklar.","sections":[{"title":"Projenizin başlangıcı","body":"Mevcut örnek, teknik çizim veya saha ölçülerinden başlayarak üretim uygunluğunu birlikte değerlendiriyoruz."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Bakım ekiplerine özel parça tutucu ve işlem yardımcıları',summary='Sökme, ayırma ve yeniden montaj sırasında kullanılan yardımcı geometrileri bakım adımına göre tasarlayın.',sections='[{"title":"Bakım hareketini tarif edin","body":"Yardımcının bakımın hangi anında takılıp çıkarıldığını gösterin. Temas edeceği yüzeylerde yağ, sıcaklık veya keskin kenar bulunup bulunmadığı; operatörün eldivenle erişimi ve parçanın düşme ihtimali tasarım görüşmesine dâhil edilir."},{"title":"Sarf yüzeyi ve gövdeyi ayrıştırın","body":"Tekrarlanan temas nedeniyle aşınan bir uç için bütün aparatı değiştirmek yerine ayrı bir parça düşünmek mümkün olabilir. Sökülebilir bağlantının karışmaması için parça kodu ve yön bilgisi kullanılır. Deneme sonunda aşınma ve deformasyon gözlemlerini kaydetmek, sonraki revizyonun nedenini görünür kılar."}]'::jsonb,faq='[{"q":"Bu aparatlar kaldırma ekipmanı yerine kullanılabilir mi?","a":"Kaldırma, emniyet kilitleme veya tehlikeli enerjiyi kontrol etme işlevleri bu yardımcı parça kapsamından ayrılır. Böyle bir görev varsa yetkili mühendislik değerlendirmesi ve uygun ekipman gereksinimi açıkça belirtilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir ekipmanı sökmek için kullanılan destek ile sürekli makine üzerinde kalan koruyucu farklı görevler taşır.","takeaways":["Bakım işleminin adım sırası","Geçici ve sürekli temas bölgeleri","Kirlenme, sıcaklık ve erişim koşulları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/cozumler/bakim-yardimcilari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Bakım yardımcıları","summary":"Üretimi destekleyen özel kılavuzlar, koruyucular ve yardımcı plastik parçalar.","sections":[{"title":"Projenizin başlangıcı","body":"Montaj bağlantıları, kablo yönlendirmeleri ve özel aparat ihtiyaçlarını sistem geometrisiyle birlikte ele alıyoruz."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Üretim aparatı için teknik satın alma ve kabul dosyası',summary='Üretim, kalite ve satın alma ekiplerinin aynı fikstür ihtiyacını ve numune kabul koşullarını takip etmesi için kapsam düzeni.',sections='[{"title":"Talebi üretim problemiyle başlatın","body":"Mevcut işlem, gözlenen sorun ve değişmesi beklenen adımı yazın. Teknik resimden farklı saha koşulları varsa bunları işaretleyin; satın alma kalemi ile operatörün ihtiyacı arasında izlenebilir bir ilişki oluşsun."},{"title":"Kabul sorumlusunu önceden belirleyin","body":"İlk numunede kimlerin hangi kontrolleri yapacağı kararlaştırılmalıdır. Üretim ekibi erişimi, kalite ekibi referans ve ölçümü, bakım ekibi sökülebilirliği değerlendirebilir. Kontrol sonucu ve sapmalar aynı revizyon kaydında tutulduğunda tekrar sipariş, yalnızca eski e-postayı bulmaya bağlı kalmaz."}]'::jsonb,faq='[{"q":"Teklifte hangi kontrol hizmetleri yer alır?","a":"Kontrol raporu, ek ölçüm, saha denemesi veya montaj desteği gerekiyorsa ayrı kapsam olarak belirtilir. Bunların tamamının yalnızca parça üretim fiyatına dâhil olduğu varsayılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Aparat ihtiyacını sadece bir parça fotoğrafı olarak göndermek, gerçek iş istasyonunu görünmez bırakır.","takeaways":["İstasyon ve ekipman kimliği","Kritik ölçüler ile kabul yöntemi","Onay verecek üretim ve kalite sorumluları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/cozumler/kurumsal-proje-yonetimi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Kurumsal proje ve tedarik süreci","summary":"Teknik ekip, satın alma ve üretim arasında dosya, onay ve tekrar sipariş akışını aynı proje kapsamına bağlayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Talep ve kapsam","body":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"title":"Numune ve revizyon","body":"İlk numunenin kabul maddelerini ve onay sorumlusunu belirleyin. Değişiklik taleplerini tek bir revizyon listesinde toplayın. Yeni geometri, adet veya teslim koşulu fiyat ve takvimin tekrar değerlendirilmesini gerektirebilir."},{"title":"Tekrar sipariş","body":"Onaylı dosyanın parça kodunu ve revizyonunu saklayın. Tekrar siparişte yalnızca eski fotoğraf yerine bu referansı kullanın. Çalışma ortamı veya kullanım amacı değiştiyse teknik değerlendirmeyi yenileyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Tasarım alternatifleri için mimari kütle maketi',summary='Yerleşim, yükseklik ve boşluk ilişkilerini hızlı değiştirilebilir fiziksel kütleler üzerinden karşılaştırın.',sections='[{"title":"Detay düzeyini tasarım sorusuna bağlayın","body":"Karşılaştırılacak alternatiflerde aynı taban ve aynı ölçeği koruyun. Değişen yalnızca kütle oranıysa çevre modelini sabit tutmak, jüri veya ekip görüşmesindeki karşılaştırmayı anlaşılır hâle getirir."},{"title":"Değiştirilecek parçaları baştan ayırın","body":"Kule yüksekliği, avlu açıklığı veya blok yerleşimi değişecekse bunları çıkarılabilir modüller olarak planlayın. Birleşim izleri görünür cephe yerine daha az dikkat çeken yüzeylere alınabilir. Numunede parçaların takılması, hizalanması ve masada hareket etmemesi değerlendirilir; en ince ayrıntıdan önce ana kompozisyon onaylanır."}]'::jsonb,faq='[{"q":"Aynı taban üzerinde birkaç alternatif gösterilebilir mi?","a":"Alternatiflerin ortak referansları uyuyorsa değiştirilebilir yapı parçaları hazırlanabilir. Her seçeneğin kodu ve yerleşim planı teslim dosyasına eklenmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Erken aşamada cephe doğramalarını çoğaltmak yerine yapının arazideki etkisini okumak daha yararlı olabilir.","takeaways":["Alternatif modellerin aynı koordinatta dosyaları","Okunması istenen kütle ve boşluk ilişkileri","Toplantı masası ve hedef maket boyutu"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/cozumler/mimari-kutle-calismalari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mimari kütle çalışmaları","summary":"Tasarım alternatiflerini fiziksel hacimler ve kütle ilişkileri üzerinden değerlendirmek için.","sections":[{"title":"Projenizin başlangıcı","body":"Kütle ve cephe kararlarını fizikselleştiren, tasarım aşamasına uygun detay seviyesinde maketler."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Satış ofisi ve yatırımcı sunumu için gayrimenkul maketi',summary='Yapı, peyzaj ve dolaşım ilişkilerini ziyaretçinin bakış mesafesine göre anlatan ölçekli proje sunumu.',sections='[{"title":"İzleyicinin göreceği yüzleri seçin","body":"Giriş, sosyal alan, ulaşım bağlantısı ve blok isimleri okunabilir olmalıdır. Her pencerenin aynı yoğunlukta işlenmesi yerine ziyaretçinin kararını etkileyen mekânsal ilişkilere öncelik verilebilir."},{"title":"Sunum donanımını kapsamda ayrı gösterin","body":"Aydınlatma, şeffaf kapak, kaide, etiketler ve taşıma kasası maketin kendisinden ayrı iş kalemleridir. Elektrik bağlantısı veya sökülebilir bölümler varsa erişim yolu çizimde gösterilmelidir. Renk ve yüzey onayı için küçük bir örnek alanın incelenmesi, bütün model tamamlandıktan sonra doğabilecek uyumsuzlukları erken ortaya çıkarır."}]'::jsonb,faq='[{"q":"Görsel render ile maket birebir aynı mı olur?","a":"Renderdaki ışık, kamera ve malzemeler fiziksel ölçekte farklı algılanır. Beklenen görünüşü fotoğraf yerine onaylanmış renk ve yüzey örneği üzerinden tanımlamak daha sağlıklı olur."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Maketin yalnızca ön tarafından mı yoksa etrafından dolaşılarak mı izleneceği kompozisyonu değiştirir.","takeaways":["Sunum mekânı ve izleme yönleri","Vurgulanacak bloklar ve ortak alanlar","Kaide, kapak ve aydınlatma ihtiyacı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/cozumler/gayrimenkul-sunum-maketleri' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Gayrimenkul sunum maketleri","summary":"Projenin yerleşimini, cephe yaklaşımını ve mekânsal ilişkilerini anlatan sunum odaklı modeller.","sections":[{"title":"Projenizin başlangıcı","body":"Yatırımcı ve müşteri sunumlarında projenizin mekânsal ilişkilerini anlatan ölçekli modeller."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Topoğrafya ve yerleşim için arazi maketi',summary='Kotlar, yapı oturumları ve ulaşım izlerini tek referans sisteminde birleştiren okunabilir arazi modelleri.',sections='[{"title":"Kot referansını kaybetmeyin","body":"Kullanılan kot sistemi, kuzey yönü ve proje sınırı paylaşılmalıdır. Aynı anda gereksiz geniş bir çevreyi göstermek, asıl yapı detayını küçültür; model sınırı sunum amacına göre seçilir."},{"title":"Eğim anlatımını ölçekle birlikte çözün","body":"Basamaklı katmanlar ile kesintisiz topoğrafya yüzeyi farklı görsel diller üretir. Küçük ölçekte ince istinat duvarları veya bordürler okunmayabilir; bunların nasıl temsil edileceği tasarım kararıdır. Arazi tabanının parçalı üretiminde birleşim hattının yollar veya doğal sınırlar üzerinde yer alması incelenebilir."}]'::jsonb,faq='[{"q":"Düşey ve yatay ölçek farklı olabilir mi?","a":"Eğimi vurgulamak için farklı ölçekler tercih edilebilir; ancak bu bilinçli bir anlatım kararı olmalı ve sunumda açıkça belirtilmelidir. Aksi hâlde arazi ilişkileri yanlış anlaşılabilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Arazi dosyası ile bina modeli farklı başlangıç kotları kullanıyorsa modelde yapılar havada kalabilir veya zemine gömülebilir.","takeaways":["Kotlu arazi verisi ve kuzey oku","Parsel sınırı ile çevre kapsamı","Yapıların araziye oturma referansı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/cozumler/arazi-yerlesim-modelleri' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Arazi & yerleşim modelleri","summary":"Topoğrafya, yapı ve çevre ilişkisini aynı ölçekte ele alan proje modelleri.","sections":[{"title":"Projenizin başlangıcı","body":"Bir tesisin planını, operasyon alanlarını ve yerleşimini ortak bir fiziksel model üzerinden konuşun."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Tesis yerleşimi ve operasyon anlatımı için ölçekli maket',summary='Üretim alanları, ekipman kümeleri ve dolaşım koridorlarını toplantı veya ziyaretçi sunumunda ortak bir modelle gösterin.',sections='[{"title":"İşlevi geometriden önce sınıflandırın","body":"Hangi ünitenin ne işe yaradığı, malzemenin hangi yönde hareket ettiği ve alanların birbirine nasıl bağlandığı anlaşılmalıdır. Renk kodları kullanılıyorsa tesisin kendi alan tanımlarıyla eşleştirin; açıklama anahtarını modelden ayrı unutmayın."},{"title":"Güncellenecek bölgeleri modüler kurun","body":"Ekipman yer değiştirecekse tek parçalı sabit bir model kısa sürede eskiyebilir. Değişebilir üniteler için ortak yerleşim referansları ve saklama bölmeleri planlanabilir. Ziyaretçi gösterimi ile mühendislik tartışması aynı ayrıntı seviyesini gerektirmez; teklif öncesinde baskın kullanım biçimi belirlenmelidir."}]'::jsonb,faq='[{"q":"Maket gerçek üretim akışını doğrular mı?","a":"Maket ilişkileri anlatmayı kolaylaştırır; proses kapasitesi, güvenli mesafeler veya operasyon uygunluğu için kendi başına mühendislik doğrulaması oluşturmaz. Bu bilgiler yetkili proje verisinden gelmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir tesiste her makinenin tüm mekanik ayrıntıları maket ölçeğinde gerekli değildir.","takeaways":["Yerleşim planının güncel revizyonu","Gösterilecek ekipman sınıfları","Sökülüp değişecek alanların listesi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/cozumler/endustriyel-tesis-maketleri' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Endüstriyel tesis maketleri","summary":"Tesis yerleşimi, ekipman ilişkileri ve operasyon alanlarını anlatmaya yönelik ölçekli modeller.","sections":[{"title":"Projenizin başlangıcı","body":"Kütle ve cephe kararlarını fizikselleştiren, tasarım aşamasına uygun detay seviyesinde maketler."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mimari makette dosya dondurma ve sunum teslim planı',summary='Mimar, proje geliştirici ve sunum ekibinin ölçek, görünür detay ve son revizyon kararlarını aynı takvimde buluşturun.',sections='[{"title":"Sunum tarihinden geriye doğru planlayın","body":"Birleştirme, boya veya yüzey işi, ambalaj ve taşıma adımlarını ayrı konuşun. Tasarım ekibi model değişikliğini sürdürecekse hangi tarihte hangi bölümün dondurulacağı belirtilmeli; geç gelen cephe revizyonunun etkisi görünür olmalıdır."},{"title":"Onayları fiziksel örneğe dayandırın","body":"Ölçek kararını yalnızca ekrandaki renderla vermek yerine toplam taban ölçüsünü masada işaretleyin. Renk ve detay için temsilî bir cephe veya kütle parçası incelenebilir. Onaylanan görünüş, kaide metni ve çevre kapsamını tek teslim listesinde toplamak, farklı ekiplerin farklı versiyonları beklemesini önler."}]'::jsonb,faq='[{"q":"Bina modeli üretim sırasında değişirse ne olur?","a":"Revizyonun etkilediği bölümler ve tamamlanmış işler belirlenerek ek kapsam çıkarılır. Tüm değişikliklerin mevcut takvim ve bedele kendiliğinden sığacağı varsayılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Toplantı günü ile üretimin bitişini aynı tarih olarak düşünmek risk yaratır.","takeaways":["Sunum günü ve mekâna giriş koşulları","Modelin dondurulacak revizyonu","Ölçek, renk ve kaide onay sorumlusu"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/cozumler/kurumsal-proje-yonetimi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Kurumsal proje ve tedarik süreci","summary":"Teknik ekip, satın alma ve üretim arasında dosya, onay ve tekrar sipariş akışını aynı proje kapsamına bağlayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Talep ve kapsam","body":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"title":"Numune ve revizyon","body":"İlk numunenin kabul maddelerini ve onay sorumlusunu belirleyin. Değişiklik taleplerini tek bir revizyon listesinde toplayın. Yeni geometri, adet veya teslim koşulu fiyat ve takvimin tekrar değerlendirilmesini gerektirebilir."},{"title":"Tekrar sipariş","body":"Onaylı dosyanın parça kodunu ve revizyonunu saklayın. Tekrar siparişte yalnızca eski fotoğraf yerine bu referansı kullanın. Çalışma ortamı veya kullanım amacı değiştiyse teknik değerlendirmeyi yenileyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Bulunamayan iç trim ve kapaklar için özel parça',summary='Eksik kapak, dekoratif panel ve güvenlik kritik olmayan iç trim parçalarını montaj yuvasıyla birlikte değerlendirin.',sections='[{"title":"Ön yüz kadar arka yüzü de gösterin","body":"Kırık parçanın her iki yüzünü ve takılacağı yuvayı fotoğraflayın. Karşı parça üzerindeki aşınma veya sonradan yapılmış tamir, ölçünün nasıl yorumlanacağını değiştirebilir."},{"title":"Küçük bağlantıyı önce deneyin","body":"Büyük ve görünür parçanın tamamına yüzey işi uygulamadan önce kritik geçme bölgesi denenebilir. Takma yönü, tutunma ve sökme hareketi ayrı kontrol edilir. Renk, doku ve parlaklık beklentisini ayrıca belirtin; orijinal üreticinin yüzey dokusu ve malzemesi, yalnızca fotoğraftan birebir garanti edilemez."}]'::jsonb,faq='[{"q":"Orijinal parçanın aynısı mı üretilir?","a":"Amaç ihtiyaca uygun özel bir parça geliştirmektir. Üretici onayı, orijinal parça niteliği veya güvenlik performansı kendiliğinden oluşmaz; görünüş ve bağlantı beklentisi ayrı değerlendirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir kapağın görünen yüzü doğru olsa bile arkadaki tırnak, pim veya menteşe uymadığında parça çalışmaz.","takeaways":["Ön/arka yüz ve montaj yuvası fotoğrafları","Kırık tırnakların durumu","İstenen renk, doku ve sökme sıklığı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/cozumler/ic-trim-kapaklar' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"İç trim & kapaklar","summary":"Araç içi estetik ve işlevsel plastik parçaların örnek veya ölçü üzerinden değerlendirilmesi.","sections":[{"title":"Projenizin başlangıcı","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='İki bileşen arasında ölçüye özel plastik adaptör',summary='Farklı bağlantı arayüzlerini eşleştirmek için merkez mesafelerini, eksenleri ve yük yönünü birlikte tanımlayın.',sections='[{"title":"Her iki arayüzü de ölçün","body":"Karşılıklı yüzlerin konumu, delik eksenleri, bağlanma derinliği ve çevredeki boşluklar birlikte görülmelidir. Birbirine yakın görünen diş veya geçmeler aynı olmayabilir; mevcut bağlantı elemanlarının bilgisi teknik çizime eklenir."},{"title":"Hareket ve kullanım yükünü açıklayın","body":"Parçanın sabit kalacağı mı, döneceği mi veya düzenli sökülüp takılacağı mı kararları etkiler. Montaj sırasında uygulanan kuvvet ve kullanım esnasındaki yük farklı olabilir. İlk numunede iki tarafın ayrı ayrı oturması ve birlikte monte edildiğinde hizanın korunması değerlendirilir."}]'::jsonb,faq='[{"q":"Fotoğraftan adaptör boyutları çıkarılabilir mi?","a":"Fotoğraf bağlantı biçimini anlamaya yardım eder; kritik ölçülerin yerine geçmez. Ölçü listesi veya fiziksel numune gerektiğinde modelleme başlamadan önce hangi verinin eksik olduğu belirtilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Adaptör tarifinde yalnızca bir ucun çapını bilmek yeterli olmaz.","takeaways":["İki bağlantının ölçülü çizimleri","Eksenler arası konum ve boşluk","Montaj elemanları ve kullanım yükü"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/cozumler/ozel-adaptorler' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Özel adaptörler","summary":"Mevcut iki bileşen arasındaki geometrik uyum için projeye özel plastik adaptörler.","sections":[{"title":"Projenizin başlangıcı","body":"Yeni bir gövde, bağlantı veya adaptör fikrini montaj ilişkilerini test edebileceğiniz fiziksel modele dönüştürün."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Güvenlik kritik olmayan uygulamalar için plastik tutucular',summary='Kablo, hafif aksesuar ve yardımcı bileşenlerin yerini düzenleyen özel tutucuları takma ve sökme davranışına göre planlayın.',sections='[{"title":"Tutulan nesnenin hareketini tanımlayın","body":"Tutulan parçanın ağırlığı, çekilme yönü ve titreşim ihtimali belirtilmelidir. Bağlantının hangi yüzeye yapılacağı ve çevredeki hareketli elemanlar görülmeden sadece dış ölçüye göre tutucu şekillendirmek eksik kalır."},{"title":"Kullanıcı müdahalesini hesaba katın","body":"Tutucu elle sökülecekse parmağın erişeceği alan, aletle sökülecekse alet boşluğu gerekir. Esnek tırnaklarda açılma miktarı ve tekrar sayısı numune planına girer. Yapıştırıcı, vida veya sıkı geçme gibi sabitleme yöntemlerinin her biri ayrı yüzey ve uygulama koşulu ister."}]'::jsonb,faq='[{"q":"Araçta veya makinede her tutucu yenilenebilir mi?","a":"Emniyet sistemi, sürüş kontrolü, taşıyıcı bağlantı veya koruyucu işlevi olan parçalar bu genel yardımcı tutucu kapsamından ayrılır. Parçanın görevi açıklanmadan yalnızca benzer geometriyle karar verilmez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir kabloyu yönlendiren klips ile bir kutuyu taşıyan braket aynı tasarım problemi değildir.","takeaways":["Tutulacak nesnenin fotoğrafı ve ağırlığı","Sabitleme yüzeyi ve bağlantı yöntemi","Sökme hareketi ve tekrar kullanım ihtiyacı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/cozumler/baglanti-sabitleme' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Bağlantı & sabitleme","summary":"Güvenlik kritik olmayan uygulamalar için plastik tutucular, yönlendiriciler ve bağlantı parçaları.","sections":[{"title":"Projenizin başlangıcı","body":"Eskiyen veya katalogda bulunmayan yardımcı plastik parçalar için üretim alternatiflerini ele alıyoruz."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Eski veya kırık örnekten üretilebilir parça modeli',summary='Aşınmış numunedeki mevcut şekli, parçanın olması gereken bağlantı geometrisinden ayırarak yeni model oluşturun.',sections='[{"title":"Hasarı tasarım verisi gibi kopyalamayın","body":"Sağlam simetrik bölümler, karşı parçanın yatağı ve varsa eski fotoğraflar eksik alanı anlamaya yardımcı olur. Her yeniden kurulan yüzey için hangi referansın kullanıldığı kaydedilebilir."},{"title":"Uyumu küçük bir test parçasıyla sınayın","body":"Parçanın tamamı yerine yalnızca bağlantı bölgesini içeren bir deneme baskısı, ölçü yorumunun doğruluğunu gösterebilir. Bu kontrol dış görünüş işinden önce yapılır. Onaylanan bağlantı geometrisi ana modele işlendiğinde yeni numune hem montaj hem kullanım yönünden değerlendirilir."}]'::jsonb,faq='[{"q":"Parça tamamen kayıpsa çalışılabilir mi?","a":"Montaj yuvası, eşleşen bileşen ve işlev tarifiyle yeni bir tasarım değerlendirilebilir. Bu süreç mevcut parçanın kopyasını çıkarmaktan farklıdır; eksik ölçüler ve varsayımlar başlangıçta görünür kılınır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Tarama, eldeki yüzeyi kaydeder; kırılmış bir tırnağın veya erimiş bir kenarın başlangıç biçimini kendiliğinden bilemez.","takeaways":["Sağlam yüzeyler ve hasarlı bölgeler","Karşı parçanın yuva ölçüleri","Varsa eski fotoğraf veya parça kodu"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/cozumler/ornekten-parca-modelleme' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Örnekten parça modelleme","summary":"Mevcut parça, eskiz veya ölçü setinden yeni üretime yönelik dijital model geliştirme.","sections":[{"title":"Projenizin başlangıcı","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"3D modelleme ile kapsamı belirleyin","body":"Teknik çizim, numune veya ölçülerden başlayarak bağlantılar ve kritik boyutlar değerlendirilir. Kullanım amacı ile istenen çıktı birlikte tanımlanır."},{"title":"Numune varsa 3D taramayı değerlendirin","body":"Mevcut parçanın yüzey geometrisinin alınması, CAD modelleme için başlangıç olabilir. Taranabilirlik ve eksik alanlar fotoğraf veya numune üzerinden incelenir."},{"title":"3D baskı ile fiziksel doğrulama","body":"Malzeme, adet ve üretim yönü uygulamanıza göre seçilir. İlk numunede form ve montaj değerlendirmesi yapıldıktan sonra tekrar üretim kapsamı kararlaştırılır."}],"faq":[],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Özel yedek parçada numune, revizyon ve tekrar sipariş',summary='Servis talebini tek bir parça kimliği, montaj örneği ve kabul kaydıyla takip edilebilir hâle getirin.',sections='[{"title":"Benzer görünen parçaları karıştırmayın","body":"Varsa parça kodunu, cihaz modelini ve söküldüğü konumu kaydedin. Farklı numuneleri tek poşette etiketsiz göndermek yerine her birini fotoğraf ve talep kaydıyla eşleştirin."},{"title":"Son onayı gerçek montaj üzerinden verin","body":"Tekrar üretime geçmeden önce hangi numunenin hangi cihazda denendiği bilinmelidir. Uyan bir parça ile sonradan düzeltilen dosya aynı kayıt sanılmamalı; revizyon ve tarih birlikte tutulmalıdır. İlk denemede görülen boşluk, sürtme veya sökme zorluğu yeni dosyaya işlenene kadar açık bulgu olarak kalır."}]'::jsonb,faq='[{"q":"Bir parçanın dosyası sonraki siparişe referans olur mu?","a":"Dosyanın sürümü ve onay numunesi tanımlandığında tekrar talebi daha açık hazırlanabilir. Malzeme değişikliği veya farklı montaj yuvası olduğunda önceki onayın kapsamı yeniden değerlendirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Aynı araç veya cihaz ailesinde üretim yılı ve donanım değişimi bağlantı noktalarını etkileyebilir.","takeaways":["Her numune için kod ve montaj konumu","Cihaz/araç varyant bilgisi","Onaylanan parça ve revizyon kaydı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/cozumler/kurumsal-proje-yonetimi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Kurumsal proje ve tedarik süreci","summary":"Teknik ekip, satın alma ve üretim arasında dosya, onay ve tekrar sipariş akışını aynı proje kapsamına bağlayın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Talep ve kapsam","body":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"title":"Numune ve revizyon","body":"İlk numunenin kabul maddelerini ve onay sorumlusunu belirleyin. Değişiklik taleplerini tek bir revizyon listesinde toplayın. Yeni geometri, adet veya teslim koşulu fiyat ve takvimin tekrar değerlendirilmesini gerektirebilir."},{"title":"Tekrar sipariş","body":"Onaylı dosyanın parça kodunu ve revizyonunu saklayın. Tekrar siparişte yalnızca eski fotoğraf yerine bu referansı kullanın. Çalışma ortamı veya kullanım amacı değiştiyse teknik değerlendirmeyi yenileyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Projenin kullanım amacını, parça listesini ve hedef tarihini paylaşın. Modelleme, tarama, üretim ve son işlem kalemlerini ayrı değerlendirin. Teklifte hangi dosya ve fiziksel çıktıların teslim edileceği açıkça belirtilmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün formu ve ergonomi denemelerinde PLA',summary='Görünüş, elde tutuş ve hacim karşılaştırması yapılan erken ürün prototiplerinde PLA seçimini kullanım amacıyla sınırlandırın.',sections='[{"title":"İlk tasarım sorusuna odaklanın","body":"PLA; form modelleri ve sunum numuneleri için değerlendirilen bir seçenektir. Ancak renkli ve düzgün görünen bir örnek, sıcak ortamda ya da sürekli yük altında aynı davranışı gösterecek diye kabul edilmez."},{"title":"Görünüş numunesinden işlev numunesine geçin","body":"Kapak tırnağı, vida yatağı veya bükülen kol gibi bölümler devreye girdiğinde malzeme kararı yeniden ele alınmalıdır. İlk PLA numunesinde tespit edilen ergonomi değişikliklerini kaydedin; fonksiyon denemesinde kullanılacak malzeme ve üretim yönünü ayrı onaylayın. Böylece yalnızca şekil için alınmış bir karar son ürün şartı hâline gelmez."}]'::jsonb,faq='[{"q":"PLA numunesini ürünün son malzemesi sayabilir miyim?","a":"Ancak gerçek kullanım koşulları ayrıca değerlendirilirse. İlk numunenin amacı hacim ve tutuş kontrolüyse bundan ömür, ısı veya darbe performansı sonucu çıkarılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir kumanda gövdesinin elde nasıl durduğunu anlamak için nihai ürün malzemesiyle başlamanız gerekmeyebilir.","takeaways":["Numunenin yanıtlayacağı form sorusu","Beklenen temas ve yük durumu","Görünüş ile fonksiyon denemelerinin ayrımı"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/pla_2062"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/malzemeler/pla' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"PLA","summary":"Form ve sunum prototipleri 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim için değerlendirme","body":"Bir tasarımı doğrulamak, montajı kolaylaştırmak veya az adetli bir ihtiyacı karşılamak için. Üretim yöntemini kullanım koşulları, adet ve hedeflenen işlevle birlikte değerlendiriyoruz."},{"title":"Kullanım yaklaşımı","body":"Boyutsal görünüm ve form denemeleri için değerlendirilebilir. Sıcaklık, güneş ve yük altında kullanım ayrıca incelenmelidir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Montaj prototiplerinde PETG değerlendirmesi',summary='Kapak, bağlantı yuvası ve yardımcı gövde denemelerinde PETG adayını geometri ve kullanım koşullarıyla birlikte karşılaştırın.',sections='[{"title":"Geçme davranışı tasarıma bağlıdır","body":"Esneme yolu, duvar kalınlığı ve baskı yönü takma davranışını etkiler. Bir kutu kapağında bütün gövdeyi üretmeden kritik geçme kesitinin denenmesi, ölçü kararını daha küçük bir numuneyle görünür kılar."},{"title":"Yüzey beklentisini bağlantıdan ayırın","body":"Şeffaflık, parlaklık veya renk beklentisi varsa kullanılacak gerçek filament ve örnek yüzey üzerinden konuşulmalıdır. Filamentin saydam görünmesi baskı parçasının optik şeffaf olacağını göstermez. Montaj testiyle yüzey onayını ayrı kaydetmek, birindeki başarının diğerinin yerine geçmesini önler."}]'::jsonb,faq='[{"q":"PETG ile esnek bir tırnak tasarlanabilir mi?","a":"Tırnak boyu, kalınlığı, hareket miktarı ve tekrar beklentisi bilinirse numune çalışması değerlendirilebilir. Malzeme adını tek başına tasarım ölçüsü olarak kullanmak doğru olmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"PETG kullanmak, her tırnağın veya sıkı geçmenin otomatik çalışacağı anlamına gelmez.","takeaways":["Takma ve çıkarma hareketinin videosu","Kritik geçme bölgesinin ölçüleri","Renk veya saydamlık için fiziksel referans"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/petg_2059"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/malzemeler/petg' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"PETG","summary":"İşlevsel prototipler ve muhafazalar 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim için değerlendirme","body":"Bir tasarımı doğrulamak, montajı kolaylaştırmak veya az adetli bir ihtiyacı karşılamak için. Üretim yöntemini kullanım koşulları, adet ve hedeflenen işlevle birlikte değerlendiriyoruz."},{"title":"Kullanım yaklaşımı","body":"Tokluk ve işlenebilirlik beklentisi olan uygulamalarda değerlendirilir. Şeffaflık ve yüzey sonucu renk, geometri ve baskı ayarına bağlıdır."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün gövdesi prototipinde ABS ne zaman konuşulur?',summary='ABS talebini yalnızca malzeme adıyla değil; gövde boyutu, kullanım sıcaklığı ve yüzey beklentisiyle birlikte değerlendirin.',sections='[{"title":"Büyük gövdede geometrik kararlılığı düşünün","body":"Gövdenin bütün olarak mı bölünerek mi hazırlanacağı; bağlantı çizgileri ve görünür yüzler üzerinden kararlaştırılır. Son ürününüz enjeksiyon ABS olacak diye ilk baskının aynı malzeme adına sahip olması yeterli bir eşdeğerlik kanıtı değildir."},{"title":"Son işlemi ölçü planına dâhil edin","body":"Zımpara, boya veya başka bir yüzey işlemi isteniyorsa kritik bağlantılar ve oturma yüzeyleri işaretlenmelidir. Görünüş iyileştirmesi yapılırken parça kenarı veya tırnak geometrisi değişebilir. Prototipin hangi ölçülerinin son işlemden önce, hangilerinin bitmiş durumda değerlendirileceği teklif kapsamını netleştirir."}]'::jsonb,faq='[{"q":"Enjeksiyon ABS parça ile basılmış ABS aynı mı davranır?","a":"Üretim yöntemi, katman yönü ve gerçek malzeme formülasyonu farklıdır. Karşılaştırma, malzeme adının benzerliği üzerinden değil projenin deneme ve kabul koşulları üzerinden yapılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Geniş düz yüzeyler, köşeler ve ince duvarlar üretim sırasında farklı davranabilir.","takeaways":["Gövde boyutu ve görünür birleşimler","Kullanım sıcaklığına ilişkin proje verisi","Boya ve yüzey işlemi kapsamı"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/filament-material-guide"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/malzemeler/abs' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"ABS","summary":"Gövde ve teknik parça denemeleri 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim için değerlendirme","body":"Bir tasarımı doğrulamak, montajı kolaylaştırmak veya az adetli bir ihtiyacı karşılamak için. Üretim yöntemini kullanım koşulları, adet ve hedeflenen işlevle birlikte değerlendiriyoruz."},{"title":"Kullanım yaklaşımı","body":"Isıl koşullar ve boyutsal kararlılık gereksinimiyle birlikte ele alınır. Büyük geometrilerde çekme ve üretim koşulları planlamayı etkiler."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Dış ortam ürün prototipleri için ASA',summary='Açıkta kullanılacak gövde ve aksesuar tasarımlarında güneş, sıcaklık, bağlantı ve yüzey gereksinimlerini beraber ele alın.',sections='[{"title":"Dış ortamı tek kelimeyle bırakmayın","body":"Kullanım yeri, gölge durumu, renk ve ısı kaynaklarına yakınlık açıklanmalıdır. ASA dış ortam adayları arasında değerlendirilse de belirli kullanım ömrü veya renk kararlılığı için gerçek malzeme verisi ve test kapsamı gerekir."},{"title":"Kablo ve su yollarını modelde inceleyin","body":"Dış ortama yönelik bir gövdede kapak, vida ve kablo açıklıkları ayrı önem taşır. Birleşim yönünü ve su birikebilecek cepleri tasarım aşamasında gözden geçirin. Sızdırmazlık talebi varsa yalnızca polimer seçmek yeterli değildir; bağlantı, conta ve doğrulama yöntemi de proje konusudur."}]'::jsonb,faq='[{"q":"ASA seçmek dış ortam onayı anlamına gelir mi?","a":"Hayır; malzeme bir tasarım girdisidir. Kullanım yeri, gövde bağlantıları ve istenen koruma seviyesi ayrıca değerlendirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir balkon sensörü ile gün boyunca doğrudan güneş altında kalan bir muhafaza aynı koşulları görmez.","takeaways":["Güneşe ve yağmura maruz kalma biçimi","Kablo girişleri ile kapak birleşimi","Renk ve beklenen bakım aralığı"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/asa_1809"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/malzemeler/asa' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"ASA","summary":"Dış ortam için değerlendirilen parçalar 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim için değerlendirme","body":"Bir tasarımı doğrulamak, montajı kolaylaştırmak veya az adetli bir ihtiyacı karşılamak için. Üretim yöntemini kullanım koşulları, adet ve hedeflenen işlevle birlikte değerlendiriyoruz."},{"title":"Kullanım yaklaşımı","body":"Dış ortamda UV ve sıcaklık koşulları önem taşır. Malzeme seçimi tek başına kullanım ömrü garantisi değildir; geometri ve yük de incelenir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Yumuşak temas ve kavrama prototipleri için TPU',summary='Kavrama yüzeyi, tampon ve esnek kılıf fikirlerini sertlik beklentisi ve sıkışma davranışı üzerinden tarif edin.',sections='[{"title":"Yumuşaklık için fiziksel referans verin","body":"Benzer sertlikte bir örnek, sıkışacağı mesafe ve temas edeceği yüzey daha anlamlı girdilerdir. TPU ailesinde farklı ürünler bulunduğundan belirli bir sertlik veya kimyasal dayanım, kullanılan ürünün teknik verisiyle doğrulanmalıdır."},{"title":"Esnek parçanın montajını da deneyin","body":"Bir kılıf kolay esneyebilir fakat gövde üzerinde dönebilir veya köşeden çıkabilir. Tutunma yolu, duvar dağılımı ve takma kuvveti numunede gözlenmelidir. Prototipin yüzey hissi ile uzun süre sıkıştıktan sonraki davranışı farklı deneylerdir; kabul listesinde birbirlerinin yerine kullanılmamalıdır."}]'::jsonb,faq='[{"q":"Baskı TPU, kalıplanmış kauçuk yerine doğrudan geçer mi?","a":"Esneklik benzer bir ihtiyacı karşılayabilir; yüzey, sürtünme, sıkışma ve üretim yapısı farklı olabilir. Gerçek temas koşulunda denenmeden doğrudan eşdeğer sayılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"“Silikon gibi” veya “biraz esnek” ifadeleri herkes için aynı hissi anlatmaz.","takeaways":["İstenen his için karşılaştırma örneği","Sıkışma veya esneme miktarı","Temas süresi ve montaj biçimi"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/flexible-materials_2057"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/malzemeler/tpu' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"TPU","summary":"Esnek parça ve temas yüzeyleri 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim için değerlendirme","body":"Bir tasarımı doğrulamak, montajı kolaylaştırmak veya az adetli bir ihtiyacı karşılamak için. Üretim yöntemini kullanım koşulları, adet ve hedeflenen işlevle birlikte değerlendiriyoruz."},{"title":"Kullanım yaklaşımı","body":"Esneklik gerektiren koruyucu, tampon ve kavrama parçalarında değerlendirilebilir. Sertlik derecesi, et kalınlığı ve bağlantı biçimi birlikte seçilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Özel performans isteyen prototiplerde malzeme seçimi',summary='PA, PC ve takviyeli filament adaylarını tek bir üst sınıf gibi değil; belirli kullanım ve üretim gereksinimleriyle değerlendirin.',sections='[{"title":"Özelliği ölçülebilir bir gereksinime çevirin","body":"Polimer ailesinin yanında tam ürün adı ve teknik veri sayfası önemlidir. Takviye bulunması, her yönde daha iyi sonuç veya her geometride uygun baskı anlamına gelmez."},{"title":"Üretilebilirliği performansla birlikte sorgulayın","body":"Seçilen malzemenin makine, kurutma ve son işlem gereksinimi proje kapsamını etkiler. İlk numunede kritik arayüzleri ve ölçülerin zaman içindeki davranışını kontrol edecek bir plan oluşturun. Stok, üretim uygunluğu ve gerekli doğrulamalar değerlendirilmeden özel polimer için kesin termin veya sınırsız uygunluk sözü verilmez."}]'::jsonb,faq='[{"q":"Malzeme adını bilmeden teknik teklif isteyebilir miyim?","a":"Evet; parçanın işlevini ve başarısız olduğu koşulu tarif edin. Aday malzemeler, gerekli ürün verileri ve numune denemeleri bu gereksinimden hareketle belirlenebilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"“Daha sağlam” talebinin hangi sorunu çözdüğü açıklanmalıdır: eğilme, darbe, aşınma, sıcaklık veya boyut kararlılığı birbirinden farklı konulardır.","takeaways":["Çözülecek performans sorunu","Sıcaklık, yük ve temas koşulları","Varsa mevcut malzemenin teknik föyü"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/filament-material-guide"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/malzemeler/muhendislik-polimerleri' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mühendislik polimerleri","summary":"Özel çalışma koşulları 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim için değerlendirme","body":"Bir tasarımı doğrulamak, montajı kolaylaştırmak veya az adetli bir ihtiyacı karşılamak için. Üretim yöntemini kullanım koşulları, adet ve hedeflenen işlevle birlikte değerlendiriyoruz."},{"title":"Kullanım yaklaşımı","body":"Naylon ve katkılı polimerler için malzeme tedariki, kurutma, cihaz uyumu ve kullanım gereksinimleri proje bazında teyit edilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Fikstür yerleşimini denemek için PLA taslak',summary='Üretim aparatının erişim ve yerleşim sorularını düşük riskli bir geometrik numune üzerinde değerlendirin.',sections='[{"title":"İstasyon hacmini önce doğrulayın","body":"Bu numune için PLA konuşulabilir; fakat istasyonun gerçek yükünü taşımaya uygunluk ayrıca değerlendirilmelidir. Geometrik denemeyi, sürekli üretim aparatının malzeme onayı olarak kaydetmemek gerekir."},{"title":"Deneme sonucunu kullanım kapsamıyla etiketleyin","body":"Taslak numuneye yalnızca yerleşim kontrolü için kullanıldığı açıkça yazılabilir. Dayama noktaları ve boşaltma hareketi onaylandığında sonraki numunenin malzemesi, temas kuvvetleri ve ortam sıcaklığı üzerinden seçilir. Bu ayrım, ilk örneğin yanlışlıkla günlük üretimde kalmasını önler."}]'::jsonb,faq='[{"q":"PLA ile üretim fikstürü teslim edilir mi?","a":"Karar uygulama koşullarına bağlıdır. Yalnızca şekli doğrulanan bir taslağın üretim çevrimine uygun olduğu varsayılmaz; görev ve kabul yöntemi teknik kapsamda belirtilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir fikstürün yüksekliği, operatör eline kalan mesafe ve takım erişimi ilk taslakta görülebilir.","takeaways":["Yerleşim denemesinin sınırı","İstasyon sıcaklığı ve kuvvet bilgisi","Taslağı kullanacak ekip ve test adımı"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/pla_2062"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/malzemeler/pla' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"PLA","summary":"Form ve sunum prototipleri 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür için değerlendirme","body":"Üretim ve bakım ekiplerinin kullanım senaryosuna özel parçalar. Geometri, yük, ortam koşulları ve montaj ilişkisi değerlendirilerek üretim kapsamı netleştirilir."},{"title":"Kullanım yaklaşımı","body":"Boyutsal görünüm ve form denemeleri için değerlendirilebilir. Sıcaklık, güneş ve yük altında kullanım ayrıca incelenmelidir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Üretim yardımcılarında PETG için seçim soruları',summary='Hafif muhafaza ve yardımcı tutucularda PETG kararını temas yükü, temizlik biçimi ve bağlantı geometrisiyle verin.',sections='[{"title":"Yükün sürekliliğini açıklayın","body":"Kuvvetin yönü, süresi ve parçanın sabitleneceği yüzey talepte yer almalıdır. Parça numunesiyle yapılacak değerlendirme, gerçek kullanım süresini temsil edecek şekilde planlanır."},{"title":"İşletmedeki kimyasal temasını yazın","body":"Temizleyici, yağ veya proses sıvısının adı ve temas biçimi malzeme görüşmesine dâhildir. Genel olarak “kimyasala dayanıklı” denmesi yerine kullanılacak filamentin üretici verisi incelenir. Tasarımda drenaj ve kolay temizlenebilir yüzey gereksinimi bulunuyorsa bunlar ayrıca modelleme girdisi olur."}]'::jsonb,faq='[{"q":"PETG otomatik olarak ESD uygun mudur?","a":"Hayır. ESD gereksinimi varsa uygun ürün tanımı ve doğrulama planı gerekir; sıradan bir polimer ailesi adı elektriksel özellik belgesi yerine geçmez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Kısa süre dokunulan bir dayama ile gün boyunca aynı kuvvet altında kalan bir braket farklı davranış gösterebilir.","takeaways":["Sürekli ve anlık yüklerin ayrımı","Temas eden sıvıların ürün adları","ESD veya başka özel gereksinimler"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/petg_2059"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/malzemeler/petg' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"PETG","summary":"İşlevsel prototipler ve muhafazalar 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür için değerlendirme","body":"Üretim ve bakım ekiplerinin kullanım senaryosuna özel parçalar. Geometri, yük, ortam koşulları ve montaj ilişkisi değerlendirilerek üretim kapsamı netleştirilir."},{"title":"Kullanım yaklaşımı","body":"Tokluk ve işlenebilirlik beklentisi olan uygulamalarda değerlendirilir. Şeffaflık ve yüzey sonucu renk, geometri ve baskı ayarına bağlıdır."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Atölye gövde ve aparatlarında ABS değerlendirmesi',summary='ABS parça talebinde montaj yüzeylerini, ısı kaynaklarını ve son işlem ihtiyacını açık bir teknik kapsamda toplayın.',sections='[{"title":"Isı kaynağına uzaklığı gösterin","body":"Yakın yüzeyler, çalışma süresi ve havalandırma durumu açıklanmalıdır. Malzemenin gerçek ürün verisi ile sahadaki koşul arasındaki ilişki teknik değerlendirmede kurulmalıdır."},{"title":"Bağlantı düzlüğünü numunede izleyin","body":"Geniş bağlantı yüzeylerinin düzlüğü veya deliklerin karşılıklı konumu montajı etkiler. Bu yüzeyleri çizimde işaretlemek, hangi ölçülere odaklanılacağını belirler. Birleşik büyük gövde yerine bölünmüş tasarım düşünülüyorsa bağlantı rijitliği ve bakım sırasında yeniden hizalama da kontrol listesine eklenir."}]'::jsonb,faq='[{"q":"ABS seçimi yangın sınıfı sağlar mı?","a":"Belirli bir alev davranışı isteniyorsa tam malzeme ürününün belgesi ve üretim koşulları incelenmelidir. ABS ifadesi tek başına bu gereksinimi karşılamaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Motor, aydınlatma veya sıcak iş parçasına yakın bir yardımcı parçanın yalnızca ortam sıcaklığı bilinerek seçilmesi eksik kalabilir.","takeaways":["Yakındaki ısı kaynaklarının konumu","Düzlüğü önemli montaj yüzeyleri","Gerekli malzeme belgeleri"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/filament-material-guide"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/malzemeler/abs' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"ABS","summary":"Gövde ve teknik parça denemeleri 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür için değerlendirme","body":"Üretim ve bakım ekiplerinin kullanım senaryosuna özel parçalar. Geometri, yük, ortam koşulları ve montaj ilişkisi değerlendirilerek üretim kapsamı netleştirilir."},{"title":"Kullanım yaklaşımı","body":"Isıl koşullar ve boyutsal kararlılık gereksinimiyle birlikte ele alınır. Büyük geometrilerde çekme ve üretim koşulları planlamayı etkiler."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Dış saha sensör ve muhafazalarında ASA',summary='Açık sahada kullanılacak yardımcı gövdeler için çevre koşullarını montaj ve kablo detaylarıyla birlikte değerlendirin.',sections='[{"title":"Saha konumunu dosyada görünür kılın","body":"Konum fotoğrafı; parçanın yönünü, korunmuş yüzünü ve kablo girişlerini anlamayı sağlar. ASA bir dış ortam adayı olarak ele alınabilir; istenen ömür ve koruma seviyesi için üretici verisi ile uygulama denemesi gerekir."},{"title":"Sökme ve kontrol erişimini bırakın","body":"Dış ortam muhafazası bakım sırasında açılacaksa bağlantı elemanlarının erişimi korunmalıdır. Gövde üzerinde su tutan cepler, kir biriktiren kanallar ve ulaşılamayan vida konumları incelenir. Conta, rakor veya bağlantı donanımının kapsamı ayrı belirtilerek yalnızca plastik parçadan beklenen görev netleştirilir."}]'::jsonb,faq='[{"q":"Dış saha kutusunda IP sınıfını kim doğrular?","a":"İstenen sınıf ve test yöntemi proje kapsamında belirlenir. Malzeme veya çizim seçimi tek başına IP doğrulaması değildir; gerekli değerlendirme yetkili yöntemle yapılmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Çatı, açık depo veya makine dış yüzeyi farklı güneş ve su koşulları taşır.","takeaways":["Saha fotoğrafı ve montaj yönü","Bakım için açılacak yüzeyler","Conta, rakor ve koruma beklentisi"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/asa_1809"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/malzemeler/asa' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"ASA","summary":"Dış ortam için değerlendirilen parçalar 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür için değerlendirme","body":"Üretim ve bakım ekiplerinin kullanım senaryosuna özel parçalar. Geometri, yük, ortam koşulları ve montaj ilişkisi değerlendirilerek üretim kapsamı netleştirilir."},{"title":"Kullanım yaklaşımı","body":"Dış ortamda UV ve sıcaklık koşulları önem taşır. Malzeme seçimi tek başına kullanım ömrü garantisi değildir; geometri ve yük de incelenir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='İş parçasına yumuşak temas eden TPU yardımcıları',summary='Temas pedi, koruyucu uç ve ayırıcı parçaları sıkışma miktarı ve değişim ihtiyacı üzerinden planlayın.',sections='[{"title":"Sıkma kuvvetini pede göre tanımlayın","body":"Uygulanan kuvvet altında ne kadar şekil değiştireceği ve temasın nerede yoğunlaşacağı düşünülmelidir. Fikstürün referans yüzeyi ile koruyucu temas yüzeyini ayrı ele almak, iki farklı görevi aynı malzemeye yüklemeyi önler."},{"title":"Aşınan elemanı değiştirilebilir kurun","body":"Pedin üretim sırasında yerinden çıkmaması ve yenisinin doğru yönde takılması için bağlantı biçimi belirlenir. Çalışma sıvısı, sürtünme ve sıkıştırma süresi numune değerlendirmesine girer. Kullanımdan sonra kalıcı şekil değişimi olup olmadığı gözlenerek bakım veya değişim aralığına veri sağlanır."}]'::jsonb,faq='[{"q":"TPU pad iş parçasını kesin çizmez mi?","a":"Yüzeyde tutulan kir, temas basıncı ve hareket de çizilmeyi etkiler. Koruyucu işlev gerçek yüzey ve temizlik koşullarıyla denenmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Yumuşak bir ped, iş parçasını çizmemeyi amaçlarken konumlandırma hassasiyetini etkileyebilir.","takeaways":["İş parçasının hassas yüzeyi","Sıkıştırma miktarı ve temas süresi","Padin sökülme ve yenilenme yöntemi"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/flexible-materials_2057"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/malzemeler/tpu' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"TPU","summary":"Esnek parça ve temas yüzeyleri 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür için değerlendirme","body":"Üretim ve bakım ekiplerinin kullanım senaryosuna özel parçalar. Geometri, yük, ortam koşulları ve montaj ilişkisi değerlendirilerek üretim kapsamı netleştirilir."},{"title":"Kullanım yaklaşımı","body":"Esneklik gerektiren koruyucu, tampon ve kavrama parçalarında değerlendirilebilir. Sertlik derecesi, et kalınlığı ve bağlantı biçimi birlikte seçilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Fikstürlerde PA, PC ve takviyeli malzeme kararı',summary='Aparatın rijitlik, nem, aşınma ve sıcaklık gereksinimlerini tam malzeme ürünüyle eşleştirin.',sections='[{"title":"Malzeme ailesi yerine ürün verisi isteyin","body":"Ana polimer, takviye oranı ve baskı yönü değerlendirmeye girer. Yük altında şekil değişimi ya da delik çevresindeki hasar gibi belirli bir sorun tarif etmek, yalnızca daha yüksek isimli bir malzeme istemekten daha yararlıdır."},{"title":"Ölçüyü kullanım koşulunda kabul edin","body":"Nem alma ve sıcaklık geçmişi bazı malzemelerde ölçü davranışını etkileyebilir. Numunenin ne zaman, hangi ortamda ve hangi referansla ölçüleceğini kalite planında belirtin. Baskı sonrası işlem veya özel donanım gerekirse bunlar uygunluk değerlendirmesinin parçasıdır; mevcut makine parkıyla üretilebilirlik ayrıca teyit edilir."}]'::jsonb,faq='[{"q":"Takviyeli filament metal fikstürün doğrudan alternatifi mi?","a":"Yük, rijitlik, aşınma, bağlantı ve kabul gereksinimleri karşılaştırılmalıdır. Metal tasarımın aynı geometrisini farklı malzemeyle basmak otomatik eşdeğerlik sağlamaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Karbon veya cam takviyesi içeren filamentler aynı davranışı paylaşan tek bir grup değildir.","takeaways":["Öncelikli mekanik sorun ve yük yönü","Ölçüm ortamı ve kabul zamanı","Talep edilen tam ürün ve teknik föy"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/filament-material-guide"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/malzemeler/muhendislik-polimerleri' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mühendislik polimerleri","summary":"Özel çalışma koşulları 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür için değerlendirme","body":"Üretim ve bakım ekiplerinin kullanım senaryosuna özel parçalar. Geometri, yük, ortam koşulları ve montaj ilişkisi değerlendirilerek üretim kapsamı netleştirilir."},{"title":"Kullanım yaklaşımı","body":"Naylon ve katkılı polimerler için malzeme tedariki, kurutma, cihaz uyumu ve kullanım gereksinimleri proje bazında teyit edilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mimari kütle ve iç mekân sunumlarında PLA',summary='Maketin okunabilirliği, renk ve yüzey beklentisi için PLA adayını ölçek ve sergileme koşullarıyla değerlendirin.',sections='[{"title":"Küçük ayrıntıyı ölçeğe göre sadeleştirin","body":"PLA seçimi bu geometri sorununu tek başına çözmez. Makette hangi çizgilerin kabartma, hangi açıklıkların gölge izi olarak anlatılacağı mimari temsil kararıdır; numune cephede birlikte değerlendirilebilir."},{"title":"Sergileme yerini önceden belirtin","body":"Maketin pencere önünde, kapalı vitrinde veya taşınan sunum çantasında kalması farklı koşullar oluşturur. Beklenen ortam bilgisi renk ve malzeme görüşmesine eklenmelidir. Onay için tüm model yerine bir yapı köşesi hazırlanması, katman izi ve boya beklentisinin daha erken konuşulmasını sağlar."}]'::jsonb,faq='[{"q":"Beyaz PLA maket boyasız kullanılabilir mi?","a":"İstenen görünüşe bağlıdır. Baskı yüzeyinin ve birleşim çizgilerinin kabulü fiziksel örnek üzerinden yapılabilir; pürüzsüz boyalı maket beklentisi ayrıca son işlem kapsamıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Gerçek binadaki ince bir parapet, küçültüldüğünde üretim veya taşıma için çok narin kalabilir.","takeaways":["Maket ölçeği ve izleme mesafesi","Boya veya ham yüzey tercihi","Sergileneceği ortamın fotoğrafı"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/pla_2062"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/malzemeler/pla' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"PLA","summary":"Form ve sunum prototipleri maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu için değerlendirme","body":"Kütle, cephe, topoğrafya ve yerleşim ilişkisini görünür kılan maket çözümleri. Ölçek ve detay seviyesini hedef kitleniz, sunum amacı ve proje takviminiz belirler."},{"title":"Kullanım yaklaşımı","body":"Boyutsal görünüm ve form denemeleri için değerlendirilebilir. Sıcaklık, güneş ve yük altında kullanım ayrıca incelenmelidir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket kapakları ve dayanıklı detaylarda PETG',summary='Sökülüp takılan maket parçaları ve ışıkla ilişkili yüzeyler için PETG seçiminin sınırlarını numuneyle görün.',sections='[{"title":"Saydam filament ile cam etkisini ayırın","body":"Saydam PETG baskı, işlenmiş şeffaf levhayla aynı optik görünüşü vermeyebilir. Görünür alan için farklı temsil veya montaj yöntemleri değerlendirilebilir; karar küçük bir ışık ve yüzey örneğiyle verilmelidir."},{"title":"Sık kullanılan modüllerin oturmasını deneyin","body":"Maket toplantılarında çıkarılan çatı veya kat modülleri için takma kolaylığı ve kenar dayanımı önemlidir. Tutma noktaları ve oturma boşlukları tasarımda gösterilir. İlk numunenin sürtme veya iz bırakma davranışı değerlendirilerek büyük parçalar üretilmeden bağlantı biçimi netleştirilir."}]'::jsonb,faq='[{"q":"PETG ile tamamen şeffaf pencere üretilebilir mi?","a":"Baskı yönü, duvar yapısı ve yüzey işlemi görünüşü etkiler. Cam berraklığı gerekiyorsa bunu ayrı bir optik beklenti olarak belirtin; yöntem seçimi örnek üzerinden yapılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir makette cam cephe hissi istendiğinde ışık geçirgenliği, renk tonu ve yüzey izi birlikte önem kazanır.","takeaways":["Işık geçirgenliği için görsel referans","Çıkarılacak modüllerin tutma yüzeyleri","Pencere ve cephe parçası boyutları"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/petg_2059"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/malzemeler/petg' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"PETG","summary":"İşlevsel prototipler ve muhafazalar maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu için değerlendirme","body":"Kütle, cephe, topoğrafya ve yerleşim ilişkisini görünür kılan maket çözümleri. Ölçek ve detay seviyesini hedef kitleniz, sunum amacı ve proje takviminiz belirler."},{"title":"Kullanım yaklaşımı","body":"Tokluk ve işlenebilirlik beklentisi olan uygulamalarda değerlendirilir. Şeffaflık ve yüzey sonucu renk, geometri ve baskı ayarına bağlıdır."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Boyanacak maket bileşenlerinde ABS seçimi',summary='Büyük kütle, birleşim ve yüzey işlemi kararlarını ABS malzeme talebiyle aynı üretim planında ele alın.',sections='[{"title":"Parçalama çizgisini görünüşe göre yerleştirin","body":"Birleşimin cephede nerede görüneceği, zımpara yapılacak yüzler ve detayların korunması önceden konuşulmalıdır. Sadece malzeme adına odaklanmak, maketin bitmiş görünüşünü açıklamak için yeterli olmaz."},{"title":"Yüzey işini numunede kararlaştırın","body":"Boya rengi ile baskı rengini birbirinden ayırın. Boyanacak bir cephe örneğinde ince çerçevelerin dolması veya keskin köşelerin yumuşaması incelenebilir. Kaideyle birleşen yüzeylerin ve sökülen modüllerin son işlem sonrasında da oturması kontrol edilmelidir."}]'::jsonb,faq='[{"q":"ABS her maket için gerekli mi?","a":"Hayır; sergileme koşulu, geometri ve bitiş beklentisi belirleyicidir. Gereksiz bir malzeme şartı koymak yerine hedef yüzeyi ve kullanım biçimini tarif etmek seçenekleri açık tutar."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Tek parça bir bina kütlesi yerine ayrı bloklar üretmek, hem makine hacmi hem de yüzey işi bakımından değerlendirilebilir.","takeaways":["Boyalı yüzey için renk numunesi","Görünür birleşim hatlarının planı","Korunması gereken ince cephe detayları"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/filament-material-guide"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/malzemeler/abs' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"ABS","summary":"Gövde ve teknik parça denemeleri maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu için değerlendirme","body":"Kütle, cephe, topoğrafya ve yerleşim ilişkisini görünür kılan maket çözümleri. Ölçek ve detay seviyesini hedef kitleniz, sunum amacı ve proje takviminiz belirler."},{"title":"Kullanım yaklaşımı","body":"Isıl koşullar ve boyutsal kararlılık gereksinimiyle birlikte ele alınır. Büyük geometrilerde çekme ve üretim koşulları planlamayı etkiler."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Açıkta sergilenecek maketler için ASA değerlendirmesi',summary='Maketin güneş gören konumu ve korunma biçimini malzeme seçiminden önce açıklayın.',sections='[{"title":"Dış mekân maketini bir bütün olarak ele alın","body":"ASA değerlendirmesi yalnızca basılan parçaya ilişkindir; bütün maketin uzun dönem performansını tek başına belirlemez. Kapak, gölge veya taşınabilir sergileme düzeni gibi seçenekler proje kapsamını değiştirebilir."},{"title":"İnce detayların dayanımını denemeye ayırın","body":"Açıkta kullanılan modelin temizlenmesi ve taşınması sırasında korkuluk veya ağaç gibi narin parçalar zorlanabilir. Mimari anlatımı koruyarak hangi ayrıntının kalınlaştırılacağı, birleştirileceği veya farklı yöntemle temsil edileceği kararlaştırılır. Temizlik yöntemi ve sergileme süresi teklif görüşmesinde yer almalıdır."}]'::jsonb,faq='[{"q":"ASA kullanılırsa maket sürekli dışarıda kalabilir mi?","a":"Bütün bileşenler ve gerçek çevre koşulları değerlendirilmeden bu sonuç çıkarılamaz. Koruma düzeni ve bakım beklentisi ayrıca planlanır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Yapı kütlesi kadar yapıştırıcı, boya, taban ve etiketler de dış ortamdan etkilenebilir.","takeaways":["Güneş gören sergileme konumu","Kapak veya koruma düzeni","Maketin temizlik ve taşıma yöntemi"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/asa_1809"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/malzemeler/asa' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"ASA","summary":"Dış ortam için değerlendirilen parçalar maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu için değerlendirme","body":"Kütle, cephe, topoğrafya ve yerleşim ilişkisini görünür kılan maket çözümleri. Ölçek ve detay seviyesini hedef kitleniz, sunum amacı ve proje takviminiz belirler."},{"title":"Kullanım yaklaşımı","body":"Dış ortamda UV ve sıcaklık koşulları önem taşır. Malzeme seçimi tek başına kullanım ömrü garantisi değildir; geometri ve yük de incelenir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket taşımada esnek destek ve temas parçaları',summary='Sergi modelinin narin bölgelerini taşıma sırasında destekleyen esnek yardımcıları temas yüzeyine göre tasarlayın.',sections='[{"title":"Desteği ayrıntının üzerine yüklemeyin","body":"Temas noktaları kaide veya güçlü yapı bölgelerinde seçilir. TPU destek adayı için sıkışma miktarı ve yüzey izi beklentisi değerlendirilir; boyalı parçayla teması küçük bir örnekte denenebilir."},{"title":"Paketleme sırasını parça planına ekleyin","body":"Sökülen modüllerin ayrı yuvalara yerleşmesi ve yeniden doğru konuma takılması için kodlama kullanılabilir. Destek parçası çıkarılırken maketi çekmemeli veya detaylara takılmamalıdır. Taşıma kasasının iç ölçüsü, maketin tutulacağı yön ve açılma sırası birlikte tasarlanır."}]'::jsonb,faq='[{"q":"Esnek destek tek başına güvenli taşıma sağlar mı?","a":"Kasa, sabitleme, darbe ve taşıma yöntemi birlikte etkilidir. Bir destek parçası hazırlanması bütün sevkiyat koşulları için hasarsızlık taahhüdü oluşturmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir maketi ambalaj içinde tutarken kuvvetin ince cephe elemanlarına veya ağaçlara aktarılmaması gerekir.","takeaways":["Kaidenin taşıyıcı temas alanları","Kasa iç ölçüsü ve açılma yönü","Boyalı yüzeylere temas sınırları"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/flexible-materials_2057"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/malzemeler/tpu' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"TPU","summary":"Esnek parça ve temas yüzeyleri maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu için değerlendirme","body":"Kütle, cephe, topoğrafya ve yerleşim ilişkisini görünür kılan maket çözümleri. Ölçek ve detay seviyesini hedef kitleniz, sunum amacı ve proje takviminiz belirler."},{"title":"Kullanım yaklaşımı","body":"Esneklik gerektiren koruyucu, tampon ve kavrama parçalarında değerlendirilebilir. Sertlik derecesi, et kalınlığı ve bağlantı biçimi birlikte seçilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket mekanizmalarında özel polimer ihtiyacı',summary='Çıkarılabilir katlar, hareketli sunum elemanları ve montaj bağlantılarında hangi özelliğin gerekli olduğunu belirleyin.',sections='[{"title":"Görsel model ile mekanizmayı ayırın","body":"Tüm maketi özel polimerle üretmek yerine işlevli bağlantının gereksinimini ayrı değerlendirmek mümkündür. Hareket mesafesi, çevrim ve temas yüzeyleri tasarım girdisidir."},{"title":"Görünüş uyumunu numunede kontrol edin","body":"Özel polimerin rengi ve yüzey dokusu maketin diğer parçalarından farklı olabilir. İşlevli eleman görünür yerdeyse kaplama, gizleme veya farklı montaj konumu düşünülür. Üretilebilirlik ve gerçek ürün verisi incelendikten sonra küçük bir mekanizma numunesi üzerinde karar verilmelidir."}]'::jsonb,faq='[{"q":"Karbon katkılı malzeme daha kaliteli maket anlamına mı gelir?","a":"Katkı tipi görsel sunum kalitesinin ölçüsü değildir. Mimari makette okunabilirlik, temiz birleşimler ve doğru ölçek; mekanik bağlantıda ise görevine uygun davranış değerlendirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir maketin dış kütleleri yalnızca sunum işlevi taşırken hareketli bir platform veya sık açılan bağlantı farklı beklentiler doğurabilir.","takeaways":["Hareketli veya sık kullanılan eleman","Bağlantının görünürlük durumu","Gerekli hareket ve tekrar sayısı"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/filament-material-guide"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/malzemeler/muhendislik-polimerleri' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mühendislik polimerleri","summary":"Özel çalışma koşulları maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu için değerlendirme","body":"Kütle, cephe, topoğrafya ve yerleşim ilişkisini görünür kılan maket çözümleri. Ölçek ve detay seviyesini hedef kitleniz, sunum amacı ve proje takviminiz belirler."},{"title":"Kullanım yaklaşımı","body":"Naylon ve katkılı polimerler için malzeme tedariki, kurutma, cihaz uyumu ve kullanım gereksinimleri proje bazında teyit edilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Yedek parçada ölçü kontrolü için PLA numune',summary='Eksik parçanın montaj şeklini denemek için hazırlanan PLA örneğini nihai kullanım parçasından ayrı değerlendirin.',sections='[{"title":"Yuvaya uyumu önce küçük numunede görün","body":"Bu numune, ölçülerin doğru yorumlanıp yorumlanmadığını gösterir. Taslak PLA parça uyduğunda yalnızca geometrik karar doğrulanmış olur; kullanılacağı sıcaklık ve yük için malzeme seçimi devam eder."},{"title":"Numuneyi yanlış görevde kullanmayın","body":"Özellikle araç içi veya ısı kaynağına yakın parçalarda test numunesi ile kullanım parçasının karışmaması önemlidir. Deneme parçasına görevini belirten bir etiket eklenebilir. İlk kontrolün sonucu, gevşeklik, takılma veya sürtme noktaları olarak kaydedilip son model revizyonuna bağlanır."}]'::jsonb,faq='[{"q":"PLA ile araç içi parça sipariş edebilir miyim?","a":"Kullanım yeri ve sıcaklık koşulları görülmeden uygunluk söylenemez. Geçme denemesi için yapılan parçanın araçta sürekli kullanım için onaylandığı varsayılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Özel bir kapak için bütün parçanın üretilmesi yerine kritik kenar ve bağlantı bölgesi denenebilir.","takeaways":["Montaj yuvasının net ölçüleri","Deneme ile kullanım amacının ayrımı","Parçanın bulunacağı sıcak ortamlar"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/pla_2062"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/malzemeler/pla' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"PLA","summary":"Form ve sunum prototipleri parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Boyutsal görünüm ve form denemeleri için değerlendirilebilir. Sıcaklık, güneş ve yük altında kullanım ayrıca incelenmelidir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Özel kapak ve yardımcı bağlantılarda PETG',summary='Gündelik yardımcı parçalar için PETG adayını yük, montaj sıkılığı ve ortam koşullarıyla birlikte değerlendirin.',sections='[{"title":"Orijinal parçanın görevini okuyun","body":"Parça söküldüğünde hangi bileşenin serbest kaldığını ve üzerinde kuvvet oluşup oluşmadığını açıklayın. PETG seçimi, kırık örneğin dış biçiminden çok bu kullanım tarifine dayanmalıdır."},{"title":"Geçmeyi gerçek karşı parçada deneyin","body":"Ölçüye göre modellenen bir yuva, eskimiş veya şekli bozulmuş karşı parçayla farklı oturabilir. Denemede takma kuvveti, boşluk ve sökme izi incelenir. Uzun süre yükte kalma ya da sıcaklık değişimi varsa bunlar da test kapsamına alınarak sadece ilk anda uymasıyla karar verilmez."}]'::jsonb,faq='[{"q":"PETG orijinal parçanın malzemesiyle aynı sayılır mı?","a":"Orijinal malzeme bilinmiyorsa eşdeğerlik iddiası kurulamaz. Yeni parçanın seçimi, tanımlanan işlev ve gerçek kullanım denemesi üzerinden yapılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Kapağın yalnızca açıklığı kapatması ile bir mekanizmayı tutması aynı görev değildir.","takeaways":["Parçanın tuttuğu veya kapattığı bölge","Karşı parçanın aşınma durumu","Sökme sıklığı ve yük süresi"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/petg_2059"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/malzemeler/petg' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"PETG","summary":"İşlevsel prototipler ve muhafazalar parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Tokluk ve işlenebilirlik beklentisi olan uygulamalarda değerlendirilir. Şeffaflık ve yüzey sonucu renk, geometri ve baskı ayarına bağlıdır."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Gövde ve trim yenilemede ABS adayının değerlendirilmesi',summary='Eski parça üzerindeki malzeme işareti, montaj şartı ve yüzey beklentisini yeni baskı tasarımına doğru aktarın.',sections='[{"title":"Malzeme işaretini başlangıç bilgisi kabul edin","body":"Üretim yapısı ve geometri farklılığı nedeniyle bağlantı bölgeleri yeniden değerlendirilir. Kırılmanın darbe, yanlış sökme veya sürekli gerilme nedeniyle olup olmadığına ilişkin gözlem tasarım kararını etkileyebilir."},{"title":"Boya ve doku beklentisini açıklaştırın","body":"Görünen bir trim parçasında renk kadar yüzey dokusu ve parlaklık da fark edilir. Fotoğrafın ışığı bu özellikleri değiştirebilir; mümkünse fiziksel referans üzerinden konuşun. Boya sonrasında tırnakların ve oturma kenarlarının hareketi tekrar kontrol edilerek estetik işlem ile montaj uyumu birlikte ele alınır."}]'::jsonb,faq='[{"q":"Orijinal yüzey dokusu birebir yapılabilir mi?","a":"Doku, üretim yöntemi ve son işlem kapsamına bağlıdır. Görsel benzerliğin hangi düzeyde beklendiği örnek üzerinden tanımlanır; yalnızca malzeme adı birebir sonuç sağlamaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Kalıplanmış bir parçada ABS yazması, aynı isimli filamentle doğrudan eşdeğer baskı alınacağı anlamına gelmez.","takeaways":["Parça üzerindeki malzeme işareti","Kırılma veya kullanım geçmişi","Renk ve yüzey için sağlam referans"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/filament-material-guide"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/malzemeler/abs' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"ABS","summary":"Gövde ve teknik parça denemeleri parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Isıl koşullar ve boyutsal kararlılık gereksinimiyle birlikte ele alınır. Büyük geometrilerde çekme ve üretim koşulları planlamayı etkiler."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Dışarıda kullanılan plastik parçalarda ASA',summary='Güneş gören kapak ve güvenlik kritik olmayan aksesuarlar için çevre, bağlantı ve yüzey koşullarını ayrı tanımlayın.',sections='[{"title":"Maruz kalmayı konum üzerinden anlatın","body":"Yerini gösteren geniş fotoğraf ile yakın montaj fotoğrafını birlikte paylaşın. ASA dış ortam için aday olabilir; ancak parçanın özel görevine uygunluk tam malzeme ürünü ve tasarım üzerinden değerlendirilir."},{"title":"Bağlantının kendisini gözden geçirin","body":"Sıcaklık değişimi veya kullanım hareketi, bağlantı noktasında gerilme oluşturabilir. Eski parçanın koptuğu yer bilinirse aynı zayıf geometrinin tekrarlanıp tekrarlanmayacağı tartışılabilir. Geçme, vida ve yapıştırma seçeneklerinin yüzey ve bakım beklentisi farklı olduğundan yalnızca dış şekli kopyalamakla yetinilmez."}]'::jsonb,faq='[{"q":"ASA baskı orijinal otomotiv parçası yerine geçer mi?","a":"Özel üretim parça, orijinal üretici onayı veya homologasyon taşıdığı anlamına gelmez. Güvenlik açısından görevi ve kullanım uygunluğu ayrıca değerlendirilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Araç dışında, balkonda veya bir ekipmanın açık yüzünde kullanılan parçalar farklı ısı ve su koşulları görür.","takeaways":["Açık ortam konumunun fotoğrafı","Eski parçanın hasar bölgesi","Montaj yöntemi ve bakım erişimi"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/asa_1809"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/malzemeler/asa' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"ASA","summary":"Dış ortam için değerlendirilen parçalar parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Dış ortamda UV ve sıcaklık koşulları önem taşır. Malzeme seçimi tek başına kullanım ömrü garantisi değildir; geometri ve yük de incelenir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Esnek kapak, ayak ve temas elemanlarında TPU',summary='Yumuşak parça ihtiyacını sertlik, sıkışma ve yüzeye tutunma beklentileriyle tarif ederek numune seçin.',sections='[{"title":"Eski parçanın hissini referanslayın","body":"Elde kalan örnek varsa onu tarif etmek, sadece “lastik parça” demekten daha faydalıdır. Tam TPU ürünü, sertlik ve geometrik yapı birlikte değerlendirilir."},{"title":"Sıkıştırıldıktan sonraki durumu da görün","body":"Numune ilk anda otursa bile kullanım sonrasında gevşeme veya iz oluşabilir. Temas süresi, tekrarlı sökme ve temizleyiciyle temas gibi koşullar kayıt altına alınmalıdır. Sızdırmazlık veya basınç tutma bekleniyorsa bu genel esnek parça işinden ayrı bir doğrulama gereksinimi olarak ele alınır."}]'::jsonb,faq='[{"q":"TPU baskı her contanın yerine kullanılabilir mi?","a":"Hayır; sızdırmazlık yüzeyi, basınç, sıvı ve sıcaklık şartları özel değerlendirme ister. Esnek görünmek conta işlevinin doğrulandığını göstermez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir cihaz ayağının kaymaması, bir kılıfın gövdeye oturması veya tamponun darbe sırasında sıkışması farklı görevlerdir.","takeaways":["Eski parça veya sertlik referansı","Sıkışma biçimi ve temas süresi","Kayma, iz veya sızdırmazlık beklentisi"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/article/flexible-materials_2057"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/malzemeler/tpu' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"TPU","summary":"Esnek parça ve temas yüzeyleri parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Esneklik gerektiren koruyucu, tampon ve kavrama parçalarında değerlendirilebilir. Sertlik derecesi, et kalınlığı ve bağlantı biçimi birlikte seçilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Zorlayıcı kullanımda özel parça malzemesi nasıl seçilir?',summary='Katalogda bulunamayan bir parçanın yük, aşınma ve ortam sorununu teknik gereksinime dönüştürün.',sections='[{"title":"Arızayı malzeme adıyla açıklamayın","body":"Daha pahalı bir filament istemeden önce kırılma yeri, görev ve kullanım geçmişi incelenmelidir. Değiştirilecek tasarım ile değerlendirilecek malzeme adayı ayrı kararlar olarak tutulabilir."},{"title":"Kullanım sınırını belirleyin","body":"Parça fren, direksiyon, taşıma, emniyet veya benzeri kritik bir göreve bağlıysa sıradan bir tersine mühendislik talebi gibi ele alınamaz. Yardımcı plastik parçalarda da gerçek ürün verisi, ölçü kontrolü ve kullanım numunesi gerekir. Özel polimerlerin üretim uygunluğu mevcut donanım ve süreç kapsamında ayrıca teyit edilir."}]'::jsonb,faq='[{"q":"Eski malzeme bilinmiyorsa nasıl başlanır?","a":"İşlev, ortam ve karşı parçalar üzerinden gereksinim toplanır. Malzeme tanımlama veya ilave test gerekiyorsa bu iş kapsamı açıkça ayrılır; görüntüden kesin polimer teşhisi yapılmış sayılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir parçanın yeniden kırılması yanlış geometri, keskin köşe veya montaj gerilimiyle de ilişkili olabilir.","takeaways":["Hasar yeri ve eski kullanım süresi","Yük, sürtünme ve sıcaklık tarifi","Parçanın güvenlik açısından görevi"],"relatedPaths":["/3d-baski","/rehber/malzeme-secim-sorulari"],"sources":[{"title":"Prusa teknik malzeme rehberi — ürün seçimine giriş","url":"https://help.prusa3d.com/filament-material-guide"}]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/malzemeler/muhendislik-polimerleri' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mühendislik polimerleri","summary":"Özel çalışma koşulları parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv için değerlendirme","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Kullanım yaklaşımı","body":"Naylon ve katkılı polimerler için malzeme tedariki, kurutma, cihaz uyumu ve kullanım gereksinimleri proje bazında teyit edilir."},{"title":"Teklif öncesi kontrol","body":"Çalışma sıcaklığını, yükü, ortamı ve eşleşen parçaları paylaşın. Malzeme adı tek başına dayanım veya tolerans taahhüdü oluşturmaz. Teknik özellikler seçilen üretici ve ürünün veri sayfasıyla birlikte teyit edilir."},{"title":"Numune ve üretim","body":"Renk, yüzey ve montaj beklentisini fiziksel numuneyle değerlendirmek önerilir. Uygunluk kararı sonrası adet, son işlem ve teslim kapsamı belirlenir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Endüstriyel ürün geliştirmede prototip ve gövde denemesi',summary='Makineye eklenecek yeni bir ürünün dış hacmini, arayüzlerini ve servis erişimini ilk fiziksel numuneyle değerlendirin.',sections='[{"title":"Sisteme bağlanan yüzleri öne çıkarın","body":"Bağlantı deliklerini, kablo yönünü ve operatörün erişeceği alanı ürün modeline ekleyin. İlk prototipin görevi bu ilişkileri görmek olabilir; aynı örnekten sahadaki bütün çevre koşullarına uygunluk sonucu beklenmez."},{"title":"Ürün kararını parça kararından ayırın","body":"Gövde şekli değiştiğinde kart, etiket ve bağlantı donanımı da etkilenebilir. Numune toplantısında hangi bileşenin sabit kaldığını ve hangisinin değişebileceğini işaretleyin. Böylece bir dış yüzey revizyonunun içerideki montajı bozup bozmadığı sonraki dosya kontrolünde izlenebilir."}]'::jsonb,faq='[{"q":"Mevcut makineye takılacak yeni cihaz için başlanabilir mi?","a":"Montaj alanının fotoğrafı, referans ölçüler ve cihazın işlevi başlangıç için paylaşılabilir. Makine üreticisine ait gereksinimler ve güvenlik sınırları proje kapsamında ayrıca ele alınır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir sensör kutusu veya küçük kontrol ünitesi, çevresindeki ekipmanla birlikte çalışır.","takeaways":["Sistem arayüzleri ve boş hacim","Operatörün erişeceği yüzler","Değiştirilebilir ürün bileşenleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/sektorler/endustriyel' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Endüstriyel üretim","summary":"Üretim hattındaki özel aparat, montaj yardımcısı ve düşük adetli parça ihtiyaçlarını aynı teknik briefte toplayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hattaki görevi tarif edin","body":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"title":"Pilot parçadan onaylı revizyona","body":"İlk numuneyi gerçek montaj noktasında değerlendirecek kişiyi belirleyin. Uyum, erişim ve operatör kullanımı ayrı kontrol başlıkları olmalıdır. Numune üzerinde yapılan değişiklikleri çizim revizyonuna işleyin; seri talebi yalnızca onaylanan dosyaya bağlayın."},{"title":"Satın alma dosyası","body":"Talebe parça kodu, adet, malzeme beklentisi ve kabul ölçütlerini ekleyin. Birden fazla parçanın aynı siparişte değerlendirilmesi gerekiyorsa dosya adlarını adet tablosuyla eşleştirin. Tekrarlı siparişlerde önceki revizyon ve değişen koşulları belirtin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Otomotiv aksesuar fikirleri için montaj prototipleri',summary='Güvenlik kritik olmayan araç içi aksesuarların hacim, erişim ve montaj davranışını araç üzerindeki konumuyla birlikte sınayın.',sections='[{"title":"Aksesuarın çevresini gösterin","body":"Yerleşim fotoğrafını tek açıyla sınırlamayın; sürücünün veya yolcunun erişimini de tarif edin. Araç modeli ve donanım farkı, aynı görünen bölgenin farklı ölçülere sahip olmasına yol açabilir."},{"title":"İlk denemeyi kullanım dışı konumda planlayın","body":"Numunede önce mekanik oturma, görüş alanı ve kumandalara erişim değerlendirilir. Sıcaklık, titreşim ve uzun süreli kullanım ayrı gereksinimlerdir. Prototipin uyduğu gözlemi, araç üreticisi onayı veya yol kullanımına uygunluk beyanı yerine geçmez."}]'::jsonb,faq='[{"q":"Bir aksesuarı tüm araçlara uyumlu tasarlayabilir miyiz?","a":"Uyumluluk iddiası için hedef araç ve varyant listesi gerekir. Tek numune üzerinden bütün modellere uygunluk varsayılmaz; ortak ve değişen arayüzler ayrıştırılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Telefon tutucu gövdesi, düzenleyici veya dekoratif ek parça tasarımında yakındaki kumandalar ve hareketli kapaklar önemlidir.","takeaways":["Araç modeli ve ilgili donanım","Montaj yerinin geniş ve yakın fotoğrafı","Kumanda ve görüş alanı ilişkisi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/sektorler/otomotiv' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Otomotiv ve yedek parça","summary":"Trim, kapak, klips ve prototip parçalarında numuneden modele uzanan süreci kullanım koşullarıyla birlikte planlayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Montaj ilişkisini koruyun","body":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"title":"Ortam koşullarını paylaşın","body":"İç mekân, güneş gören bölge veya motor çevresi farklı koşullar taşır. Sıcaklık, titreşim, kimyasal temas ve beklenen kullanım ömrünü anlatın. Görünüş numunesi ile işlevsel kullanım parçasını aynı kabul kriteriyle değerlendirmeyin."},{"title":"Doğrulama kapsamı","body":"Emniyet açısından kritik bir parçanın yeniden üretilmesi ayrıca mühendislik doğrulaması gerektirir. Talepte parçanın görevini açıkça belirtin. Prototipin montaja oturması, tek başına güvenli kullanım onayı anlamına gelmez."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mekân ürünleri ve mimari detaylar için tasarım prototipi',summary='Mobilya bağlantısı, aydınlatma gövdesi ve mekânsal ürün fikirlerini ölçü, oran ve montaj üzerinden somutlaştırın.',sections='[{"title":"Ürünü yerindeki ölçekle düşünün","body":"Yakınındaki malzemeleri ve kullanıcının bakış mesafesini gösteren bağlam görseli ekleyin. İlk prototip, parçanın dış oranını ve dokunma noktalarını sınamak için hazırlanabilir; dekoratif yüzey işi daha sonra ayrı onaylanabilir."},{"title":"Montaj detayı görsel kararı etkiler","body":"Vida, kablo veya askı noktası tasarımın görünür yüzünü değiştirebilir. Gizlenecek bağlantılar ve bakım için erişilecek bölgeler ilk modelde düşünülmelidir. Bir aydınlatma fikrinde elektrik, ısıl davranış ve ürün uygunluğu ayrı uzmanlık ve doğrulama konularıdır."}]'::jsonb,faq='[{"q":"Renderdan fiziksel obje üretimine geçilebilir mi?","a":"Render biçimi anlatır; ölçülü model veya ek modelleme gerekebilir. Kullanılacak ölçü, birleşim ve malzeme bilgisiyle üretim kapsamı belirlenir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Ekranda dengeli görünen bir obje, kullanılacağı masa veya duvar üzerinde farklı algılanabilir.","takeaways":["Mekân içindeki ölçek referansı","Görünen ve gizlenen bağlantılar","İlk numuneden beklenen tasarım kararı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/sektorler/mimari-tasarim' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mimari ve tasarım","summary":"Kütle, cephe ve yerleşim maketlerinde ölçeği, gösterilecek detayları ve taşıma planını üretimden önce netleştirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçekte okunabilirlik","body":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"title":"Bölünebilir üretim","body":"Maketin sergileneceği alan ve taşınacağı kutu boyutu, parçalara ayırma kararını etkiler. Birleşim yerlerini görünür cephelerden uzaklaştırmak veya sökülebilir kütleler kullanmak tasarım aşamasında değerlendirilebilir. Aydınlatma ve kablo kanalları ayrıca belirtilmelidir."},{"title":"Sunum onayı","body":"Renk, yüzey, etiket ve taban beklentisini referanslarla anlatın. Önce dijital yerleşim, sonra kritik bir detayın numunesi üzerinden karar verin. Son teslimden önce parça listesi ve yerleşim şemasını birlikte kontrol edin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Medikal ürün fikirleri için eğitim ve ergonomi modelleri',summary='Klinik kullanım dışındaki cihaz gövdesi, eğitim maketi ve kullanıcı arayüzü çalışmalarını kontrollü prototip kapsamıyla ele alın.',sections='[{"title":"Modelin kullanım amacını sınırlandırın","body":"Talepte modelin kim tarafından, nerede ve neyi göstermek için kullanılacağını açıklayın. Bu sayfadaki yaklaşım, ürün fikri ve eğitim prototipini ele alır; klinik uygunluk veya biyouyumluluk beyanı içermez."},{"title":"Ergonomi gözlemini kayda alın","body":"Eldivenle tutma, düğmeye erişme veya ekranı görme gibi tasarım soruları fiziksel bir gövde numunesiyle incelenebilir. Değerlendirmeyi yapacak kişi ve gözlemlenecek hareketler belirlenmelidir. Temizlik yöntemi veya hasta temasına ilişkin gereksinimler varsa bunlar yetkili ekip tarafından ayrı değerlendirilir."}]'::jsonb,faq='[{"q":"Görüntüleme verisi paylaşmak gerekli mi?","a":"Her prototipte gerekli değildir. Gövde ve arayüz çalışmalarında ölçülü ürün verisi yeterli olabilir; kişisel veya sağlık verisi içeren bir dosya gerekiyorsa paylaşım kapsamı önceden kararlaştırılmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir eğitim modelinin dokunularak anlatımda kullanılması ile hastayla temas eden bir parçanın üretilmesi farklı süreçlerdir.","takeaways":["Eğitim veya tasarım kullanımının tanımı","Kullanıcının gerçekleştireceği hareket","Prototipin temas edeceği ortam"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/sektorler/medikal' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Medikal tasarım ve eğitim","summary":"Anlatım, eğitim ve tasarım değerlendirmesi için anatomik gösterim ve cihaz gövdesi prototiplerinin kapsamını belirleyin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kullanım amacını ayırın","body":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"title":"Veri paylaşımı","body":"Gerekli dosya formatını ve görüntüleme beklentisini teknik ekiple belirleyin. Kişisel bilgi içeren görüntü veya dosyaları paylaşmadan önce yetki ve anonimleştirme süreçlerinizi tamamlayın. Teklif aşamasında mümkünse kimlik bilgisi içermeyen geometriyle başlayın."},{"title":"Eğitim modelinin kabulü","body":"Gösterilecek yapıları, renk ayrımını, sökülebilir bölümleri ve kullanılacak ölçeği listeleyin. Modelin anlatım amacına uygunluğunu konu uzmanı değerlendirmelidir. Dijital onay ile fiziksel yüzey beklentisini ayrı adımlarda ele alın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Havacılık Ar-Ge sunumları için işlev dışı fiziksel prototip',summary='Kavramsal yerleşim ve tasarım değerlendirmelerinde kullanılacak modelin görevini, veri kapsamını ve teslim biçimini netleştirin.',sections='[{"title":"Sunum modelini operasyon parçasından ayırın","body":"Talepte numunenin sunum, hacim kontrolü veya montaj erişimi amacıyla kullanıldığını açıkça yazın. Operasyonel yük, güvenlik veya sertifikasyon beklentisi varsa bu kapsam bağımsız olarak ele alınmalıdır."},{"title":"Paylaşılacak geometriyi seçin","body":"Yerleşim kontrolü için gerekli olmayan iç ayrıntıların tamamını iletmek zorunlu olmayabilir. Yetkili proje ekibi hangi arayüz ve dış hacmin paylaşılabileceğini belirler. Dosya revizyonu, gizlilik talebi ve teslim edilecek model formatı başlangıçta kayda alınır."}]'::jsonb,faq='[{"q":"Bu modeller sertifikalı havacılık parçası mıdır?","a":"Hayır; bu kapsam kavramsal ve işlev dışı tasarım prototipleridir. Belirli bir standart veya sertifikasyonun karşılandığı ancak ilgili süreç ve doğrulama ile söylenebilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir gövde formu veya cihaz yerleşimini anlatan model, uçuşa elverişlilik değerlendirmesinden farklı bir ihtiyacı karşılar.","takeaways":["Modelin operasyon dışı kullanım amacı","Paylaşımı onaylanmış dış geometri","Revizyon ve veri erişim sorumlusu"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/sektorler/savunma-havacilik' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Havacılık ve teknik Ar-Ge","summary":"Form kontrolü, ergonomi ve montaj gösterimi için kullanılan teknik prototipleri izlenebilir bir dosya akışıyla planlayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kapsam ve veri sınırı","body":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"title":"Gösterim ve montaj prototipi","body":"Ergonomi maketi, bağlantı yerleşimi veya dış form numunesinde hangi kararın doğrulanacağını yazın. Görsel prototipin uçuşa elverişlilik veya işlevsel parça sertifikası sağlamadığını proje içinde açıkça ayırın. Kritik işlevler ayrı doğrulama planı gerektirir."},{"title":"İzlenebilir değerlendirme","body":"Dosya adı, parça kodu, revizyon, talep sahibi ve kabul kontrolünü ortak tabloda tutun. Fiziksel numune üzerindeki değişiklikleri dijital modele geri işleyin. Tekrar üretimde onaylı dosyanın aynı olduğundan emin olun."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Eğitim projeleri ve Ar-Ge deneyleri için fiziksel prototip',summary='Bir fikri göstermek veya kontrollü bir denemeyi kurmak için gereken model, geometri ve gözlem planını birlikte hazırlayın.',sections='[{"title":"Deney sorusunu parçaya çevirin","body":"Hangi ilişkinin gözleneceği, hangi ölçünün değiştirileceği ve hangi parçasının sabit kalacağı yazılmalıdır. Karşılaştırma numunelerinde aynı referansı kullanmak, sonuçların yalnızca rastgele baskı farkından etkilenmesini azaltmaya yardımcı olur."},{"title":"Dosya düzenini tekrar üretilebilir kurun","body":"Deney grubunu, model sürümünü ve malzeme bilgisini dosya adlarında veya eşlik eden listede tutun. Parçaların üzerine okunabilir bir kod gerekebilir. Sonuçların anlamlı olması için üretim kapsamı kadar ölçüm veya gözlem yönteminin de proje ekibi tarafından tanımlanması gerekir."}]'::jsonb,faq='[{"q":"Tek bir numune yeterli olur mu?","a":"Bu, sorulan araştırma sorusuna bağlıdır. Karşılaştırma veya tekrar deneyi gerekiyorsa adet ve varyantlar çalışmanın yöntemine göre belirlenmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Öğrenci veya araştırma projesinde başarılı çıktı her zaman bitmiş bir ürün değildir.","takeaways":["Araştırma sorusu ve değişkenler","Numune kodları ve varyant listesi","Gözlemi yapacak kişi veya ekip"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/sektorler/egitim-arge' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Eğitim ve Ar-Ge","summary":"Fikrinizi test edilebilir numunelere ayırın; bir sonraki tasarım kararını verecek prototipi üretin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Deneyi önce tanımlayın","body":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"title":"Revizyonları karşılaştırın","body":"Alternatifleri dosya adında işaretleyin; yalnızca değişen parametreleri bir tabloyla paylaşın. Deneme sonucunu not ederken kullanılan revizyonu ve test koşullarını ekleyin. Böylece yeni numunenin neden istendiği açık kalır."},{"title":"Bütçe ve adet","body":"Görünüş değerlendirmesi için gereken adetle kullanıcı testi için gereken adet aynı olmayabilir. Önce küçük bir doğrulama grubu planlayın. Malzeme, yüzey ve teslim tarihi seçimlerini deneyin amacıyla birlikte değerlendirin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Obje ve takı tasarımlarında ölçek ve form prototipi',summary='Heykel, dekoratif obje ve aksesuar tasarımlarının oranını ve eldeki hissini fiziksel örnekle değerlendirin.',sections='[{"title":"Dijital ayrıntıyı fiziksel ölçekte okuyun","body":"Nihai dış ölçüyü, dokunulacak yüzeyleri ve özellikle korunacak karakteristik biçimleri belirtin. İlk örnekte silüet, denge ve oran değerlendirilerek ayrıntı için hangi bölgelerin yeniden düzenleneceği seçilebilir."},{"title":"Sonraki üretim yolunu baştan konuşun","body":"Prototipin sergilenecek nihai obje mi, kalıp için referans mı yoksa yalnızca form çalışması mı olduğu önemlidir. Döküm veya başka malzemeye aktarım düşünülüyorsa bu süreç ayrı teknik gereksinimler getirir. FDM numune, her döküm sürecinde doğrudan kullanılabilir bir model olarak kabul edilmez."}]'::jsonb,faq='[{"q":"Takı prototipi metal ürünle aynı görünür mü?","a":"Yansıtma, ağırlık ve yüzey farklılığı algıyı değiştirir. Prototipin hangi özellikleri değerlendireceği belirlenerek metal üretim veya son işlem ihtiyacı ayrıca ele alınır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir modelin ekranda görünen ince çizgileri küçültülmüş objede aynı etkiyi vermeyebilir.","takeaways":["Gerçek boyut ve karakteristik hatlar","Sergileme veya sonraki üretim amacı","Dokunma ve ağırlık beklentisi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/sektorler/sanat-mucevher' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Sanat, obje ve takı tasarımı","summary":"Heykel, obje ve takı tasarımlarında dijital formu fiziksel ölçekte görerek yüzey ve detay kararlarını geliştirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Formun fiziksel etkisi","body":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"title":"Son işlem planı","body":"Boyama, birleştirme veya başka bir üretim sürecine girdi oluşturma amacı varsa bunu baştan belirtin. Kalıp veya döküm sürecine uygunluk ilgili üretim yöntemiyle ayrıca değerlendirilmelidir. Her baskı malzemesinin her son işlemle uyumlu olduğu varsayılmaz."},{"title":"Tasarım hakları","body":"Üretim için ilettiğiniz modelin kullanım hakkının sizde olduğundan emin olun. Sanatçı adı, eser numarası ve revizyonu dosyada takip edin. Görsel sunum numunesi ile satışa çıkacak nihai ürünün kabul ölçütlerini ayrı belirleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Robotik ve hobi projelerinde gövde ve yerleşim prototipi',summary='Elektronik, batarya ve mekanik bileşenleri bir arada konumlandırmak için tasarım numuneleri hazırlayın.',sections='[{"title":"Bileşenleri gerçek hacimleriyle temsil edin","body":"Bataryanın takılma yönü, anahtara erişim ve bileşenleri değiştirme ihtiyacı modelde gösterilmelidir. İlk gövde denemesi, ekipmanın işlevinden önce bu yerleşim ilişkilerini anlamaya yönelik olabilir."},{"title":"Hareket alanlarını açık bırakın","body":"Hareketli mekanizma veya pervane çevresindeki boşluklar tasarım sınırıdır. Prototip, çalışan düzende kullanılmadan önce yetkili proje ekibinin kontrolünden geçmelidir. Darbe, titreşim veya uçuş yükü gibi beklentiler ayrıca değerlendirilir; yalnızca monte edilebilmesi güvenli çalışma kanıtı değildir."}]'::jsonb,faq='[{"q":"Hazır indirilen model doğrudan basılabilir mi?","a":"Dosyanın kullanım izni, ölçüsü ve sizin bileşenlerinizle uyumu kontrol edilmelidir. Gereken model düzeltmeleri baskı işinden ayrı kapsam olabilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Kart dış ölçüsü kadar konektör ve kablo çıkışı da yer kaplar.","takeaways":["Gerçek bileşen ölçüleri ve bağlantılar","Kablo ve bakım erişimi","Hareketli bölgelerin sınırları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/sektorler/drone-hobi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Drone, robotik ve hobi","summary":"Elektronik yerleşimi, kablo yönetimi ve montaj yardımcıları için modelleme ve prototip planınızı oluşturun. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Bileşen yerleşimi","body":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"title":"Deneme koşulları","body":"Titreşim, dış ortam ve hareketli mekanizma ilişkisini belirtin. Uçuş veya yüksek hız gerektiren kullanımda parça doğrulaması ayrıca ele alınmalıdır. Tasarım numunesini doğrudan güvenlik açısından kritik kullanıma uygun kabul etmeyin."},{"title":"Onarım ve değiştirme","body":"Sık sökülecek kapakları, tüketilecek parçaları ve farklı sürümlerde değişecek bağlantıları işaretleyin. Tasarımın servis kolaylığı prototip üzerinden kontrol edilebilir. Sonraki sipariş için onaylanan dosyayı ve bağlantı ölçülerini saklayın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Üretim hattında montaj ve konumlandırma aparatları',summary='Tekrarlanan işlemi, iş parçasının referanslarını ve operatör erişimini aynı fikstür ihtiyacında birleştirin.',sections='[{"title":"İşlemden bağımsız aparat tasarlamayın","body":"Yükleme, işlem ve boşaltma adımlarının sırasını gösterin. Hatalı yerleştirmeyi görünür kılacak bir geometrik anahtar veya yön işareti düşünülebilir; bunun çalıştığı gerçek örnekler üzerinden sınanmalıdır."},{"title":"Üretim denemesini kayıt altına alın","body":"İlk parçada uyum görüldükten sonra operatör hareketi, çevrim içindeki temas ve temizlik ihtiyacı değerlendirilir. Bulgu ve revizyonların istasyon kimliğiyle tutulması, benzer görünen farklı aparatların karışmasını önler. Sürekli kullanım için kabul kararı yetkili üretim ve kalite sorumlularına aittir."}]'::jsonb,faq='[{"q":"Mevcut aparatta sadece bir bölge yenilenebilir mi?","a":"Aşınan veya değişen bölümün bağlantıları ve görevleri biliniyorsa parça bazlı yenileme değerlendirilebilir. Yeni parçanın eski gövdeyle hizası ayrıca kontrol edilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir istasyondaki tutucu, sonraki istasyona giden parçanın yönünü de etkileyebilir.","takeaways":["İstasyonun işlem sırası","Hatalı yerleşme ihtimalleri","Sökülebilir veya aşınan elemanlar"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/sektorler/endustriyel' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Endüstriyel üretim","summary":"Üretim hattındaki özel aparat, montaj yardımcısı ve düşük adetli parça ihtiyaçlarını aynı teknik briefte toplayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hattaki görevi tarif edin","body":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"title":"Pilot parçadan onaylı revizyona","body":"İlk numuneyi gerçek montaj noktasında değerlendirecek kişiyi belirleyin. Uyum, erişim ve operatör kullanımı ayrı kontrol başlıkları olmalıdır. Numune üzerinde yapılan değişiklikleri çizim revizyonuna işleyin; seri talebi yalnızca onaylanan dosyaya bağlayın."},{"title":"Satın alma dosyası","body":"Talebe parça kodu, adet, malzeme beklentisi ve kabul ölçütlerini ekleyin. Birden fazla parçanın aynı siparişte değerlendirilmesi gerekiyorsa dosya adlarını adet tablosuyla eşleştirin. Tekrarlı siparişlerde önceki revizyon ve değişen koşulları belirtin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Otomotiv üretim ekipleri için yardımcı fikstürler',summary='Araç parçası üretimi veya montajında kullanılan işlem yardımcılarını ürün geometrisi ve kalite kontrolüyle birlikte tanımlayın.',sections='[{"title":"Parça ailesinin farklarını listeleyin","body":"Hangi ürünlerin işleneceğini ve karıştırılmaması gereken varyantları belirtin. Dayama ve işaretleme kararları bu varyant listesine göre verilir."},{"title":"Kontrol gereksinimini üretim yardımından ayırın","body":"Parçayı montaj sırasında tutmak ile ölçü uygunluğunu kanıtlamak aynı iş değildir. Kalite ekibinin istediği referans ve toleranslar teknik dosyada açık olmalıdır. İlk numune, üretim ortamındaki kuvvet, erişim ve değişim adımları üzerinden değerlendirilir."}]'::jsonb,faq='[{"q":"Üretilen aparat otomotiv standardına uygun sayılır mı?","a":"Standart, müşteri şartnamesi ve doğrulama gereksinimleri açıkça belirtilmelidir. Bir sektöre yönelik olması tek başına kalite sistemi veya ürün uygunluğu belgesi oluşturmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Sağ-sol varyantlar, farklı kablo çıkışları veya model yılı değişimleri bir fikstürün yanlış ürüne de oturmasına yol açabilir.","takeaways":["Ürün ailesi ve sağ-sol varyantlar","Müşteri teknik şartnamesi","Üretim ve kontrol görevlerinin ayrımı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/sektorler/otomotiv' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Otomotiv ve yedek parça","summary":"Trim, kapak, klips ve prototip parçalarında numuneden modele uzanan süreci kullanım koşullarıyla birlikte planlayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Montaj ilişkisini koruyun","body":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"title":"Ortam koşullarını paylaşın","body":"İç mekân, güneş gören bölge veya motor çevresi farklı koşullar taşır. Sıcaklık, titreşim, kimyasal temas ve beklenen kullanım ömrünü anlatın. Görünüş numunesi ile işlevsel kullanım parçasını aynı kabul kriteriyle değerlendirmeyin."},{"title":"Doğrulama kapsamı","body":"Emniyet açısından kritik bir parçanın yeniden üretilmesi ayrıca mühendislik doğrulaması gerektirir. Talepte parçanın görevini açıkça belirtin. Prototipin montaja oturması, tek başına güvenli kullanım onayı anlamına gelmez."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Yapı bileşeni üretiminde montaj yardımcıları',summary='Doğrama, panel ve tasarım ürünü atölyelerinde tekrarlanan hizalama işlemlerini ölçüye özel aparatlarla değerlendirin.',sections='[{"title":"Bitmiş yüzeyleri temas planına ekleyin","body":"Aparatın referans alacağı yüz ile korunması gereken yüz ayrı gösterilir. Panel kalınlığı veya profil kesiti değişiyorsa varyantlar bir arada incelenerek değişebilir dayama gerekip gerekmediği belirlenir."},{"title":"Bağlantı ve takım yolunu gösterin","body":"Delme, vidalama veya yapıştırma işlemi sırasında takımın hareket edeceği alan fikstür tarafından kapanmamalıdır. Kullanılan bağlama elemanlarının konumu ve erişim açısı numunede kontrol edilir. Bir kılavuz aşınacaksa değiştirilebilir eleman veya farklı malzeme gereksinimi değerlendirilebilir."}]'::jsonb,faq='[{"q":"Baskı şablonuyla doğrudan delme yapılır mı?","a":"Takım yükü, ısı, aşınma ve istenen hassasiyet birlikte incelenmelidir. Yalnızca delik geometrisinin bulunması işlem için yeterlilik göstermez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Boyalı profil veya dekoratif panelin tutulacağı bölge, çizilmeye hassas olabilir.","takeaways":["Profil kesitleri ve panel kalınlıkları","Korunacak dekoratif yüzeyler","Kullanılan el aleti ve hareket yönü"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/sektorler/mimari-tasarim' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mimari ve tasarım","summary":"Kütle, cephe ve yerleşim maketlerinde ölçeği, gösterilecek detayları ve taşıma planını üretimden önce netleştirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçekte okunabilirlik","body":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"title":"Bölünebilir üretim","body":"Maketin sergileneceği alan ve taşınacağı kutu boyutu, parçalara ayırma kararını etkiler. Birleşim yerlerini görünür cephelerden uzaklaştırmak veya sökülebilir kütleler kullanmak tasarım aşamasında değerlendirilebilir. Aydınlatma ve kablo kanalları ayrıca belirtilmelidir."},{"title":"Sunum onayı","body":"Renk, yüzey, etiket ve taban beklentisini referanslarla anlatın. Önce dijital yerleşim, sonra kritik bir detayın numunesi üzerinden karar verin. Son teslimden önce parça listesi ve yerleşim şemasını birlikte kontrol edin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Medikal ekipman üretiminde operasyon dışı montaj yardımcıları',summary='Cihaz geliştirme ve montaj çalışmalarındaki tutucu ihtiyacını temizlenebilirlik, erişim ve kullanım sınırlarıyla tanımlayın.',sections='[{"title":"Yardımcının temasını sınıflandırın","body":"Hangi yüzeylerle temas kurulacağını ve yardımcı parçanın üretim sürecinin neresinde kullanıldığını açıklayın. Özel malzeme, temizlik veya izlenebilirlik şartları yetkili kalite ekibinin tanımladığı gereksinimlerden gelmelidir."},{"title":"Montaj izlerini ve erişimi kontrol edin","body":"Gövde üzerinde çizik veya baskı izi istenmiyorsa temas bölgeleri buna göre seçilir. Kablo, sensör ve küçük bağlantıların operatör tarafından erişilebilir kalması numunede değerlendirilir. İstenen rapor veya doğrulama hizmeti parçanın kendisinden ayrı iş kalemi olarak tekliflenir."}]'::jsonb,faq='[{"q":"Bu kapsam steril veya biyouyumlu ekipman üretimi midir?","a":"Hayır; burada tariflenen ihtiyaç montaj ve geliştirme yardımcılarıdır. Sterilite, hasta teması veya biyouyumluluk gereksinimi ayrıca tanımlanmış süreç ve kanıt ister."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir elektronik kartı montaj sırasında tutan parça ile hasta veya steril ürünle temas eden ekipman aynı kapsam değildir.","takeaways":["Temas edilen yüzeylerin sınıfı","Kalite ekibinin temizlik gereksinimleri","Montaj sırası ve erişim bölgeleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/sektorler/medikal' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Medikal tasarım ve eğitim","summary":"Anlatım, eğitim ve tasarım değerlendirmesi için anatomik gösterim ve cihaz gövdesi prototiplerinin kapsamını belirleyin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kullanım amacını ayırın","body":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"title":"Veri paylaşımı","body":"Gerekli dosya formatını ve görüntüleme beklentisini teknik ekiple belirleyin. Kişisel bilgi içeren görüntü veya dosyaları paylaşmadan önce yetki ve anonimleştirme süreçlerinizi tamamlayın. Teklif aşamasında mümkünse kimlik bilgisi içermeyen geometriyle başlayın."},{"title":"Eğitim modelinin kabulü","body":"Gösterilecek yapıları, renk ayrımını, sökülebilir bölümleri ve kullanılacak ölçeği listeleyin. Modelin anlatım amacına uygunluğunu konu uzmanı değerlendirmelidir. Dijital onay ile fiziksel yüzey beklentisini ayrı adımlarda ele alın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Havacılık Ar-Ge ekiplerine operasyon dışı işlem yardımcıları',summary='Kavramsal yerleşim, montaj erişimi ve kontrollü atölye denemeleri için yardımcı aparat kapsamını tanımlayın.',sections='[{"title":"Görev sınırını teknik talebe yazın","body":"Aparatın üretim, eğitim veya Ar-Ge aşamasındaki görevi açık olmalıdır. Hassas proje verisi paylaşılacaksa yetkili ekip hangi geometrinin ve dosya sürümünün iletileceğini önceden seçer."},{"title":"İzlenebilirliği referanslardan kurun","body":"Parça numarası, aparat revizyonu ve kontrol edilen arayüzler birlikte kaydedilebilir. Numunede hedeflenen dayama ve erişim koşulları fotoğraf veya ölçümle belgelenir. Sektöre özgü sertifikasyon ve tedarikçi onayları varsa bunların mevcut olduğu varsayılmaz; talebin ayrı gereksinimleri olarak değerlendirilir."}]'::jsonb,faq='[{"q":"Uçuşa takılacak parça üretimi bu kapsamda mı?","a":"Bu sayfa operasyon dışı geliştirme ve işlem yardımcılarını ele alır. Uçuş donanımının malzeme, süreç ve uygunluk değerlendirmesi ayrı bir mühendislik kapsamıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir sunum numunesini tutan düzenek ile uçuş sisteminin parçası olan donanım farklı değerlendirmeler gerektirir.","takeaways":["Operasyon dışı kullanım tanımı","Paylaşım izni verilmiş arayüzler","Parça numarası ve revizyon zinciri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/sektorler/savunma-havacilik' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Havacılık ve teknik Ar-Ge","summary":"Form kontrolü, ergonomi ve montaj gösterimi için kullanılan teknik prototipleri izlenebilir bir dosya akışıyla planlayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kapsam ve veri sınırı","body":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"title":"Gösterim ve montaj prototipi","body":"Ergonomi maketi, bağlantı yerleşimi veya dış form numunesinde hangi kararın doğrulanacağını yazın. Görsel prototipin uçuşa elverişlilik veya işlevsel parça sertifikası sağlamadığını proje içinde açıkça ayırın. Kritik işlevler ayrı doğrulama planı gerektirir."},{"title":"İzlenebilir değerlendirme","body":"Dosya adı, parça kodu, revizyon, talep sahibi ve kabul kontrolünü ortak tabloda tutun. Fiziksel numune üzerindeki değişiklikleri dijital modele geri işleyin. Tekrar üretimde onaylı dosyanın aynı olduğundan emin olun."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Laboratuvar deney düzenekleri için tutucu ve yerleştirme parçaları',summary='Sensör, numune ve deney bileşenlerinin konumunu koruyan yardımcıları ölçüm yönteminizle birlikte tarif edin.',sections='[{"title":"Düzeneğin neyi sabitleyeceğini belirleyin","body":"Deneyde değişecek ve sabit kalacak büyüklükleri listeleyin. Tutucunun ölçümü etkileme ihtimali varsa temas kuvveti, titreşim ve erişim şartları çalışma planında yer almalıdır."},{"title":"Deneyler arasında aynı kurulumu sağlayın","body":"Sökülen bir parçanın yeniden aynı yerde durması için referans yüzleri ve montaj yönü belirlenir. Numune kodu, yerleştirme sırası ve bağlantı donanımı kaydedilebilir. Basılmış bir düzeneğin doğruluğu yalnızca çizimdeki ölçüye dayanmaz; deney ekibinin kurulum ve kontrol yöntemiyle değerlendirilir."}]'::jsonb,faq='[{"q":"Aparat ölçüm hatasını ortadan kaldırır mı?","a":"Hayır; düzenek ölçüm zincirinin bir parçasıdır. Kullanılan cihaz, kurulum ve çevre koşullarıyla birlikte belirsizliği değerlendirilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir numunenin dönmesini engellemek, iki sensörü aynı eksende tutmak veya kabloları ayırmak farklı geometriler gerektirir.","takeaways":["Deneyde sabit kalacak referanslar","Sensör veya numune temas noktaları","Kurulumun tekrar edilme biçimi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/sektorler/egitim-arge' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Eğitim ve Ar-Ge","summary":"Fikrinizi test edilebilir numunelere ayırın; bir sonraki tasarım kararını verecek prototipi üretin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Deneyi önce tanımlayın","body":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"title":"Revizyonları karşılaştırın","body":"Alternatifleri dosya adında işaretleyin; yalnızca değişen parametreleri bir tabloyla paylaşın. Deneme sonucunu not ederken kullanılan revizyonu ve test koşullarını ekleyin. Böylece yeni numunenin neden istendiği açık kalır."},{"title":"Bütçe ve adet","body":"Görünüş değerlendirmesi için gereken adetle kullanıcı testi için gereken adet aynı olmayabilir. Önce küçük bir doğrulama grubu planlayın. Malzeme, yüzey ve teslim tarihi seçimlerini deneyin amacıyla birlikte değerlendirin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Obje atölyelerinde yüzey ve montaj yardımcıları',summary='Boyama, birleştirme veya sergileme hazırlığında objeyi kontrollü konumda tutan atölye aparatlarını planlayın.',sections='[{"title":"Temasın iz bırakacağı yeri seçin","body":"Boyanmayan taban, iç hacim veya sonradan kapanacak bölge gibi seçenekler değerlendirilir. Kullanılan boya, yapıştırıcı veya temizleyiciye temas varsa ilgili ürün bilgisi malzeme seçiminde dikkate alınmalıdır."},{"title":"Ürün serisindeki değişkenleri belirleyin","body":"Aynı objenin farklı boyları veya biçim varyantları bulunuyorsa tek tutucuya zorlamak yerine değiştirilebilir yuvalar düşünülebilir. İşlemden sonra objenin elle çıkarılacağı yön ve kuruma için bekleme konumu açıklanır. Yüzey numunesinde iz ve sürtme kontrolü yapılarak gerçek işlem kapsamı kararlaştırılır."}]'::jsonb,faq='[{"q":"Mücevher döküm kalıbı da aynı iş midir?","a":"Hayır; döküm ve sıcak işlem gereksinimleri bu genel tutucu kapsamından ayrıdır. Yalnızca atölye konumlandırma ihtiyacından yola çıkılarak döküm uygunluğu varsayılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"İşlenen objenin görünür yüzeyi, tutma için uygun bir dayama olmayabilir.","takeaways":["Görünür ve temas edilebilir yüzeyler","İşlemde kullanılan kimyasal ürünler","Serideki boyut ve biçim varyantları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/sektorler/sanat-mucevher' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Sanat, obje ve takı tasarımı","summary":"Heykel, obje ve takı tasarımlarında dijital formu fiziksel ölçekte görerek yüzey ve detay kararlarını geliştirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Formun fiziksel etkisi","body":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"title":"Son işlem planı","body":"Boyama, birleştirme veya başka bir üretim sürecine girdi oluşturma amacı varsa bunu baştan belirtin. Kalıp veya döküm sürecine uygunluk ilgili üretim yöntemiyle ayrıca değerlendirilmelidir. Her baskı malzemesinin her son işlemle uyumlu olduğu varsayılmaz."},{"title":"Tasarım hakları","body":"Üretim için ilettiğiniz modelin kullanım hakkının sizde olduğundan emin olun. Sanatçı adı, eser numarası ve revizyonu dosyada takip edin. Görsel sunum numunesi ile satışa çıkacak nihai ürünün kabul ölçütlerini ayrı belirleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Robotik geliştirmede montaj sehpası ve test tutucuları',summary='Robotik bileşenlerin masa üstü montajını ve kontrollü denemelerini kolaylaştıran destek geometrilerini tanımlayın.',sections='[{"title":"Dönme ve hareket hacmini işaretleyin","body":"Enerjisiz montaj desteği ile çalışır sistem testi farklı risk ve kuvvetler taşır. Dönen veya hareket eden elemanların çevresindeki boşluklar tasarım dosyasına eklenmelidir."},{"title":"Kablo ve bileşen değişimini kolaylaştırın","body":"Geliştirme sırasında aynı kart veya motor sıkça sökülebilir. Vida erişimi, konektör yönü ve parçaların yerleştirme sırası bu kullanım biçimine göre değerlendirilir. Numunede devrilme, kayma ve kabloya takılma gibi durumlar kontrollü biçimde incelenerek tasarım revizyonu yapılır."}]'::jsonb,faq='[{"q":"Çalışan pervane için test sehpası yapılabilir mi?","a":"Yük ve güvenli test düzeni uzman değerlendirmesi gerektirir. Genel bir masa üstü tutucu çizimi, çalışan pervane testine uygun kabul edilmez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Motor, tekerlek veya hareketli kol üzerinde çalışma yapılacaksa tutucunun hangi koşulda kullanılacağı net olmalıdır.","takeaways":["Enerjili ve enerjisiz kullanım ayrımı","Hareketli elemanların çalışma hacmi","Sık değiştirilen bileşenler"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/sektorler/drone-hobi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Drone, robotik ve hobi","summary":"Elektronik yerleşimi, kablo yönetimi ve montaj yardımcıları için modelleme ve prototip planınızı oluşturun. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Bileşen yerleşimi","body":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"title":"Deneme koşulları","body":"Titreşim, dış ortam ve hareketli mekanizma ilişkisini belirtin. Uçuş veya yüksek hız gerektiren kullanımda parça doğrulaması ayrıca ele alınmalıdır. Tasarım numunesini doğrudan güvenlik açısından kritik kullanıma uygun kabul etmeyin."},{"title":"Onarım ve değiştirme","body":"Sık sökülecek kapakları, tüketilecek parçaları ve farklı sürümlerde değişecek bağlantıları işaretleyin. Tasarımın servis kolaylığı prototip üzerinden kontrol edilebilir. Sonraki sipariş için onaylanan dosyayı ve bağlantı ölçülerini saklayın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Üretim tesislerinin yerleşimini anlatan sunum maketleri',summary='Fabrika planını, ekipman alanlarını ve malzeme akışını yönetim veya ziyaretçi sunumunda okunabilir hâle getirin.',sections='[{"title":"Ölçekten önce anlatım katmanlarını seçin","body":"Hangi bölümün çıkarılabilir veya renkli gösterileceği belirlenmelidir. Her makinenin gerçek ayrıntısını küçültmek yerine işlevini anlaşılır biçimde temsil etmek, kalabalık bir modelin okunmasını kolaylaştırabilir."},{"title":"Güncel yerleşimi tek dosyada toplayın","body":"Mimari plan, ekipman listesi ve saha değişikliklerinin aynı revizyona ait olması gerekir. Değişmesi beklenen üniteler modüler tasarlanabilir. Maket üzerindeki kodlar teslim listesindeki ünitelerle eşleşirse sonraki güncellemede doğru parçanın değiştirilmesi mümkün olur."}]'::jsonb,faq='[{"q":"Maket üretim kapasitesi hesabının yerine geçer mi?","a":"Hayır; fiziksel model ilişkileri sunar. Kapasite, proses ve güvenli alan bilgileri proje ekibinin doğrulanmış verilerinden gelmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir tesiste yapı kabuğu, üretim hücreleri ve lojistik alanlar farklı bilgi katmanlarıdır.","takeaways":["Anlatılacak operasyon alanları","Güncel yerleşim revizyonu","Modüler olması gereken üniteler"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/sektorler/endustriyel' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Endüstriyel üretim","summary":"Üretim hattındaki özel aparat, montaj yardımcısı ve düşük adetli parça ihtiyaçlarını aynı teknik briefte toplayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hattaki görevi tarif edin","body":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"title":"Pilot parçadan onaylı revizyona","body":"İlk numuneyi gerçek montaj noktasında değerlendirecek kişiyi belirleyin. Uyum, erişim ve operatör kullanımı ayrı kontrol başlıkları olmalıdır. Numune üzerinde yapılan değişiklikleri çizim revizyonuna işleyin; seri talebi yalnızca onaylanan dosyaya bağlayın."},{"title":"Satın alma dosyası","body":"Talebe parça kodu, adet, malzeme beklentisi ve kabul ölçütlerini ekleyin. Birden fazla parçanın aynı siparişte değerlendirilmesi gerekiyorsa dosya adlarını adet tablosuyla eşleştirin. Tekrarlı siparişlerde önceki revizyon ve değişen koşulları belirtin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Otomotiv tesisleri ve showroomlar için ölçekli sunum',summary='Üretim alanı veya sergileme düzeninin araç, dolaşım ve yapı ilişkilerini fiziksel model üzerinde gösterin.',sections='[{"title":"Araç detayını anlatıma göre seçin","body":"Hedef ölçekte hangi parçaların simgesel gösterileceği belirlenir. Marka logosu veya belirli araç modeli kullanılacaksa sağlanan dosyaların kullanım yetkisi proje sahibince teyit edilmelidir."},{"title":"Sunum mekânını teslim planına katın","body":"Modelin kaidesi, izleme yüksekliği ve etrafında dolaşılacak alan tasarım kararını etkiler. Değişebilir araç yerleşimleri için sökülebilir parçalar planlanabilir. Taşıma sırasında kaybolabilecek küçük elemanlar teslim sayımı ve saklama düzenine dâhil edilir."}]'::jsonb,faq='[{"q":"Gerçek aracın üretim modeli mi hazırlanır?","a":"Bu kapsam ölçekli sunum ve yerleşim maketidir. Araç mühendisliği, üretim kalıbı veya işlevli otomotiv bileşeni tasarımı ayrı işlerdir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Showroom yerleşiminde araçların kapladığı hacim ve ziyaretçi dolaşımı, küçük dış tasarım ayrıntılarından daha önemli olabilir.","takeaways":["Showroom veya tesis planı","Araçların temsil ayrıntısı","Kaide ve izleme yüksekliği"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/sektorler/otomotiv' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Otomotiv ve yedek parça","summary":"Trim, kapak, klips ve prototip parçalarında numuneden modele uzanan süreci kullanım koşullarıyla birlikte planlayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Montaj ilişkisini koruyun","body":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"title":"Ortam koşullarını paylaşın","body":"İç mekân, güneş gören bölge veya motor çevresi farklı koşullar taşır. Sıcaklık, titreşim, kimyasal temas ve beklenen kullanım ömrünü anlatın. Görünüş numunesi ile işlevsel kullanım parçasını aynı kabul kriteriyle değerlendirmeyin."},{"title":"Doğrulama kapsamı","body":"Emniyet açısından kritik bir parçanın yeniden üretilmesi ayrıca mühendislik doğrulaması gerektirir. Talepte parçanın görevini açıkça belirtin. Prototipin montaja oturması, tek başına güvenli kullanım onayı anlamına gelmez."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mimarlık ofislerine tasarım ve jüri maketleri',summary='Kütle, boşluk, cephe ve arazi kararlarını projenin aşamasına uygun ölçekli modellerle görünür kılın.',sections='[{"title":"Jüride sorulacak soruyu belirleyin","body":"Avlu ilişkisi, güneşlenme fikri veya dolaşım kararı gibi odaklar seçilebilir. Kesit alınacak yer ve çıkarılacak katlar, model üretildikten sonra değil tasarım aşamasında kararlaştırılmalıdır."},{"title":"Dijital modeli maket diline uyarlayın","body":"BIM veya çizim modelindeki her katman baskıya doğrudan uygun olmayabilir. Gereksiz iç elemanların temizlenmesi, ince detayların temsil biçimi ve parçaların birleştirme yöntemi değerlendirilir. Maket ölçeğine göre sadeleştirme yapılan alanlar proje ekibinin onayına sunulmalıdır."}]'::jsonb,faq='[{"q":"BIM dosyası doğrudan baskı dosyası mıdır?","a":"Çoğu projede model temizliği, ölçek ve üretim hazırlığı gerekir. Kaynak formatı, dışa aktarım ve hangi detayların korunacağı baştan konuşulmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir kütle alternatifini tartışmak ile bitmiş projeyi anlatmak aynı maketi gerektirmez.","takeaways":["Sunumun ana tasarım sorusu","Kesit ve çıkarılabilir katlar","Korunacak ve sadeleştirilecek detaylar"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/sektorler/mimari-tasarim' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mimari ve tasarım","summary":"Kütle, cephe ve yerleşim maketlerinde ölçeği, gösterilecek detayları ve taşıma planını üretimden önce netleştirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçekte okunabilirlik","body":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"title":"Bölünebilir üretim","body":"Maketin sergileneceği alan ve taşınacağı kutu boyutu, parçalara ayırma kararını etkiler. Birleşim yerlerini görünür cephelerden uzaklaştırmak veya sökülebilir kütleler kullanmak tasarım aşamasında değerlendirilebilir. Aydınlatma ve kablo kanalları ayrıca belirtilmelidir."},{"title":"Sunum onayı","body":"Renk, yüzey, etiket ve taban beklentisini referanslarla anlatın. Önce dijital yerleşim, sonra kritik bir detayın numunesi üzerinden karar verin. Son teslimden önce parça listesi ve yerleşim şemasını birlikte kontrol edin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Sağlık yapıları için mekânsal eğitim ve sunum maketi',summary='Klinik bina, laboratuvar ve eğitim alanlarının yerleşim ilişkilerini hasta verisi içermeyen ölçekli modellerle anlatın.',sections='[{"title":"Mekân akışını anlaşılır kılın","body":"Kullanılacak renklerin neyi temsil ettiği açıklanmalı; mahremiyet veya işletme güvenliği nedeniyle paylaşılmaması gereken alanlar proje sahibi tarafından seçilmelidir. Maket, yetkili planların görsel anlatımıdır."},{"title":"Eğitim için çıkarılabilir katlar planlayın","body":"İç mekânın görülmesi gerekiyorsa katların sökülme sırası ve tutulacak yüzler tanımlanır. Kırılgan bölümler yoğun kullanımda sorun yaratabilir; duvar ve kapı temsilinde okunabilirlik ile sağlamlık dengelenir. Sergileme ve eğitim kullanımının farklı bakım ihtiyaçları olduğu teklif kapsamında belirtilir."}]'::jsonb,faq='[{"q":"Bu hizmet anatomik veya klinik model üretimi midir?","a":"Bu sayfa sağlık yapılarının mekânsal sunumunu ele alır. Hasta özelinde anatomik model veya klinik planlama gereksinimleri ayrıca değerlendirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir sağlık yapısında bekleme, dolaşım ve çalışma alanlarını aynı modelde göstermek sunumu destekleyebilir.","takeaways":["Paylaşılabilir mimari yerleşim","Gösterilecek dolaşım ilişkileri","Katların açılma ve tutulma biçimi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/sektorler/medikal' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Medikal tasarım ve eğitim","summary":"Anlatım, eğitim ve tasarım değerlendirmesi için anatomik gösterim ve cihaz gövdesi prototiplerinin kapsamını belirleyin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kullanım amacını ayırın","body":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"title":"Veri paylaşımı","body":"Gerekli dosya formatını ve görüntüleme beklentisini teknik ekiple belirleyin. Kişisel bilgi içeren görüntü veya dosyaları paylaşmadan önce yetki ve anonimleştirme süreçlerinizi tamamlayın. Teklif aşamasında mümkünse kimlik bilgisi içermeyen geometriyle başlayın."},{"title":"Eğitim modelinin kabulü","body":"Gösterilecek yapıları, renk ayrımını, sökülebilir bölümleri ve kullanılacak ölçeği listeleyin. Modelin anlatım amacına uygunluğunu konu uzmanı değerlendirmelidir. Dijital onay ile fiziksel yüzey beklentisini ayrı adımlarda ele alın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Havacılık yerleşkeleri için kavramsal tesis maketleri',summary='Hangar, yapı grubu ve operasyon alanlarını onaylanmış sunum verisiyle fiziksel yerleşim modeline dönüştürün.',sections='[{"title":"Sunulabilir veriyi proje sahibi belirler","body":"Kavramsal sunum için gerekli olmayan iç düzen ve hassas bilgi paylaşılmayabilir. Maketteki her etiket ve ünite, sunum için onaylanan dosya listesiyle eşleştirilir."},{"title":"Büyük yerleşimi okunabilir parçalara ayırın","body":"Geniş bir alanı tek tabana sığdırmak yapıların çok küçülmesine yol açabilir. Genel yerleşim ile belirli bir hangarın detay modeli ayrı ölçeklerde hazırlanabilir. Bu ölçek farkı sunumda açıkça gösterilmeli; modüllerin birleştirme ve taşıma planı teslim kapsamına girmelidir."}]'::jsonb,faq='[{"q":"Operasyonel ekipman veya parça üretiliyor mu?","a":"Bu kapsam yalnızca kavramsal sunum maketidir. İşlevli sistem veya uçuş donanımı üretimi anlamına gelmez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Yerleşke maketinde görülecek yapı ve ekipman ayrıntısının kapsamı yetkili ekipten gelmelidir.","takeaways":["Sunuma izin verilen yapı listesi","Genel yerleşim ve detay modeli sınırları","Etiket ve dosya onay sorumlusu"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/sektorler/savunma-havacilik' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Havacılık ve teknik Ar-Ge","summary":"Form kontrolü, ergonomi ve montaj gösterimi için kullanılan teknik prototipleri izlenebilir bir dosya akışıyla planlayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kapsam ve veri sınırı","body":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"title":"Gösterim ve montaj prototipi","body":"Ergonomi maketi, bağlantı yerleşimi veya dış form numunesinde hangi kararın doğrulanacağını yazın. Görsel prototipin uçuşa elverişlilik veya işlevsel parça sertifikası sağlamadığını proje içinde açıkça ayırın. Kritik işlevler ayrı doğrulama planı gerektirir."},{"title":"İzlenebilir değerlendirme","body":"Dosya adı, parça kodu, revizyon, talep sahibi ve kabul kontrolünü ortak tabloda tutun. Fiziksel numune üzerindeki değişiklikleri dijital modele geri işleyin. Tekrar üretimde onaylı dosyanın aynı olduğundan emin olun."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Atölye, üniversite ve araştırma sunumları için maket',summary='Bir kavramı dokunarak açıklamak için ölçek, sökülebilirlik ve tekrar kullanım ihtiyaçlarını birlikte planlayın.',sections='[{"title":"Öğrenme hedefini fiziksel harekete çevirin","body":"Öğrencinin ya da izleyicinin yapacağı hareket tasarım girdisidir. Her ayrıntıyı göstermek yerine tek bir kavramı açık anlatan bölümler seçmek, modelin kalabalıklaşmasını azaltır."},{"title":"Yoğun kullanımın bağlantılarını düşünün","body":"Sökülüp takılan parçaların kodlanması, yönünün anlaşılması ve kaybolmadan saklanması gerekir. Küçük veya sivri elemanların uygunluğu hedef yaş grubu ve kullanım ortamına göre değerlendirilir. Öğretim modeli; bilimsel ölçüm veya gerçek sistem performansını kendi başına doğrulamaz."}]'::jsonb,faq='[{"q":"Aynı maket farklı derslerde kullanılabilir mi?","a":"Ortak taban ve değiştirilebilir modüller uygun olabilir. Her modülün hangi kavramı anlattığı ve nasıl saklanacağı teslim listesinde belirtilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir kesiti açmak, katları ayırmak veya farklı yerleşimleri değiştirmek maketi anlatım aracına dönüştürebilir.","takeaways":["Anlatılacak kavram ve kullanıcı grubu","İzleyicinin yapacağı fiziksel hareket","Modüllerin kodlama ve saklama planı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/sektorler/egitim-arge' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Eğitim ve Ar-Ge","summary":"Fikrinizi test edilebilir numunelere ayırın; bir sonraki tasarım kararını verecek prototipi üretin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Deneyi önce tanımlayın","body":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"title":"Revizyonları karşılaştırın","body":"Alternatifleri dosya adında işaretleyin; yalnızca değişen parametreleri bir tabloyla paylaşın. Deneme sonucunu not ederken kullanılan revizyonu ve test koşullarını ekleyin. Böylece yeni numunenin neden istendiği açık kalır."},{"title":"Bütçe ve adet","body":"Görünüş değerlendirmesi için gereken adetle kullanıcı testi için gereken adet aynı olmayabilir. Önce küçük bir doğrulama grubu planlayın. Malzeme, yüzey ve teslim tarihi seçimlerini deneyin amacıyla birlikte değerlendirin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Sergi mekânları ve heykel yerleşimleri için sunum modeli',summary='Obje, kaide ve ziyaretçi alanının ilişkisini ölçekli bir sahne üzerinde karşılaştırın.',sections='[{"title":"Eseri mekânından ayrı düşünmeyin","body":"Bir galeri veya açık alan planına eserlerin basitleştirilmiş kütleleri yerleştirilebilir. Temsil edilecek eser dosyaları ve görseller için gerekli kullanım izni proje sahibinin paylaşım kapsamındadır."},{"title":"Değişen düzen için sökülebilir parçalar kullanın","body":"Sergi senaryoları karşılaştırılacaksa eserler ve kaideler kodlanmış modüller hâlinde tasarlanabilir. Ölçeğin küçük olması ince sanat ayrıntılarının aynı biçimde üretileceği anlamına gelmez. Makette korunacak silüet ve oranlar belirlenerek detaylar bilinçli biçimde sadeleştirilir."}]'::jsonb,faq='[{"q":"Maket eserin kopyası olarak satılabilir mi?","a":"Bu çalışma yerleşim sunumu içindir. Eserin çoğaltılması ve ticari kullanımı için gerekli haklar ayrı değerlendirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Heykelin yüksekliği kadar çevresindeki boşluk ve ziyaretçinin bakış yönü de sunumu etkiler.","takeaways":["Sergi planı ve izleme yönleri","Eserlerin dış ölçü ve silüetleri","Değişebilir kaide yerleşimleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/sektorler/sanat-mucevher' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Sanat, obje ve takı tasarımı","summary":"Heykel, obje ve takı tasarımlarında dijital formu fiziksel ölçekte görerek yüzey ve detay kararlarını geliştirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Formun fiziksel etkisi","body":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"title":"Son işlem planı","body":"Boyama, birleştirme veya başka bir üretim sürecine girdi oluşturma amacı varsa bunu baştan belirtin. Kalıp veya döküm sürecine uygunluk ilgili üretim yöntemiyle ayrıca değerlendirilmelidir. Her baskı malzemesinin her son işlemle uyumlu olduğu varsayılmaz."},{"title":"Tasarım hakları","body":"Üretim için ilettiğiniz modelin kullanım hakkının sizde olduğundan emin olun. Sanatçı adı, eser numarası ve revizyonu dosyada takip edin. Görsel sunum numunesi ile satışa çıkacak nihai ürünün kabul ölçütlerini ayrı belirleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Robotik etkinlikler ve model sahalar için ölçekli çevre',summary='Parkur, arazi veya çalışma alanını sunum ve masa üstü senaryo için fiziksel bir çevre modeli olarak hazırlayın.',sections='[{"title":"Modelin simülasyon sınırını açıklayın","body":"Maketin amacı yerleşimi anlatmak veya senaryo tartışmaksa bunu baştan belirtin. Engel konumları, görüş hatları ve giriş noktaları gibi mekânsal öğeler modelde öne çıkarılabilir."},{"title":"Parkuru modüllerle güncelleyin","body":"Engellerin ve arazi bölümlerinin yeniden yerleşebilmesi için ortak taban bağlantıları düşünülebilir. Her parçanın yönü ve ölçeği işaretlenir. Taşınacak bir modelde toplam boyut, kasa ve kurulum sırası etkinlik programından bağımsız bırakılmamalıdır."}]'::jsonb,faq='[{"q":"Bu maket uçuş veya robot testi için doğrulama sağlar mı?","a":"Yerleşim modeli senaryoyu anlatır; fiziksel test veya güvenlik doğrulamasının yerine geçmez. Gerçek sistem testleri kendi yöntem ve koşullarında yapılmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir robot parkurunu küçültmek, gerçek robotun fiziksel davranışını aynı oranda küçültmez.","takeaways":["Senaryoda anlatılacak alanlar","Değişebilir engel ve modüller","Etkinlikte kurulum ve taşıma planı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/sektorler/drone-hobi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Drone, robotik ve hobi","summary":"Elektronik yerleşimi, kablo yönetimi ve montaj yardımcıları için modelleme ve prototip planınızı oluşturun. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Bileşen yerleşimi","body":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"title":"Deneme koşulları","body":"Titreşim, dış ortam ve hareketli mekanizma ilişkisini belirtin. Uçuş veya yüksek hız gerektiren kullanımda parça doğrulaması ayrıca ele alınmalıdır. Tasarım numunesini doğrudan güvenlik açısından kritik kullanıma uygun kabul etmeyin."},{"title":"Onarım ve değiştirme","body":"Sık sökülecek kapakları, tüketilecek parçaları ve farklı sürümlerde değişecek bağlantıları işaretleyin. Tasarımın servis kolaylığı prototip üzerinden kontrol edilebilir. Sonraki sipariş için onaylanan dosyayı ve bağlantı ölçülerini saklayın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Eski ekipmanlar için yardımcı plastik parça yenileme',summary='Katalogda bulunamayan kapak, yönlendirici ve yardımcı bağlantıları cihazın görev sınırları içinde değerlendirin.',sections='[{"title":"Yedek parçanın neyi etkilediğini anlayın","body":"Parçanın söküldüğü bölgeyi ve makinenin işlevini gösterin. Mevcut malzeme, aşınma ve bağlantı hasarı gözlemleri yeni modelin hangi bölümlerinin gözden geçirileceğine yardımcı olur."},{"title":"Eski karşı parçayla eşleştirme yapın","body":"Yıllar içinde gövde deliği, vida veya yuva değişmiş olabilir. Teknik resim ile sahadaki ölçü aynı değilse gerçek montaj referansı açıklanmalıdır. İlk örnekte bağlantı ve erişim kontrolü yapıldıktan sonra kullanım koşuluna uygunluk ayrı değerlendirilir."}]'::jsonb,faq='[{"q":"Her eski makine parçası baskıyla yenilenebilir mi?","a":"Hayır; yük, sıcaklık, emniyet görevi ve üretici gereksinimleri belirleyicidir. Yardımcı plastik parça ihtiyacı ile kritik makine elemanı birbirinden ayrılmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir toz kapağı ile hareketli elemanı koruyan güvenlik muhafazası aynı şekilde ele alınamaz.","takeaways":["Ekipmanın modeli ve parça görevi","Montaj yuvasının güncel durumu","Aşınma ve önceki tamir izleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/sektorler/endustriyel' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Endüstriyel üretim","summary":"Üretim hattındaki özel aparat, montaj yardımcısı ve düşük adetli parça ihtiyaçlarını aynı teknik briefte toplayın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hattaki görevi tarif edin","body":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"title":"Pilot parçadan onaylı revizyona","body":"İlk numuneyi gerçek montaj noktasında değerlendirecek kişiyi belirleyin. Uyum, erişim ve operatör kullanımı ayrı kontrol başlıkları olmalıdır. Numune üzerinde yapılan değişiklikleri çizim revizyonuna işleyin; seri talebi yalnızca onaylanan dosyaya bağlayın."},{"title":"Satın alma dosyası","body":"Talebe parça kodu, adet, malzeme beklentisi ve kabul ölçütlerini ekleyin. Birden fazla parçanın aynı siparişte değerlendirilmesi gerekiyorsa dosya adlarını adet tablosuyla eşleştirin. Tekrarlı siparişlerde önceki revizyon ve değişen koşulları belirtin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parçanın hangi operasyonda kullanıldığını, operatörün nasıl tuttuğunu ve hangi yüzeylerin referans alındığını açıklayın. Çevrim sırasında oluşan yük, sıcaklık ve kimyasal temas bilgisi üretim kararının girdisidir. Mevcut çizim varsa kritik ölçüleri ayrı işaretleyin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Restorasyon ve servis için özel iç trim parçaları',summary='Eksik veya kırık güvenlik kritik olmayan plastik parçaları araç varyantı ve gerçek montaj örneği üzerinden ele alın.',sections='[{"title":"Model yılı ve donanımı dosyaya ekleyin","body":"Varsa parça numarası ile ön ve arka yüz fotoğraflarını paylaşın. Sağlam bir karşı örnek bulunuyorsa kırık tırnakların biçimini anlamak kolaylaşır; fotoğraftan kritik ölçü tahmini nihai ölçü yerine kullanılmaz."},{"title":"Görünüş onayını uyumdan sonra verin","body":"Önce bağlantı bölgesi denenerek montaj kararının doğruluğu görülür. Sonra renk, doku ve görünür kenarlar üzerinde çalışılır. Özel üretilmiş parçanın orijinal üretici parçası veya onaylı güvenlik bileşeni olduğu ileri sürülmez; kullanım görevi teklif değerlendirmesinde açıklanır."}]'::jsonb,faq='[{"q":"Kaput altı veya emniyet sistemi parçası yapılır mı?","a":"Isı, yük ve güvenlik gereksinimleri farklıdır. Bu sayfadaki genel iç trim yaklaşımı bu parçalara otomatik uygulanamaz; görev özel değerlendirme gerektirir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Aynı kasa içinde bile düğme, hava kanalı veya kapak bağlantısı değişebilir.","takeaways":["Araç yılı, donanım ve parça kodu","Kırık bağlantılarla montaj yuvası","Renk ve doku beklentisi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/sektorler/otomotiv' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Otomotiv ve yedek parça","summary":"Trim, kapak, klips ve prototip parçalarında numuneden modele uzanan süreci kullanım koşullarıyla birlikte planlayın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Montaj ilişkisini koruyun","body":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"title":"Ortam koşullarını paylaşın","body":"İç mekân, güneş gören bölge veya motor çevresi farklı koşullar taşır. Sıcaklık, titreşim, kimyasal temas ve beklenen kullanım ömrünü anlatın. Görünüş numunesi ile işlevsel kullanım parçasını aynı kabul kriteriyle değerlendirmeyin."},{"title":"Doğrulama kapsamı","body":"Emniyet açısından kritik bir parçanın yeniden üretilmesi ayrıca mühendislik doğrulaması gerektirir. Talepte parçanın görevini açıkça belirtin. Prototipin montaja oturması, tek başına güvenli kullanım onayı anlamına gelmez."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tek başına kırık parçanın fotoğrafı her zaman yeterli değildir. Parçanın takıldığı bölgeyi, sağlam eşini ve bağlantı elemanlarını da gösterin. Geçme yönü ve esnemesi gereken bölgeler işaretlenirse modelleme kapsamı daha doğru belirlenir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mobilya ve iç mekân ürünleri için özel plastik parçalar',summary='Bulunamayan kapak, profil ucu ve yardımcı bağlantıları kullanılacağı ürünün ölçü ve yüzeyleriyle birlikte değerlendirin.',sections='[{"title":"Görünmeyen bağlantıyı da belgeleyin","body":"Sökülmüş parçanın tüm yüzlerini, profil kesitini ve takılacağı yuvayı gösterin. Yaşlanmış veya eğilmiş karşı parça varsa yeni tasarımın hangi ölçüyü esas alacağı birlikte belirlenir."},{"title":"Yük taşıma görevini ayrı konuşun","body":"Dekoratif kapak ile raf, ayak veya menteşe bağlantısı farklı beklentiler taşır. Sürekli yük, çocukların erişimi veya devrilme ile ilişkili görevler açıklanmalıdır. İlk numunede yüzey izi, boşluk ve sökme hareketi incelenerek montajın zarar vermeden gerçekleştiği değerlendirilir."}]'::jsonb,faq='[{"q":"Görünen parçanın rengi mobilyayla eşleşir mi?","a":"Yakın renk seçimi ile birebir yüzey eşleşmesi aynı şey değildir. Fiziksel referans ve son işlem beklentisi üzerinden numune onayı gerekir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir mobilya kapağının dış ölçüsü doğru olsa bile arkadaki geçme veya vida yatağı uyumsuz olabilir.","takeaways":["Profil veya yuva kesit ölçüsü","Parçanın yük taşıma görevi","Mobilya yüzeyinden renk referansı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/sektorler/mimari-tasarim' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Mimari ve tasarım","summary":"Kütle, cephe ve yerleşim maketlerinde ölçeği, gösterilecek detayları ve taşıma planını üretimden önce netleştirin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçekte okunabilirlik","body":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"title":"Bölünebilir üretim","body":"Maketin sergileneceği alan ve taşınacağı kutu boyutu, parçalara ayırma kararını etkiler. Birleşim yerlerini görünür cephelerden uzaklaştırmak veya sökülebilir kütleler kullanmak tasarım aşamasında değerlendirilebilir. Aydınlatma ve kablo kanalları ayrıca belirtilmelidir."},{"title":"Sunum onayı","body":"Renk, yüzey, etiket ve taban beklentisini referanslarla anlatın. Önce dijital yerleşim, sonra kritik bir detayın numunesi üzerinden karar verin. Son teslimden önce parça listesi ve yerleşim şemasını birlikte kontrol edin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kaynak modelin birimini, hedef maket ölçeğini ve bitmiş taban ölçüsünü paylaşın. Cephedeki çok küçük detayların fiziksel makette nasıl temsil edileceğini kararlaştırın. Peyzaj, kütle ve iç mekân farklı ayrıntı seviyelerinde ele alınabilir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Eğitim ekipmanları için klinik kullanım dışı plastik parçalar',summary='Demonstrasyon cihazı ve eğitim modelindeki yardımcı kapak veya bağlantı ihtiyacını kullanım alanı açıkça belirtilerek değerlendirin.',sections='[{"title":"Klinik temas olup olmadığını belirtin","body":"Yenilenecek elemanın kimle ve hangi yüzeylerle temas ettiği açıklanmalıdır. Hasta teması, temizlik, sterilizasyon veya cihaz güvenliği gereksinimi varsa bunlar yetkili ekip değerlendirmesi olmadan sıradan baskı işi olarak kabul edilmez."},{"title":"Setin diğer parçalarıyla uyumu koruyun","body":"Eski eğitim modelinin bağlantı yuvası ve sökülüp takılan elemanları birlikte görülmelidir. Sınıf kullanımında yönün anlaşılması, küçük parçaların kaybolması ve saklama düzeni tasarımı etkileyebilir. İlk örnek, amaçlanan eğitim hareketi ve bakım biçimi içinde incelenir."}]'::jsonb,faq='[{"q":"Bu parçalar medikal sertifikalı olarak mı sunulur?","a":"Bu kapsam klinik kullanım dışı eğitim yardımcılarını ele alır. Medikal uygunluk, biyouyumluluk veya sterilite belgesi varsayılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Eğitim setinin saklama kapağı ile hastaya uygulanan bir cihazın parçası aynı talep değildir.","takeaways":["Eğitim kullanımının açık tanımı","Temas ve temizlik gereksinimleri","Setin eşleşen bağlantı parçaları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/sektorler/medikal' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Medikal tasarım ve eğitim","summary":"Anlatım, eğitim ve tasarım değerlendirmesi için anatomik gösterim ve cihaz gövdesi prototiplerinin kapsamını belirleyin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kullanım amacını ayırın","body":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"title":"Veri paylaşımı","body":"Gerekli dosya formatını ve görüntüleme beklentisini teknik ekiple belirleyin. Kişisel bilgi içeren görüntü veya dosyaları paylaşmadan önce yetki ve anonimleştirme süreçlerinizi tamamlayın. Teklif aşamasında mümkünse kimlik bilgisi içermeyen geometriyle başlayın."},{"title":"Eğitim modelinin kabulü","body":"Gösterilecek yapıları, renk ayrımını, sökülebilir bölümleri ve kullanılacak ölçeği listeleyin. Modelin anlatım amacına uygunluğunu konu uzmanı değerlendirmelidir. Dijital onay ile fiziksel yüzey beklentisini ayrı adımlarda ele alın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Eğitimde gösterim, cihazın form kontrolü ve klinik kullanım birbirinden farklı kapsamlar taşır. Talebinizin hangi amaçla kullanılacağını açıkça yazın. Bu sayfadaki prototipleme yaklaşımı klinik uygunluk, sterilizasyon veya hasta temasına ilişkin bir onay değildir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Teknik eğitim ve sergi modellerinde plastik parça yenileme',summary='Operasyon dışı demonstrasyon modelinin eksik kapak veya bağlantısını onaylı geometri ve kullanım sınırlarıyla hazırlayın.',sections='[{"title":"Referans modelin statüsünü yazın","body":"Talep, modelin eğitim veya sunum amaçlı olduğunu açıkça belirtmelidir. Paylaşılabilecek ölçü ve görseller yetkili proje sahibince seçilir; gizlilik talebi veri iletilmeden önce görüşülebilir."},{"title":"Sunum kullanımındaki dayanımı değerlendirin","body":"Sökülüp takılan kapakların yönü, tutma yüzeyleri ve saklanması düşünülebilir. Eksik bağlantı yeniden tasarlanacaksa hangi referanslardan yararlanıldığı kaydedilir. Operasyonel veya uçuşa ait yük ve uygunluk iddiaları bu sunum modeli çalışmasından çıkarılmaz."}]'::jsonb,faq='[{"q":"Gerçek donanımın yedeği olarak kullanılabilir mi?","a":"Bu sayfadaki yaklaşım eğitim ve sergi parçaları içindir. Operasyonel kullanımın mühendislik, malzeme ve onay gereksinimleri farklıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir sergi modelinin parçası ile gerçek donanımda çalışan bir eleman aynı kabul planını paylaşmaz.","takeaways":["Modelin eğitim veya sergi kimliği","Paylaşımına izin verilen referanslar","Sökme-takma ve saklama ihtiyacı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/sektorler/savunma-havacilik' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Havacılık ve teknik Ar-Ge","summary":"Form kontrolü, ergonomi ve montaj gösterimi için kullanılan teknik prototipleri izlenebilir bir dosya akışıyla planlayın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kapsam ve veri sınırı","body":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"title":"Gösterim ve montaj prototipi","body":"Ergonomi maketi, bağlantı yerleşimi veya dış form numunesinde hangi kararın doğrulanacağını yazın. Görsel prototipin uçuşa elverişlilik veya işlevsel parça sertifikası sağlamadığını proje içinde açıkça ayırın. Kritik işlevler ayrı doğrulama planı gerektirir."},{"title":"İzlenebilir değerlendirme","body":"Dosya adı, parça kodu, revizyon, talep sahibi ve kabul kontrolünü ortak tabloda tutun. Fiziksel numune üzerindeki değişiklikleri dijital modele geri işleyin. Tekrar üretimde onaylı dosyanın aynı olduğundan emin olun."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Paylaşıma yetkili olduğunuz çizimleri ve kullanım amacı bilgisini talebe ekleyin. İlk değerlendirme için gerekli olmayan hassas proje detaylarını kapsam dışında tutun. Dosya erişimi, gizlilik ve revizyon sorumluları teklif öncesinde belirlenmelidir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Laboratuvar ve eğitim setlerinde eksik plastik parçalar',summary='Bir deney setinin kapağı, taşıyıcısı veya yardımcı bağlantısını işlevi ve eşleşen elemanlarıyla birlikte yeniden değerlendirin.',sections='[{"title":"Setin çalışma mantığını anlatın","body":"Numuneyi hangi hareketin tuttuğunu, hangi bileşenin yerine oturduğunu ve ölçümle ilişkisi olup olmadığını gösterin. Bu bilgiler, basit bir koruyucu ile deney sonucunu etkileyen bir elemanı ayırt etmeye yardımcı olur."},{"title":"Kodlama ve kullanım sırasını koruyun","body":"Eğitim setlerinde yanlış parçanın yanlış yuvaya takılması öğrenme akışını bozabilir. Renk veya biçimle ayırt etme düşünülebilir; kullanılan işaretlerin mevcut yönergelerle uyumu kontrol edilir. Tekrar üretilecek parçalar için dosya sürümü ve fiziksel örnek aynı kayıt altında tutulur."}]'::jsonb,faq='[{"q":"Bir parçayı farklı eğitim setlerine uyarlayabilir miyiz?","a":"Eşleşen ölçüler ve işlevler karşılaştırılmalıdır. Benzer görünüş tek başına uyum anlamına gelmez; her arayüzün numune kontrolü planlanır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Eksik parçanın yalnızca görünüşünü bilmek hangi görevi taşıdığını açıklamaz.","takeaways":["Eğitim setinin kullanım adımları","Eşleşen bileşenlerin ölçüleri","Kod veya renk eşleştirme düzeni"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/sektorler/egitim-arge' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Eğitim ve Ar-Ge","summary":"Fikrinizi test edilebilir numunelere ayırın; bir sonraki tasarım kararını verecek prototipi üretin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Deneyi önce tanımlayın","body":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"title":"Revizyonları karşılaştırın","body":"Alternatifleri dosya adında işaretleyin; yalnızca değişen parametreleri bir tabloyla paylaşın. Deneme sonucunu not ederken kullanılan revizyonu ve test koşullarını ekleyin. Böylece yeni numunenin neden istendiği açık kalır."},{"title":"Bütçe ve adet","body":"Görünüş değerlendirmesi için gereken adetle kullanıcı testi için gereken adet aynı olmayabilir. Önce küçük bir doğrulama grubu planlayın. Malzeme, yüzey ve teslim tarihi seçimlerini deneyin amacıyla birlikte değerlendirin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Bu numuneyle hangi soruya yanıt aradığınızı yazın. Form, mekanizma hareketi ve montaj uyumu farklı deneylerdir. Her birini aynı prototipte çözmeye çalışmak yerine karar sırasına göre ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Dekoratif objeler için özel ayak, kapak ve bağlantılar',summary='Eski veya özgün tasarım objelerin eksik yardımcı parçalarını yüzey, denge ve montaj beklentileriyle değerlendirin.',sections='[{"title":"Objenin görünür karakterini koruyun","body":"Sağlam örnek, alt yüzey fotoğrafı ve gerçek ölçüler başlangıç verisidir. Sanat eserinin kendisini çoğaltma veya üçüncü tarafa ait tasarımı ticari kullanma yetkisi, yardımcı parçanın teknik çalışmasından ayrı ele alınır."},{"title":"Temas yüzeyinde iz ve dengeyi inceleyin","body":"Sert bir ayağın hassas yüzeye iz bırakması veya küçük bir bağlantının objeyi eğik tutması istenmeyebilir. Numunede temas, kayma ve montaj yönü değerlendirilir. Parçanın ağırlık taşıması hâlinde yük ve devrilme koşulları ayrıca açıklanmalıdır."}]'::jsonb,faq='[{"q":"Eksik süs parçası fotoğraftan tamamlanabilir mi?","a":"Fotoğraf biçim için referans olabilir; görünmeyen yüzeyler ve ölçüler için ek bilgi gerekir. Modelleme yorumları fiziksel üretimden önce gözden geçirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Yeni bir kapak ya da ayak, objenin silüetini ve masadaki duruşunu değiştirebilir.","takeaways":["Sağlam biçim veya eski fotoğraf","Objenin alt yüzeyi ve denge noktaları","Temas edeceği masa veya vitrin yüzeyi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/sektorler/sanat-mucevher' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Sanat, obje ve takı tasarımı","summary":"Heykel, obje ve takı tasarımlarında dijital formu fiziksel ölçekte görerek yüzey ve detay kararlarını geliştirin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Formun fiziksel etkisi","body":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"title":"Son işlem planı","body":"Boyama, birleştirme veya başka bir üretim sürecine girdi oluşturma amacı varsa bunu baştan belirtin. Kalıp veya döküm sürecine uygunluk ilgili üretim yöntemiyle ayrıca değerlendirilmelidir. Her baskı malzemesinin her son işlemle uyumlu olduğu varsayılmaz."},{"title":"Tasarım hakları","body":"Üretim için ilettiğiniz modelin kullanım hakkının sizde olduğundan emin olun. Sanatçı adı, eser numarası ve revizyonu dosyada takip edin. Görsel sunum numunesi ile satışa çıkacak nihai ürünün kabul ölçütlerini ayrı belirleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Ekranda büyük görünen bir detay gerçek ölçekte kaybolabilir. Hedef ölçüyü, tutulacak yüzeyleri ve sergileme yönünü paylaşın. Organik modellerde yüzey sürekliliği ile bilinçli doku kararlarını ayırın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Hobi ve robotik projeleri için özel yardımcı parçalar',summary='Kayıp kapak, kablo yönlendirici veya hafif aksesuar bağlantısını kendi bileşenlerinizin ölçüsüne göre değerlendirin.',sections='[{"title":"Hazır modelin uyumunu kontrol edin","body":"Kullanım izniyle birlikte modelin birim ve revizyon bilgisini inceleyin. Gerekli değişikliklerin geometriye etkisi görülmeden dosyanın yalnızca benzer görünmesine dayanarak üretime geçilmez."},{"title":"İşlevli ve yardımcı parçaları ayırın","body":"Kablo klipsi ile pervane, hareketli kol veya enerji taşıyan bağlantı farklı gereksinimler taşır. Çalışma yükü, sıcaklık ve hareketli parçaya yakınlık açıklanmalıdır. Basılmış bir numunenin takılması, çalışan sistemde güvenli kullanılacağı anlamına gelmez; proje ekibinin değerlendirmesi gerekir."}]'::jsonb,faq='[{"q":"Kırık drone gövdesinin tamamı yenilenebilir mi?","a":"Geometri oluşturulabilir olsa da uçuş yükleri ve güvenlik uygunluğu ayrıca ele alınmalıdır. Bu sayfa genel yardımcı plastik parçalar için başlangıç bilgisidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"İnternetten bulunan dosyanın vida aralığı, kart ölçüsü veya konektör açıklığı sizin ekipmanınızla farklı olabilir.","takeaways":["Bileşen modeli ve gerçek bağlantı ölçüleri","Hazır dosyanın izin ve revizyonu","Parçanın hareket ve enerjiyle ilişkisi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/sektorler/drone-hobi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Drone, robotik ve hobi","summary":"Elektronik yerleşimi, kablo yönetimi ve montaj yardımcıları için modelleme ve prototip planınızı oluşturun. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Bileşen yerleşimi","body":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"title":"Deneme koşulları","body":"Titreşim, dış ortam ve hareketli mekanizma ilişkisini belirtin. Uçuş veya yüksek hız gerektiren kullanımda parça doğrulaması ayrıca ele alınmalıdır. Tasarım numunesini doğrudan güvenlik açısından kritik kullanıma uygun kabul etmeyin."},{"title":"Onarım ve değiştirme","body":"Sık sökülecek kapakları, tüketilecek parçaları ve farklı sürümlerde değişecek bağlantıları işaretleyin. Tasarımın servis kolaylığı prototip üzerinden kontrol edilebilir. Sonraki sipariş için onaylanan dosyayı ve bağlantı ölçülerini saklayın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Kart, sensör, bağlantı ve kablo ölçülerini aynı referans sisteminde paylaşın. Montaj sırasında alet erişimi ve kablo bükülme alanını da düşünün. Sadece dış ölçüleri vermek, parçanın sorunsuz monte edileceğini göstermez."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='İlk prototip talebine hangi dosyalar eklenmeli?',summary='Fikir aşamasındaki bir ürünü teklif değerlendirmesine hazırlarken tasarım amacını, eldeki veriyi ve eksik kararları aynı pakette toplayın.',sections='[{"title":"Elinizdeki verinin seviyesini belirtin","body":"Dosyayı yalnızca uzantısıyla tarif etmeyin; hangi programdan çıktığını ve hangi ölçülerin güvenilir olduğunu yazın. Henüz çözülmemiş bağlantıları işaretlemek, bu alanların yanlışlıkla tamamlanmış tasarım kabul edilmesini önler."},{"title":"Talebi numunenin amacına bağlayın","body":"İlk örnek müşteri sunumuna mı gidecek, elde tutuşu mu gösterecek, yoksa bileşen montajı mı denenecek? Bu bilgi ayrıntı ve yüzey kapsamını etkiler. Bir dosya listesi içinde güncel sürümü, referans görselleri ve yalnızca fikir vermek için eklenen eski çizimleri ayırın."}]'::jsonb,faq='[{"q":"Hiç 3D modelim yoksa ne paylaşmalıyım?","a":"Ölçülü eskiz, benzer işlevi anlatan referans ve ürünün nasıl kullanılacağına ilişkin kısa açıklama modelleme değerlendirmesini başlatabilir. Referansın doğrudan kopyalanmasını değil hangi özelliğinin önemli olduğunu belirtin."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir eskiz, görsel tasarım dosyası ve üretilebilir katı model farklı hazırlık işleri gerektirir.","takeaways":["Güncel ve eski dosyaların ayrımı","Modelde henüz kararlaştırılmamış bölgeler","Numunenin kullanılacağı ilk görüşme veya test"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/teklif-icin-dosya-hazirlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Teklif için dosyanızı nasıl hazırlarsınız?","summary":"Teklif talebinde model kadar kullanım bilgisi de önemlidir. 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim projelerinde","body":"Tasarımınızı fiziksel olarak değerlendirin. Model revizyonu, montaj kontrolü ve sonraki iterasyon için proje kapsamını birlikte belirleyelim."},{"title":"Dosyanın birimini belirtin","body":"STL dosyası birim bilgisi taşımaz. Modelinizi milimetre olarak dışa aktarın ve Studio’da görünen boyutları kontrol edin. STEP dosyanız varsa montaj ilişkilerini değerlendirmek için ayrıca paylaşabilirsiniz."},{"title":"Teknik ihtiyacı tarif edin","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Sürümü takip edin","body":"Dosya adına parça kodu ve revizyon ekleyin. Birden fazla parçanın set halinde üretilmesini istiyorsanız her parça için adet belirtin."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Baskı teklifindeki hazırlık ve üretim bedeli nasıl okunur?',summary='Model düzeltme, makine süresi, destek temizliği ve yüzey işi kalemlerini aynı kapsamda karşılaştırarak teklifleri anlamlandırın.',sections='[{"title":"Tek seferlik işleri tekrar işlerden ayırın","body":"Teklifte hazırlık kapsamının ne olduğu ve hangi dosya sürümünü kapsadığı görülmelidir. Model değiştiğinde yeni hazırlık ihtiyacı doğabileceği ayrıca konuşulur."},{"title":"Ucuz bir kalemi eksik kapsamla karıştırmayın","body":"Baskı parçası destekleriyle mi teslim edilecek, görünür yüzeyi işlenecek mi, eşleşen bileşenle kontrol yapılacak mı? Aynı adet için fiyat karşılaştırırken bu soruların yanıtları eşleşmelidir. Teslimat ve paketleme kapsamını da parça bedelinden bağımsız gözden geçirmek, toplam ihtiyacı doğru okumayı sağlar."}]'::jsonb,faq='[{"q":"Gram fiyatı teklifleri kıyaslamak için yeterli mi?","a":"Malzeme miktarı işin yalnızca bir bölümüdür. İnce geometri, hazırlık, baskı süresi ve son işlem farklı olduğunda aynı ağırlıktaki iki parçanın toplam kapsamı değişebilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Dosyanın düzeltilmesi veya yeni bir kapağın modellenmesi ilk siparişte yer alabilir; sonraki üretimde aynı işin tekrarlanması gerekmeyebilir.","takeaways":["İlk siparişe özgü hazırlık kalemleri","Destek temizliği ve yüzey beklentisi","Kapsama dâhil kontrol ve teslim işleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/3d-baski-fiyatlandirma' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D baskı fiyatı nasıl belirlenir?","summary":"Malzeme, üretim süresi ve teknik ihtiyaçlar birlikte değerlendirilir.","sections":[{"title":"Prototip & kurumsal üretim projelerinde","body":"Tasarımınızı fiziksel olarak değerlendirin. Model revizyonu, montaj kontrolü ve sonraki iterasyon için proje kapsamını birlikte belirleyelim."},{"title":"Hacim ve malzeme","body":"Aynı dış boyuttaki iki model farklı hacim ve duvar yapısına sahip olabilir. Malzeme tüketimi, destekler ve fire üretim hazırlığında değerlendirilir."},{"title":"Adet ve işlem süresi","body":"Tekrarlanan parçaların planlaması, kurulum ve son işlem toplam maliyeti etkiler. Büyük bir parçanın üretimi ile küçük parçaların toplu üretimi aynı değerlendirme değildir."},{"title":"Ön tahmin ve kesin teklif","body":"Studio hesabı bir bütçe göstergesidir. Dilimleme, üretilebilirlik, montaj gereksinimi ve teslimat kontrolü sonrası resmi teklif netleşir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün yenilemede tarama ile yeniden modelleme arasındaki fark',summary='Mevcut şekli kaydetmek ile düzenlenebilir bir tasarım kurmak farklı çıktılar üretir; ihtiyacınızı teslim edilecek dosyayla tarif edin.',sections='[{"title":"Ölçülen yüzey ile tasarım niyetini ayırın","body":"Aşınma, eğrilik veya üretim izi de bu verinin parçası olabilir. Yeni modelin mevcut yüzeyi izlemesi mi, simetrik veya nominal bir geometriye dönmesi mi beklendiği belirlenmelidir. Bu karar yalnızca dosya dönüştürme işlemi değildir."},{"title":"Teslim dosyasının kullanımını açıklayın","body":"Yeniden baskı için kapalı bir ağ model yeterli olabilirken sonraki tasarım değişiklikleri için farklı bir CAD yapısı gerekebilir. Montaj delikleri ve düz yüzeyler gibi işlevli bölgelerin hangi referansla kurulacağı konuşulur. Tarama, temizleme ve yeniden modelleme ayrı kapsam olarak tekliflenebilir."}]'::jsonb,faq='[{"q":"Tarama dosyası CAD dosyası mıdır?","a":"Tarayıcı çıktısı çoğu durumda ağ veya nokta verisidir. Düzenlenebilir tasarım modeli bekleniyorsa yüzey kurma ve modelleme işi ayrıca tanımlanmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Tarama verisi numunede görülen biçimi içerir.","takeaways":["Mevcut şeklin korunacak ve düzeltilecek yerleri","Dosyanın sonraki kullanım programı","İşlevli yüzeylerin referans ölçüleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/tarama-ve-tersine-muhendislik' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D tarama mı, tersine mühendislik mi?","summary":"Ölçülen yüzey ile yeniden tasarlanmış CAD modelinin farkı. 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim projelerinde","body":"Tasarımınızı fiziksel olarak değerlendirin. Model revizyonu, montaj kontrolü ve sonraki iterasyon için proje kapsamını birlikte belirleyelim."},{"title":"Yüzey verisi","body":"Tarama dış yüzeyin ölçümünü sağlar. Delikler, iç kanallar ve erişilemeyen alanlar için ek ölçüm gerekebilir."},{"title":"Düzenlenebilir model","body":"CAD modelleme, işlevi tanımlanan yüzeyler ve ölçüler üzerinden yeni bir dijital tasarım oluşturur. Geometriyi düzenlemek ve üretim için değiştirmek bu aşamada mümkündür."},{"title":"Doğru teslim tanımı","body":"Sadece görselleştirme, arşivleme veya yeniden üretim farklı çıktılar gerektirir. Hangi amaçla kullanılacağını teklif öncesinde belirtin."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Prototip revizyonunu gözlemden üretim kararına taşıma',summary='Bir denemede görülen sorunu tarif edilebilir model değişikliğine dönüştürün ve sonraki numunede aynı noktayı tekrar kontrol edin.',sections='[{"title":"Gözlemi yorumdan ayrı yazın","body":"Fotoğraftaki bir işaret ve ilgili ölçü, modellemeye somut girdi sağlar. Tasarım değişikliği önerisi bu gözlemle eşleştirilerek hangi sorunu çözmesinin beklendiği açık tutulur."},{"title":"Kapanan ve açık bulguları izleyin","body":"Her numune sürümünde bütün sorunlar kapanmayabilir. Kabul edilen bölgeler ile yeniden değerlendirilecek bölgeleri ayrı listeleyin. Bir parça yalnızca görünüş için onaylandıysa bu onayı montaj veya işlev onayı gibi genişletmeyin; sonraki siparişin kapsamı bu kayıt üzerinden kurulmalıdır."}]'::jsonb,faq='[{"q":"Kaç revizyon gerektiğini baştan bilir miyiz?","a":"Belirsizlik düzeyine ve değişen gereksinimlere bağlıdır. Teklifte dâhil edilen modelleme turu ve ek değişikliklerin nasıl ele alınacağı belirlenebilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"“Kapak kötü” demek yerine nerede açıldığını, hangi hareket sırasında sürttüğünü ve hangi bileşene değdiğini kaydedin.","takeaways":["Bulguyu gösteren fotoğraf ve ölçü","Değişiklik önerisinin hedefi","Bir sonraki numunede kapanacak maddeler"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/numune-ve-revizyon' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Numuneden tekrar siparişe","summary":"Parçayı onaylamak ve doğru revizyonla devam etmek. 3dyanımda ile prototip & kurumsal üretim için proje bazlı değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim projelerinde","body":"Tasarımınızı fiziksel olarak değerlendirin. Model revizyonu, montaj kontrolü ve sonraki iterasyon için proje kapsamını birlikte belirleyelim."},{"title":"İlk kontrol","body":"Numuneyi gerçek montaj ortamında değerlendirin. Uyum, erişim ve kullanım sırasında karşılaşılan noktaları fotoğraf ve ölçüyle kaydedin."},{"title":"Revizyon kararı","body":"Değişen ölçüleri açıkça belirtin. Tasarım güncellemelerinin eski dosyayla karışmaması için yeni bir revizyon adı kullanın."},{"title":"Tekrar üretim","body":"Onaylanan dosya, malzeme ve üretim ayarları tekrar talebin başlangıcıdır. Malzeme veya kullanım koşulu değiştiğinde yeniden değerlendirme gerekir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün prototipi için STL dışa aktarma kontrolü',summary='Baskıya gönderilecek ağ modelde birim, yüzey bütünlüğü ve çok parçalı montaj yapısını kontrol edin.',sections='[{"title":"Birim ve toplam boyutu karşılaştırın","body":"Dışa aktarılan modeli yeniden açıp bilinen bir uzunluğu kontrol edin. Çok küçük ya da çok büyük görünen bir modelin yalnızca ekrandaki zoom nedeniyle öyle göründüğünü varsaymayın; gerçek dış ölçüyü talep notunda yazın."},{"title":"Görsel düzgünlük ile ağ bütünlüğünü ayırın","body":"Ekranda düzgün görünen yüzeyde açık kenar, üst üste binmiş kabuk veya ters yüz bulunabilir. Ayrı üretilecek bileşenleri anlaşılır dosyalara ayırın ve montaj görseli ekleyin. Üçgen sayısını gereksiz büyütmek dosyayı ağırlaştırır; önemli eğrileri koruyan dışa aktarım ayarı kullanılmalıdır."}]'::jsonb,faq='[{"q":"Tek STL içinde birden fazla parça olabilir mi?","a":"Olabilir; ancak parçaların ayrı basılıp basılmayacağı ve aralarındaki ilişki belirtilmelidir. Parça adları ve adet listesi yanlış yorumlama ihtimalini azaltır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"STL dosyalarında ölçü birimi bilgisi her iş akışında korunmayabilir.","takeaways":["Modelin gerçek birimi ve dış ölçüsü","Açık kenar veya kabuk kontrolü","Ayrı üretilecek parçaların adedi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/stl-dosya-hazirlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"STL dosyası hazırlama kontrol listesi","summary":"Tekliften önce birim, dış ölçü, yüzey bütünlüğü ve revizyon bilgisini aynı kontrol listesiyle gözden geçirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Birim ve ölçek","body":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"title":"Yüzey ve ayrıntı","body":"Modelde açık yüzey, üst üste geometri veya istenmeyen iç parçalar olup olmadığını CAD yazılımınızda kontrol edin. Görüntüleyicide kesit almak iç ilişkileri anlamayı kolaylaştırır; ancak otomatik üretilebilirlik doğrulamasının yerini tutmaz."},{"title":"Dosya paketi","body":"Parça kodu ve revizyonu dosya adına ekleyin. Adet, kritik ölçü ve kullanım koşullarını ayrı not edin. Birden fazla dosyada aynı kodu farklı revizyonlarla karıştırmayın; onaylanmış sürümü açıkça işaretleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Tarama ağından revizyon yapılabilir ürün modeline',summary='Tarama verisindeki serbest yüzeyleri ve işlevli bağlantıları farklı modelleme kararları olarak değerlendirin.',sections='[{"title":"Nominal geometri gereken bölgeleri seçin","body":"Tüm ağın aynı yöntemle dönüştürülmesi yerine bu bölgeler ayrıştırılır. Hangi yüzeyin referans sayılacağı ve hangi kusurların düzeltilmesi istendiği açıklanmalıdır."},{"title":"Düzenleme beklentisini teslimata yazın","body":"Sonraki aşamada boy değiştirilecek, delik eklenecek veya montaj geliştirilecekse model yapısının bunu desteklemesi gerekir. Dosya formatı tek başına düzenleme kolaylığını garanti etmez. Kaynak ağ, kurulan yüzeyler ve nihai çıktı arasındaki ilişki teslim kapsamına göre belgelenebilir."}]'::jsonb,faq='[{"q":"Ağ dosyasını STEP kaydetmek yeterli mi?","a":"Uzantı değişikliği düzenlenebilir tasarım niyeti oluşturmaz. Hedef geometri ve sonraki kullanım görülerek dönüştürme veya yeniden modelleme yöntemi seçilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir cihazın elde kavranan yüzeyi taranmış biçimi izleyebilir; vida ekseni veya kapak yatağı ise ölçülü geometri gerektirebilir.","takeaways":["Serbest biçimli ve ölçülü yüzeylerin ayrımı","Düzenlenecek parametre veya bölgeler","Kaynak ağın eksik alanları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/tarama-verisinden-cad' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Tarama verisinden CAD modeline","summary":"Nokta bulutu, yüzey ağı ve düzenlenebilir CAD çıktısını ayırarak tersine mühendislik talebinizi doğru kapsamlandırın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hangi veri elinizde?","body":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"title":"Fonksiyonel yüzeyler","body":"Delik, mil yatağı, oturma yüzeyi ve bağlantı eksenlerini işaretleyin. Aşınmış veya kırılmış bölgeyi olduğu gibi kopyalamak yerine korunması gereken tasarım ilişkisini açıklayın. Gerekirse sağlam karşı parça da değerlendirmeye eklenir."},{"title":"Teslim ve kontrol","body":"İstenen formatı, revizyon kapsamını ve kontrol edilecek ölçüleri baştan belirleyin. Tarama ile CAD arasındaki farkların nasıl değerlendirileceğini kararlaştırın. Sadece görsel benzerlik, ölçüsel kabulün yerine geçmez."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün gövdesi kesitinde duvar ve montaj boşluğu okuma',summary='Dış yüzeyin sakladığı iç hacmi kesitlerle inceleyerek kart, vida ve kapak ilişkilerini görünür kılın.',sections='[{"title":"Kesiti bağlantı ekseninden geçirin","body":"Vida yatağı çevresindeki duvar, kapağın bindirmesi ve kart altındaki boşluk aynı görünümde değerlendirilebilir. Kritik ölçüler ayrı notlanır; ekrandaki çizgi kalınlığı gerçek duvar kalınlığı olarak yorumlanmaz."},{"title":"Hareket için gereken boşluğu kontrol edin","body":"Bir düğme veya tırnak yalnızca başlangıç konumunda değil hareket ederken de yer ister. Kesitleri farklı konumlarda karşılaştırın. Görünen bir boşluğun üretim toleransı ve montaj payıyla yeterli olup olmadığı numune üzerinde değerlendirilmelidir; görüntüleyici tek başına uygunluk sertifikası değildir."}]'::jsonb,faq='[{"q":"Kesit görünümü dosyayı değiştirir mi?","a":"Görüntüleme kesiti çoğunlukla inceleme içindir. Fiziksel parçayı kesmek veya ikiye bölerek üretmek ayrı bir model düzenlemesi gerektirir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Rastgele bir düzlem yerine sorun yaşanabilecek bağlantının ortasından geçen kesit seçin.","takeaways":["İncelenecek bağlantı ekseni","En dar iç boşluklar","Hareketli elemanın iki uç konumu"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/kesit-nasil-incelenir' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D modelde kesit nasıl incelenir?","summary":"Kesit düzlemini kullanarak iç boşlukları, montaj ilişkilerini ve beklenmeyen yüzeyleri görünür hale getirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Düzlem yönünü seçin","body":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"title":"Görsel kesitin sınırları","body":"Tarayıcıdaki araç yüzeyleri düzleme göre gizler. Açılan kesiti kapatmaz, takım yolu veya baskı katmanı üretmez. Duvar kalınlığı ya da tolerans raporu gerekiyorsa ölçüm ve üretim yazılımlarındaki uygun araçlarla doğrulama yapın."},{"title":"Bulgunuzu tarif edin","body":"İncelediğiniz ekseni, düzlem konumunu ve sorunlu bölgeyi not edin. Talebe dosyanın aynı revizyonunu ekleyin. Bir ekran görüntüsünde görünen boşluğun tasarım amacı mı, dosya hatası mı olduğunu açıklamadan üretim kararı vermeyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Kurumsal prototip talebi için teknik kapsam dosyası',summary='Satın alma, tasarım ve üretim değerlendirmesinin aynı numune amacını ve teslim kapsamını okuyabileceği bir kayıt hazırlayın.',sections='[{"title":"Karar tablosunu dosyaya ekleyin","body":"Görünür yüz, kritik ölçü ve varsa eşleşen bileşen açıkça belirtilsin. Henüz kararlaştırılmamış malzeme veya renk için tahmini seçim yazmak yerine kararın açık olduğunu göstermek daha sağlıklıdır."},{"title":"Teslim edilecekleri ayrı satırlara ayırın","body":"Fiziksel parça, düzenlenebilir model, kontrol raporu ve montaj desteği farklı teslimatlardır. İstenen dosya formatı ve veri sorumlusu belirtilmelidir. Ticari teklif üzerinde kapsam dışı kalan bir iş, teknik dosyada istenmiş olsa bile otomatik dâhil sayılmaz; iki belge arasındaki farklar sipariş öncesinde kapatılır."}]'::jsonb,faq='[{"q":"Teklif dosyasında hedef tarihi yazmalı mıyım?","a":"Evet; bunun sunum, numune kontrolü veya son teslim için mi olduğu belirtilmelidir. Üretim ve taşıma planı değerlendirilerek tarih ayrıca teyit edilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Her parça için kod, revizyon, adet ve numune amacı yer alsın.","takeaways":["Kod, revizyon ve adet tablosu","Fiziksel ve dijital teslimatlar","Açık kararlar ve tarih türü"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/teknik-teklif-dosyasi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Teknik teklif dosyası nasıl hazırlanır?","summary":"Satın alma ve teknik ekiplerin aynı dosya üzerinden ilerlemesi için parça, adet, revizyon ve kabul bilgilerini düzenleyin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Tek bir parça tablosu","body":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"title":"Kabul beklentisi","body":"Kritik ölçüler, görünür yüzeyler, işlevsel kontroller ve numune onayını kimin vereceği talepte yer alsın. Belgelenmeyen bir beklentinin teklif kapsamına otomatik girdiğini varsaymayın. Teslim dosyası ve fiziksel ürün kapsamını ayrı yazın."},{"title":"Takvim ve değişiklik","body":"Hedef tarihi, ara onay adımlarını ve revizyon için ayrılan süreyi belirtin. Talep sonrası geometri veya adet değişirse teklif yeniden değerlendirilebilir. Onaylanan sürümü teknik ekip ve satın alma arasında ortak referans yapın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün prototipinde malzeme seçmeden önce beş kullanım sorusu',summary='Malzeme adından önce temas, sıcaklık, yük, görünüş ve numune amacını açıklayın.',sections='[{"title":"Başarıyı nasıl anlayacağınızı tarif edin","body":"Başarı ölçütü değiştiğinde malzeme ve geometri de değişebilir. Bir özelliği iyileştirmenin başka bir özelliği etkileyebileceği kabul edilerek öncelik sırası oluşturulur."},{"title":"Bilinen koşullarla varsayımları ayırın","body":"Gerçek ortam sıcaklığı ölçülmediyse kesin bir değer yazmak yerine hangi kaynağa yakın olduğunu açıklayın. Kimyasal temas varsa ürünün adını paylaşın. Renk ve yüzey için referans görsel, mekanik davranış için kullanım tarifi ekleyin; bunlar aynı tür veri değildir."}]'::jsonb,faq='[{"q":"En pahalı filament en iyi seçenek midir?","a":"Fiyat bir uygunluk ölçütü değildir. Belirlenen görevi karşılayan, üretilebilir ve gerekli doğrulaması yapılabilen seçenek değerlendirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Prototip elden düşmeye dayanmalı mı, yalnızca toplantıda gösterilecek mi, yoksa bir kapağın tekrar açılması mı denenecek?","takeaways":["Numunede başarı sayılacak davranış","Bilinen koşullar ve belirsizlikler","Görünüş ile mekanik öncelik sırası"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/malzeme-secim-sorulari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Malzeme seçmeden önce sorulacak sorular","summary":"Malzeme kararını yalnızca isim veya renge göre değil, parçanın işlevi ve çalışma koşullarına göre hazırlayın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ortamı tanımlayın","body":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"title":"Geometriyi birlikte düşünün","body":"İnce bağlantılar, esneyen tırnaklar ve büyük düz yüzeyler farklı tasarım değerlendirmeleri gerektirir. Malzeme, yönlendirme ve üretim yöntemi birlikte ele alınmalıdır. Sadece doluluk oranını artırmak her işlevsel problemi çözmez."},{"title":"Numuneyle karar verin","body":"Kritik kullanımlarda numuneyi hedef ortama uygun bir kontrol planıyla değerlendirin. Malzeme veri sayfasını, üretim ayarlarını ve test koşullarını birbirine karıştırmayın. Nihai kabul ölçütünü üretimden önce belirleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün sunum modelinde ölçek ve parçalama planı',summary='Büyük bir ürün fikrini küçültülmüş sunum modeline çevirirken görülecek ayrıntıları ve taşınabilirliği birlikte belirleyin.',sections='[{"title":"Küçültmenin hangi bilgiyi kaybettirdiğini görün","body":"Modelin gerçekçi görünmesiyle mekanizmayı anlatması farklı hedeflerdir. Özellikle gösterilmek istenen detaylar ayrı büyütülmüş parça veya kesit olarak sunulabilir."},{"title":"Birleşimleri sunumun parçası yapın","body":"Çıkarılabilir kapak veya patlatılmış yerleşim, iç bileşenleri anlatmayı kolaylaştırabilir. Bağlantı yerleri ve tutma yüzleri tasarımda gösterilir. Modelin kutuya nasıl gireceği, masada nasıl duracağı ve hangi sırayla kurulacağı toplam teslim kapsamına eklenmelidir."}]'::jsonb,faq='[{"q":"Ölçekli modelle gerçek montaj doğrulanır mı?","a":"Tam boyutlu montaj boşlukları ve kuvvetler ölçekli modelde aynı anlamı taşımaz. Ölçekli sunum ile gerçek boyutlu uyum numunesi farklı amaçlarla hazırlanır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir ürünün bütün ölçülerini aynı oranda küçültmek bağlantı ve düğme gibi ayrıntıları okunmaz hâle getirebilir.","takeaways":["Gösterilecek ana ürün özelliği","Toplam sunum ve taşıma boyutu","Ayrı gösterilecek iç bileşenler"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/maket-olcek-planlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Maket ölçeği ve parçalara ayırma","summary":"Mimari modelin fiziksel ölçüsünü, okunabilir detayını ve taşıma ihtiyacını tek üretim planında birleştirin. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçeği hesaplayın","body":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"title":"Detay seviyesini seçin","body":"Pencere, korkuluk ve peyzaj gibi öğeleri her ölçekte aynı biçimde üretmek uygun olmayabilir. Anlatım açısından gerekli ayrıntıları listeleyin. Fiziksel sınırlar nedeniyle sadeleştirilecek bölgeler için dijital onay alın."},{"title":"Taşıma ve montaj","body":"Taban ölçüsü, birleşim yerleri ve sökülebilir parçaları kutulama planıyla birlikte değerlendirin. Parçaları kodlayın ve yerleşim şemasını saklayın. Sergileme sırasında sık taşınacak bir maket için servis erişimini de planlayın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Ürün prototipini kabul ederken hangi kararlar kaydedilir?',summary='Form, montaj ve görünüş denemelerinin sonucunu aynı prototip sürümüne bağlayan pratik kabul düzeni.',sections='[{"title":"Kontrol maddesini gözlenebilir yazın","body":"Kullanılacak karşı parça ve kontrol yöntemi belli olmalıdır. Ölçülecek değer varsa referans çizim ve kabul sınırı yetkili tasarım sorumlusunca belirtilir."},{"title":"Kısmi onayın kapsamını koruyun","body":"Bir numunenin ergonomisi onaylanıp yüzeyi reddedilebilir. Her başlığın durumunu ayrı kaydetmek, sonraki revizyonun nerede çalışacağını gösterir. Koşullu kabul varsa hangi eksiklerin tamamlanacağı ve tekrar üretime izin verilip verilmediği yazılmalıdır."}]'::jsonb,faq='[{"q":"Fotoğraflı onay yeterli olur mu?","a":"Görsel kararlar için yardımcıdır; montaj veya işlev kontrolünün yerine her durumda geçmez. Kabul kanıtı, kararın türüne uygun seçilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"“Kaliteli olsun” yerine kapağın kapanması, düğmenin erişilmesi veya parçanın belirtilen yuvaya oturması gibi somut maddeler seçin.","takeaways":["Her madde için kontrol yöntemi","Kullanılan karşı parça ve revizyon","Kabul, red ve açık bulgu ayrımı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/rehber/numune-kabul-plani' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Numune kabul planı","summary":"Bir prototipin hangi koşullarda onaylanacağını üretimden önce tanımlayarak revizyon görüşmelerini somutlaştırın. 3dyanımda: prototip & kurumsal üretim odağında değerlendirme.","sections":[{"title":"Prototip & kurumsal üretim","body":"3dyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Prototip & kurumsal üretim için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kontrol maddeleri","body":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"title":"Kayıt düzeni","body":"Numunenin dosya revizyonu, malzemesi, adedi ve test tarihi bir arada tutulmalıdır. Test sırasında yapılan elle düzeltmeler varsa bunları da kaydedin. Yeni baskıda aynı düzeltmenin yeniden gerekmemesi için dijital modele geri işleyin."},{"title":"Onaydan tekrar siparişe","body":"Hangi maddelerin geçtiğini ve hangilerinin açık kaldığını listeleyin. Koşullu onayı nihai onaydan ayırın. Tekrar sipariş verirken aynı revizyonu, değişen adetleri ve yeni kullanım koşullarını belirtin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Aparat talebi için saha dosyası nasıl hazırlanır?',summary='Fikstürün görevini iş istasyonu, iş parçası ve operatör hareketiyle birlikte tarif eden bir başlangıç paketi oluşturun.',sections='[{"title":"Geniş görüntü ile yakın ölçüyü birleştirin","body":"İkisi aynı işe aittir. İş parçasının yüklenme yönünü ve işlem sırasında hareket eden takımı işaretleyin; hangi yüzeylerin dayama olarak kullanılabileceğini teknik ekip belirlesin."},{"title":"Gerçek sorunu ayrı bir notta açıklayın","body":"Mevcut işlemde kayma, yanlış yerleştirme, uzun kurulum veya yüzey izi gibi hangi sorun yaşanıyor? Sorunun gözlendiği adımı yazmak, aparatın hangi davranışı değiştireceğini gösterir. Numune denemesinin nerede ve kim tarafından yapılacağı talebe eklenebilir."}]'::jsonb,faq='[{"q":"CAD dosyası olmadan istasyon aparatı konuşulabilir mi?","a":"Ölçülü fotoğraf ve örnek parçayla kapsam değerlendirilebilir. Modelleme için eksik ölçüler belirlendiğinde ilave saha verisi veya numune ihtiyacı ayrıca planlanır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Yakın parça fotoğrafı bağlantıyı gösterirken geniş istasyon görüntüsü erişim kısıtlarını ortaya çıkarır.","takeaways":["Geniş istasyon ve yakın temas fotoğrafları","İş parçasının yükleme yönü","Çözülmesi beklenen işlem sorunu"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/teklif-icin-dosya-hazirlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Teklif için dosyanızı nasıl hazırlarsınız?","summary":"Teklif talebinde model kadar kullanım bilgisi de önemlidir. 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür projelerinde","body":"Montaj bağlantıları, kablo yönlendirmeleri ve özel aparat ihtiyaçlarını sistem geometrisiyle birlikte ele alıyoruz."},{"title":"Dosyanın birimini belirtin","body":"STL dosyası birim bilgisi taşımaz. Modelinizi milimetre olarak dışa aktarın ve Studio’da görünen boyutları kontrol edin. STEP dosyanız varsa montaj ilişkilerini değerlendirmek için ayrıca paylaşabilirsiniz."},{"title":"Teknik ihtiyacı tarif edin","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Sürümü takip edin","body":"Dosya adına parça kodu ve revizyon ekleyin. Birden fazla parçanın set halinde üretilmesini istiyorsanız her parça için adet belirtin."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Fikstür teklifinde toplam iş kapsamını karşılaştırma',summary='Tasarım, baskı, montaj donanımı ve kontrol işlerinin teklif bedeline nasıl yansıdığını aynı teknik kapsamla okuyun.',sections='[{"title":"Baskı gövdesi ile bitmiş aparatı ayırın","body":"Montajı kimin yapacağı ve mevcut ekipmandan hangi parçaların kullanılacağı yazılmalıdır. Satırların aynı isimde olması aynı teslim kapsamını ifade etmeyebilir."},{"title":"Kontrol ve revizyon işini görünür tutun","body":"İlk numune sonrasında referans yüzünün değişmesi veya ek ölçüm istenmesi yeni iş doğurabilir. Teklifte hangi kontrolün, kaç modelleme turunun ve hangi teslimatın yer aldığı incelenir. Toplam maliyet değerlendirmesi, üretim ekibinin kendi kurulum ve kabul yükünü de görmesini gerektirir."}]'::jsonb,faq='[{"q":"Baskı ağırlığını azaltmak aparatı her zaman ucuzlatır mı?","a":"Geometri karmaşıklığı, üretim süresi ve işlev gereksinimleri de etkilidir. Ağırlık azaltmanın aparatın görevini ve kontrol kapsamını bozup bozmadığı değerlendirilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir teklif yalnızca plastik gövdeyi içerebilir; metal burç, vida, ped veya diğer donanım ayrı olabilir.","takeaways":["Gövde ve satın alınacak donanım ayrımı","Montaj ve kontrol sorumluluğu","Numune sonrası revizyon kapsamı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/3d-baski-fiyatlandirma' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D baskı fiyatı nasıl belirlenir?","summary":"Malzeme, üretim süresi ve teknik ihtiyaçlar birlikte değerlendirilir.","sections":[{"title":"Endüstriyel parça & fikstür projelerinde","body":"Montaj bağlantıları, kablo yönlendirmeleri ve özel aparat ihtiyaçlarını sistem geometrisiyle birlikte ele alıyoruz."},{"title":"Hacim ve malzeme","body":"Aynı dış boyuttaki iki model farklı hacim ve duvar yapısına sahip olabilir. Malzeme tüketimi, destekler ve fire üretim hazırlığında değerlendirilir."},{"title":"Adet ve işlem süresi","body":"Tekrarlanan parçaların planlaması, kurulum ve son işlem toplam maliyeti etkiler. Büyük bir parçanın üretimi ile küçük parçaların toplu üretimi aynı değerlendirme değildir."},{"title":"Ön tahmin ve kesin teklif","body":"Studio hesabı bir bütçe göstergesidir. Dilimleme, üretilebilirlik, montaj gereksinimi ve teslimat kontrolü sonrası resmi teklif netleşir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Eski fikstürü taramak mı yeniden tasarlamak mı?',summary='Mevcut aparatın aşınmış yüzeylerini, korunacak referanslarını ve değiştirilmek istenen işlevini ayrı değerlendirin.',sections='[{"title":"Aşınmayı yeni tasarıma taşımayın","body":"Taranan şekli doğrudan kopyalamak bu sorunu yeni parçaya aktarabilir. Sağlam referanslar, teknik resim ve iş parçasının güncel ölçüleri birlikte incelenerek hangi alanların nominal geometriyle kurulacağı belirlenir."},{"title":"İş istasyonundaki değişikliği hesaba katın","body":"Makineye sonradan sensör veya yeni bir takım eklenmişse eski aparatın geometrisi artık uygun olmayabilir. Tarama yalnızca mevcut biçimi belgeler; yeni hareket ve erişim ihtiyacını çözmek modelleme görevidir. Teslim edilecek dosya ve kontrol yöntemi bu iki işi ayırmalıdır."}]'::jsonb,faq='[{"q":"Eski aparatı gönderdiğimde birebir kopya yeterli olur mu?","a":"Önce eski parçanın işlevini koruyup korumadığı ve hasarları değerlendirilir. Kopyalama hedefi ile iyileştirme hedefi aynı kapsam değildir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Eski dayama yüzeyi veya yuva zamanla biçim değiştirmiş olabilir.","takeaways":["Aşınmış ve korunacak yüzeyler","İstasyonun değişen ekipmanları","İş parçasının güncel referansı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/tarama-ve-tersine-muhendislik' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D tarama mı, tersine mühendislik mi?","summary":"Ölçülen yüzey ile yeniden tasarlanmış CAD modelinin farkı. 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür projelerinde","body":"Montaj bağlantıları, kablo yönlendirmeleri ve özel aparat ihtiyaçlarını sistem geometrisiyle birlikte ele alıyoruz."},{"title":"Yüzey verisi","body":"Tarama dış yüzeyin ölçümünü sağlar. Delikler, iç kanallar ve erişilemeyen alanlar için ek ölçüm gerekebilir."},{"title":"Düzenlenebilir model","body":"CAD modelleme, işlevi tanımlanan yüzeyler ve ölçüler üzerinden yeni bir dijital tasarım oluşturur. Geometriyi düzenlemek ve üretim için değiştirmek bu aşamada mümkündür."},{"title":"Doğru teslim tanımı","body":"Sadece görselleştirme, arşivleme veya yeniden üretim farklı çıktılar gerektirir. Hangi amaçla kullanılacağını teklif öncesinde belirtin."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Fikstür revizyonlarını istasyon kabulüne bağlama',summary='Operatör, kalite ve bakım geri bildirimlerini tek aparat sürümünde toplayarak deneme sonucunu izlenebilir tutun.',sections='[{"title":"Bulguyu istasyondaki adıma bağlayın","body":"Her gözlemin hangi adımda oluştuğunu kaydedin. Varsa ölçü, fotoğraf ve kullanılan iş parçası kodu bulguya eklenir; böylece revizyonun hedefi netleşir."},{"title":"Onaydan sonra değişen şartı tanıyın","body":"Ürün varyantı, temas elemanı veya malzeme değişirse önceki kabulün geçerliliği değerlendirilmelidir. Aynı aparat kodunu taşımak bütün değişiklikleri kapsayan bir onay değildir. Tekrar üretimde referans alınacak sürüm, kapatılmış bulgular ve açık şartlar birlikte belirtilir."}]'::jsonb,faq='[{"q":"Operatörün uygun bulması tek başına yeterli mi?","a":"Operatör erişimi önemli bir girdidir; ölçüm, kalite ve iş güvenliği gereksinimleri varsa ilgili sorumluların değerlendirmeleri de gerekir. Kabul kapsamı işe göre tanımlanır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Yükleme sırasında takılan parça, işlemde kayan yüzey ve boşaltırken zorlanan operatör farklı bulgulardır.","takeaways":["Bulgunun oluştuğu çevrim adımı","Denemede kullanılan ürün varyantı","Onaylanan aparat sürümü"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/numune-ve-revizyon' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Numuneden tekrar siparişe","summary":"Parçayı onaylamak ve doğru revizyonla devam etmek. 3dsanayi ile endüstriyel parça & fikstür için proje bazlı değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür projelerinde","body":"Montaj bağlantıları, kablo yönlendirmeleri ve özel aparat ihtiyaçlarını sistem geometrisiyle birlikte ele alıyoruz."},{"title":"İlk kontrol","body":"Numuneyi gerçek montaj ortamında değerlendirin. Uyum, erişim ve kullanım sırasında karşılaşılan noktaları fotoğraf ve ölçüyle kaydedin."},{"title":"Revizyon kararı","body":"Değişen ölçüleri açıkça belirtin. Tasarım güncellemelerinin eski dosyayla karışmaması için yeni bir revizyon adı kullanın."},{"title":"Tekrar üretim","body":"Onaylanan dosya, malzeme ve üretim ayarları tekrar talebin başlangıcıdır. Malzeme veya kullanım koşulu değiştiğinde yeniden değerlendirme gerekir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Aparat STL dosyasında kritik arayüz kontrolü',summary='Baskı dosyasını dayama yüzeyi, burç yatağı ve montaj deliklerinin gerçek boyutlarıyla birlikte kontrol edin.',sections='[{"title":"Üçgenleme kritik daireleri etkileyebilir","body":"Dışa aktarılan modeli yeniden açarak işlevli yüzeyleri inceleyin. Dosya boyutunu yalnızca küçültmek için seçilen ayarların kritik arayüzlere etkisi görülmelidir."},{"title":"Baskı ile ek işlemi ayırın","body":"Bazı delik veya yüzeyler baskı sonrası işlenecekse bu durum notlanmalıdır. Modelde gösterilen ölçünün bitmiş ölçü mü yoksa işleme payı mı olduğu açık olmalıdır. Donanım listesi ve teknik resim, yalnızca STL içinde görünmeyen montaj gereksinimlerini tamamlar."}]'::jsonb,faq='[{"q":"STL yerine STEP göndermek daha mı iyi?","a":"Düzenleme ve ölçülü geometri değerlendirmesi gerekiyorsa CAD verisi yararlı olabilir. Üretime hangi formatın esas alınacağı ve ağ hazırlığını kimin yapacağı talep kapsamına göre seçilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Dairesel yüzey veya eğri bir yuva ağ dosyasında çok kaba temsil edilmişse geometrik ayrıntı kaybolabilir.","takeaways":["Kritik eğri ve delik yüzeyleri","Baskı sonrası işlenecek bölgeler","Donanım ve teknik resim ekleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/stl-dosya-hazirlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"STL dosyası hazırlama kontrol listesi","summary":"Tekliften önce birim, dış ölçü, yüzey bütünlüğü ve revizyon bilgisini aynı kontrol listesiyle gözden geçirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Birim ve ölçek","body":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"title":"Yüzey ve ayrıntı","body":"Modelde açık yüzey, üst üste geometri veya istenmeyen iç parçalar olup olmadığını CAD yazılımınızda kontrol edin. Görüntüleyicide kesit almak iç ilişkileri anlamayı kolaylaştırır; ancak otomatik üretilebilirlik doğrulamasının yerini tutmaz."},{"title":"Dosya paketi","body":"Parça kodu ve revizyonu dosya adına ekleyin. Adet, kritik ölçü ve kullanım koşullarını ayrı not edin. Birden fazla dosyada aynı kodu farklı revizyonlarla karıştırmayın; onaylanmış sürümü açıkça işaretleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Aparat referanslarını tarama verisinden kurma',summary='Taranmış iş parçasına uygun bir fikstür geliştirmek için yüzey verisini dayama ve eksen kararlarıyla birleştirin.',sections='[{"title":"Parçanın nereden oturacağını belirleyin","body":"İşlevli referansların seçimi üretim yöntemiyle birlikte değerlendirilir. Tarama ağındaki gürültünün dayama geometrisine aktarılmaması için yüzeylerin nasıl sadeleştirileceği açıklanmalıdır."},{"title":"Nominal ve gerçek örneği karşılaştırın","body":"Tek bir iş parçası üretim dağılımını temsil etmeyebilir. Uygunsa teknik resim ve farklı örnekler üzerinden varyasyon değerlendirilir. Kurulan CAD yüzeyi ile kaynak veri arasındaki sapmanın nerede önemli olduğu kalite ekibinin kabul gereksiniminden gelmelidir."}]'::jsonb,faq='[{"q":"Tek taranmış numune bütün seri için yeterli mi?","a":"Ürün varyasyonu bilinmeden bu sonuç çıkarılmaz. Referans çizim, örnek seçimi ve gerekli karşılaştırma kapsamı birlikte belirlenmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"İş parçasının bütün yüzeyini saracak bir yuva, istenmeyen sıkışma veya kir birikimi yaratabilir.","takeaways":["Dayama olarak seçilen yüzeyler","Teknik resim ve örnek farklılıkları","Sapmanın değerlendirileceği bölgeler"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/tarama-verisinden-cad' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Tarama verisinden CAD modeline","summary":"Nokta bulutu, yüzey ağı ve düzenlenebilir CAD çıktısını ayırarak tersine mühendislik talebinizi doğru kapsamlandırın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hangi veri elinizde?","body":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"title":"Fonksiyonel yüzeyler","body":"Delik, mil yatağı, oturma yüzeyi ve bağlantı eksenlerini işaretleyin. Aşınmış veya kırılmış bölgeyi olduğu gibi kopyalamak yerine korunması gereken tasarım ilişkisini açıklayın. Gerekirse sağlam karşı parça da değerlendirmeye eklenir."},{"title":"Teslim ve kontrol","body":"İstenen formatı, revizyon kapsamını ve kontrol edilecek ölçüleri baştan belirleyin. Tarama ile CAD arasındaki farkların nasıl değerlendirileceğini kararlaştırın. Sadece görsel benzerlik, ölçüsel kabulün yerine geçmez."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Fikstür kesitinde gövde, burç ve takım erişimi inceleme',summary='Aparatın iç yapısını kritik kuvvet ve bağlantı bölgelerinden geçen kesitlerle değerlendirin.',sections='[{"title":"Bağlantının çevresindeki gövdeyi görün","body":"Kesit düzlemini bağlantı ekseninden geçirip komşu boşlukları inceleyin. Kuvvetin hangi yönde aktarılacağı da değerlendirmeye dâhil edilir; sadece kalın görünen bir kesitten taşıma kapasitesi sonucu çıkarılmaz."},{"title":"Takımın yaklaşma hacmini kontrol edin","body":"Tornavida, prob veya başka bir takım parçaya ulaşırken gövdeye çarpabilir. Kesitte görülen açıklıkla birlikte üç boyutlu hareket hacmi de incelenmelidir. Baskı sonrası donanım montajı yapılacaksa parçanın hangi sırayla birleşeceği ayrı olarak denenir."}]'::jsonb,faq='[{"q":"Kesit analizi mekanik hesap yerine geçer mi?","a":"Hayır; kesit görünümü geometriyi inceleme aracıdır. Gerekli yük, rijitlik veya emniyet hesabı kendi mühendislik yöntemiyle yapılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bir vida veya burcun çevresinde kalan malzeme, dış görünümde anlaşılmayabilir.","takeaways":["Kuvvet ve bağlantı eksenleri","Burç ve vida çevresindeki boşluklar","Takım yaklaşma ve montaj sırası"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/kesit-nasil-incelenir' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D modelde kesit nasıl incelenir?","summary":"Kesit düzlemini kullanarak iç boşlukları, montaj ilişkilerini ve beklenmeyen yüzeyleri görünür hale getirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Düzlem yönünü seçin","body":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"title":"Görsel kesitin sınırları","body":"Tarayıcıdaki araç yüzeyleri düzleme göre gizler. Açılan kesiti kapatmaz, takım yolu veya baskı katmanı üretmez. Duvar kalınlığı ya da tolerans raporu gerekiyorsa ölçüm ve üretim yazılımlarındaki uygun araçlarla doğrulama yapın."},{"title":"Bulgunuzu tarif edin","body":"İncelediğiniz ekseni, düzlem konumunu ve sorunlu bölgeyi not edin. Talebe dosyanın aynı revizyonunu ekleyin. Bir ekran görüntüsünde görünen boşluğun tasarım amacı mı, dosya hatası mı olduğunu açıklamadan üretim kararı vermeyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Üretim aparatı için satın alma teknik eki',summary='İş parçası, istasyon ve kabul gereksinimlerini satın alma siparişine bağlayan açık bir teknik ek hazırlayın.',sections='[{"title":"Referans belgeleri sürümleriyle listeleyin","body":"Belirsiz bir ölçü varsa tasarım sorumlusunun karar vermesi için açık madde olarak yazın. Sipariş edilen aparatın hangi ürün kodlarıyla kullanılacağı ve hangi donanımı içerdiği ayrı satırlarda belirtilir."},{"title":"Kabul ve sorumlulukları görünür kılın","body":"Numuneyi kimin kuracağı, kimlerin değerlendireceği ve hangi raporun teslim edileceği tanımlanmalıdır. Saha kurulumu, eğitim veya periyodik kontrol talep ediliyorsa bunlar üretim parçasının doğal uzantısı sayılmaz; açık kapsam olur. Bu düzen, fiyatı teknik beklentiden bağımsız değerlendirmeyi önler."}]'::jsonb,faq='[{"q":"Toleransları üretici mi belirler?","a":"İşlevin gerektirdiği kabul sınırları yetkili tasarım veya kalite sorumlusundan gelmelidir. Üretilebilirlik değerlendirmesi bu gereksinimler üzerinden yapılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Teknik resim, CAD modeli ve saha fotoğrafı aynı revizyonu anlatmalıdır.","takeaways":["Belge numarası ve revizyon listesi","Kullanılacak ürün kodları","Kabul ve kurulum sorumluları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/teknik-teklif-dosyasi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Teknik teklif dosyası nasıl hazırlanır?","summary":"Satın alma ve teknik ekiplerin aynı dosya üzerinden ilerlemesi için parça, adet, revizyon ve kabul bilgilerini düzenleyin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Tek bir parça tablosu","body":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"title":"Kabul beklentisi","body":"Kritik ölçüler, görünür yüzeyler, işlevsel kontroller ve numune onayını kimin vereceği talepte yer alsın. Belgelenmeyen bir beklentinin teklif kapsamına otomatik girdiğini varsaymayın. Teslim dosyası ve fiziksel ürün kapsamını ayrı yazın."},{"title":"Takvim ve değişiklik","body":"Hedef tarihi, ara onay adımlarını ve revizyon için ayrılan süreyi belirtin. Talep sonrası geometri veya adet değişirse teklif yeniden değerlendirilebilir. Onaylanan sürümü teknik ekip ve satın alma arasında ortak referans yapın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Fikstür malzemesi için sahadan toplanacak bilgiler',summary='İşlem kuvveti, sürekli yük, sıcaklık ve kimyasal temas bilgilerini malzeme değerlendirmesine taşıyın.',sections='[{"title":"Sahadaki koşulu tahminden ayırın","body":"Temas edilen bölge ve çalışma süresi açıklanmalıdır. Yağ veya temizleyicinin ürün adı, genel bir dayanıklılık isteğinden daha somut bir değerlendirme girdisidir."},{"title":"Özelliği kabul yöntemiyle eşleştirin","body":"Aşınma, esneme veya ölçü kararlılığı sorunlarından hangisi öncelikliyse onu kontrol edecek numune denemesi planlanır. Gerekli teknik veri ve malzeme belgeleri belirlenir. Filament ailesinin adıyla test sonucunun yerini değiştirmeyin; aynı ailedeki ürünler farklı olabilir."}]'::jsonb,faq='[{"q":"Her gereksinim tek malzemeyle çözülebilir mi?","a":"Bazı tasarımlarda değiştirilebilir temas elemanı, metal donanım veya farklı gövde geometrisi birlikte değerlendirilir. Öncelikler belirlenmeden tek bir üstün malzeme seçilemez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"İstasyonun yakınında sıcak bir yüzey bulunması, bütün ortamın aynı sıcaklıkta olduğu anlamına gelmez.","takeaways":["Ölçülen ve tahmin edilen saha koşulları","Temas eden kimyasalların adı","Öncelikli başarısızlık ve kontrol yöntemi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/malzeme-secim-sorulari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Malzeme seçmeden önce sorulacak sorular","summary":"Malzeme kararını yalnızca isim veya renge göre değil, parçanın işlevi ve çalışma koşullarına göre hazırlayın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ortamı tanımlayın","body":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"title":"Geometriyi birlikte düşünün","body":"İnce bağlantılar, esneyen tırnaklar ve büyük düz yüzeyler farklı tasarım değerlendirmeleri gerektirir. Malzeme, yönlendirme ve üretim yöntemi birlikte ele alınmalıdır. Sadece doluluk oranını artırmak her işlevsel problemi çözmez."},{"title":"Numuneyle karar verin","body":"Kritik kullanımlarda numuneyi hedef ortama uygun bir kontrol planıyla değerlendirin. Malzeme veri sayfasını, üretim ayarlarını ve test koşullarını birbirine karıştırmayın. Nihai kabul ölçütünü üretimden önce belirleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Üretim hücresini ölçekli modelle değerlendirme',summary='Tam boyutlu fikstür üretiminden önce istasyon düzeni ve erişim fikrini bir yerleşim modeliyle tartışın.',sections='[{"title":"Yerleşim modelinin görevini sınırlayın","body":"Ancak gerçek kol erişimi, takım kuvveti veya çevrim güvenliği aynı ölçeğe taşınmış sayılmaz. Hangi kararların maket üzerinde, hangilerinin gerçek istasyonda verileceği açıklanmalıdır."},{"title":"Değişen elemanları ayrı tutun","body":"Farklı ürün besleme veya aparat konumları incelenecekse modüller sökülebilir tasarlanabilir. Ortak referans çizgisi ve ölçek korunur; her alternatif fotoğrafla belgelenir. Bir yerleşim seçildiğinde bunun mühendislik ve iş güvenliği değerlendirmesi gerçek ölçülerle devam eder."}]'::jsonb,faq='[{"q":"Maket onayı fikstür üretim onayı mıdır?","a":"Hayır; maket yerleşim kararına destek olur. Ayrıntılı parça geometrisi, yük ve kabul gereksinimleri ayrıca tamamlanmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Makine, tezgâh ve operatör alanının küçültülmüş temsili, alternatifleri karşılaştırmayı kolaylaştırabilir.","takeaways":["Karşılaştırılacak istasyon alternatifleri","Modelde sabit kalacak referanslar","Gerçek ölçekte doğrulanacak kararlar"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/maket-olcek-planlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Maket ölçeği ve parçalara ayırma","summary":"Mimari modelin fiziksel ölçüsünü, okunabilir detayını ve taşıma ihtiyacını tek üretim planında birleştirin. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçeği hesaplayın","body":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"title":"Detay seviyesini seçin","body":"Pencere, korkuluk ve peyzaj gibi öğeleri her ölçekte aynı biçimde üretmek uygun olmayabilir. Anlatım açısından gerekli ayrıntıları listeleyin. Fiziksel sınırlar nedeniyle sadeleştirilecek bölgeler için dijital onay alın."},{"title":"Taşıma ve montaj","body":"Taban ölçüsü, birleşim yerleri ve sökülebilir parçaları kutulama planıyla birlikte değerlendirin. Parçaları kodlayın ve yerleşim şemasını saklayın. Sergileme sırasında sık taşınacak bir maket için servis erişimini de planlayın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Fikstür numunesi için ölçü ve operasyon kontrol listesi',summary='Bir aparatın parçayı tutmasıyla üretim sürecine kabul edilmesi arasındaki kontrol adımlarını ayırın.',sections='[{"title":"Ölçü listesinde referansı gösterin","body":"Kullanılan cihaz ve yöntem de kayıt altına alınır. Teknik resimde olmayan kabul sınırları varsayılarak başarılı sonuç üretilmez; eksik koşul karar sorumlusuna geri taşınır."},{"title":"Operasyon denemesini ayrı kaydedin","body":"Yükleme kolaylığı, takım erişimi, yüzey izi ve boşaltma davranışı iş istasyonunda görülür. Denenen ürün varyantı ve aparat sürümü birlikte belirtilir. Red veya şartlı kabul maddeleri kapanmadan tekrar siparişin hangi kapsamda verilebileceği açık kalmalıdır."}]'::jsonb,faq='[{"q":"Sadece ölçü raporu aparatı onaylar mı?","a":"Ölçü uygunluğu bir girdidir. İşlev, operatör erişimi ve diğer süreç gereksinimleri varsa bunların kabulü de ayrıca yapılmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Delik konumu, dayama yüksekliği veya açıklık kontrol edilirken hangi yüzeyin başlangıç alındığı belli olmalıdır.","takeaways":["Ölçüm referansı ve kabul sınırları","Denemede kullanılan ürün varyantı","Operasyon bulguları ve karar sahibi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/rehber/numune-kabul-plani' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Numune kabul planı","summary":"Bir prototipin hangi koşullarda onaylanacağını üretimden önce tanımlayarak revizyon görüşmelerini somutlaştırın. 3dsanayi: endüstriyel parça & fikstür odağında değerlendirme.","sections":[{"title":"Endüstriyel parça & fikstür","body":"3dsanayi: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Endüstriyel parça & fikstür için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kontrol maddeleri","body":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"title":"Kayıt düzeni","body":"Numunenin dosya revizyonu, malzemesi, adedi ve test tarihi bir arada tutulmalıdır. Test sırasında yapılan elle düzeltmeler varsa bunları da kaydedin. Yeni baskıda aynı düzeltmenin yeniden gerekmemesi için dijital modele geri işleyin."},{"title":"Onaydan tekrar siparişe","body":"Hangi maddelerin geçtiğini ve hangilerinin açık kaldığını listeleyin. Koşullu onayı nihai onaydan ayırın. Tekrar sipariş verirken aynı revizyonu, değişen adetleri ve yeni kullanım koşullarını belirtin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/fixture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mimari maket teklifi için dosya paketi hazırlama',summary='Maketin sınırını, ölçeğini ve görünür ayrıntılarını mimari modelle aynı teslim paketinde açıklayın.',sections='[{"title":"Kaynak modelin katmanlarını belirtin","body":"Hangisinin güncel olduğunu ve hangilerinin makete dâhil edileceğini listeleyin. Sunum renderları görünüşü anlatırken ölçülü model üretim hazırlığına temel olur; iki verinin aynı revizyona ait olması kontrol edilmelidir."},{"title":"Çevre kapsamını çizimde işaretleyin","body":"Komşu yapılar, yollar, peyzaj ve kaide sınırı maliyet ile maket boyutunu etkiler. Dahil edilmeyen çevreyi belirsiz bırakmak yerine bir sınır çizgisiyle gösterin. Aydınlatma, etiket ve şeffaf kapak gibi ekleri dosya listesinde ayrı belirtin."}]'::jsonb,faq='[{"q":"Sadece kat planı ile başlanabilir mi?","a":"Kütle ve yükseklik bilgisi de gerekir. Eksik üç boyutlu modelin hazırlanması veya mevcut verinin dönüştürülmesi ayrı iş kapsamı olarak değerlendirilebilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bina, çevre, arazi ve iç mekân verileri farklı dosyalarda bulunabilir.","takeaways":["Güncel yapı, arazi ve çevre dosyaları","Modelde gösterilecek alan sınırı","Kaide, kapak ve etiket beklentileri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/teklif-icin-dosya-hazirlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Teklif için dosyanızı nasıl hazırlarsınız?","summary":"Teklif talebinde model kadar kullanım bilgisi de önemlidir. maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu projelerinde","body":"Kütle ve cephe kararlarını fizikselleştiren, tasarım aşamasına uygun detay seviyesinde maketler."},{"title":"Dosyanın birimini belirtin","body":"STL dosyası birim bilgisi taşımaz. Modelinizi milimetre olarak dışa aktarın ve Studio’da görünen boyutları kontrol edin. STEP dosyanız varsa montaj ilişkilerini değerlendirmek için ayrıca paylaşabilirsiniz."},{"title":"Teknik ihtiyacı tarif edin","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Sürümü takip edin","body":"Dosya adına parça kodu ve revizyon ekleyin. Birden fazla parçanın set halinde üretilmesini istiyorsanız her parça için adet belirtin."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket teklifinde model hazırlığı ve bitiş işlerini ayırma',summary='Baskıdan birleştirmeye, boya işinden kaideye kadar maketin toplam teslim kapsamını aynı ölçekte karşılaştırın.',sections='[{"title":"Ölçek fiyatın tek belirleyicisi değildir","body":"Ayrıntı yoğunluğu, model temizliği ve parça sayısı iş miktarını değiştirir. Teklifler karşılaştırılırken yalnızca santimetre veya baskı ağırlığına bakmak kapsamı gizler."},{"title":"Sunum donanımını ayrıca okuyun","body":"Peyzaj, ışık, kaide yazısı, taşıma kutusu ve mekânda kurulum ayrı ihtiyaçlardır. Boya veya yüzey düzeltme seviyesinin referans örnekle tarif edilmesi yararlıdır. Tasarım revizyonu geldikten sonra tamamlanmış parçaların yeniden hazırlanması gerekirse bunun etkisi yeni kapsam olarak değerlendirilir."}]'::jsonb,faq='[{"q":"Daha küçük maket her zaman daha ucuz mu olur?","a":"Küçültme bazı işleri azaltırken ince detayların yeniden modellenmesini gerektirebilir. Fiyat aynı görünür kapsam ve bitiş düzeyi üzerinden karşılaştırılmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Aynı dış boyuttaki iki maketten biri yalın kütlelerden, diğeri ince cephe ve sökülebilir katlardan oluşabilir.","takeaways":["Ölçekle birlikte detay seviyesi","Boya ve birleştirme kapsamı","Sunum ve taşıma donanımı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/3d-baski-fiyatlandirma' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D baskı fiyatı nasıl belirlenir?","summary":"Malzeme, üretim süresi ve teknik ihtiyaçlar birlikte değerlendirilir.","sections":[{"title":"Mimari maket & proje sunumu projelerinde","body":"Kütle ve cephe kararlarını fizikselleştiren, tasarım aşamasına uygun detay seviyesinde maketler."},{"title":"Hacim ve malzeme","body":"Aynı dış boyuttaki iki model farklı hacim ve duvar yapısına sahip olabilir. Malzeme tüketimi, destekler ve fire üretim hazırlığında değerlendirilir."},{"title":"Adet ve işlem süresi","body":"Tekrarlanan parçaların planlaması, kurulum ve son işlem toplam maliyeti etkiler. Büyük bir parçanın üretimi ile küçük parçaların toplu üretimi aynı değerlendirme değildir."},{"title":"Ön tahmin ve kesin teklif","body":"Studio hesabı bir bütçe göstergesidir. Dilimleme, üretilebilirlik, montaj gereksinimi ve teslimat kontrolü sonrası resmi teklif netleşir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Fiziksel maketi taramak mı dijitalden yeniden kurmak mı?',summary='Elde kalan modelin biçimini kaydetme ihtiyacı ile güncel bir proje modelini oluşturma ihtiyacını ayırın.',sections='[{"title":"Fiziksel örneğin temsil sınırını tanıyın","body":"Tarama bunları gerçek proje ayrıntısına dönüştürmez. Maketin ölçeği, sağlam bölgeleri ve hangi geometrinin korunacağı belirtilmelidir; güncel mimari çizimler varsa karşılaştırma için eklenir."},{"title":"İstenen çıktıyı sunum amacına göre seçin","body":"Dijital arşiv, yeniden üretim ve proje revizyonu farklı çıktılar gerektirebilir. Özellikle ince ve içe bakan yüzeylerin taramada ne kadar görülebildiği değerlendirilir. Eksik alanların modelleme ile tamamlanması gerekiyorsa bu yorumlar onay sürecinde görünür tutulur."}]'::jsonb,faq='[{"q":"Eski maketten güncel BIM modeli çıkar mı?","a":"Tarama yüzey bilgisidir; BIM elemanları ve proje bilgileri ayrıca kurulabilir. Böyle bir dönüşüm otomatik dosya kaydetme işlemi olarak ele alınmamalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Eski makette sadeleştirilmiş bir cephe veya eksik bir kütle bulunabilir.","takeaways":["Eski maketin bilinen ölçeği","Korunacak ve güncellenecek bölgeler","Varsa güncel plan ve cephe çizimleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/tarama-ve-tersine-muhendislik' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D tarama mı, tersine mühendislik mi?","summary":"Ölçülen yüzey ile yeniden tasarlanmış CAD modelinin farkı. maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu projelerinde","body":"Kütle ve cephe kararlarını fizikselleştiren, tasarım aşamasına uygun detay seviyesinde maketler."},{"title":"Yüzey verisi","body":"Tarama dış yüzeyin ölçümünü sağlar. Delikler, iç kanallar ve erişilemeyen alanlar için ek ölçüm gerekebilir."},{"title":"Düzenlenebilir model","body":"CAD modelleme, işlevi tanımlanan yüzeyler ve ölçüler üzerinden yeni bir dijital tasarım oluşturur. Geometriyi düzenlemek ve üretim için değiştirmek bu aşamada mümkündür."},{"title":"Doğru teslim tanımı","body":"Sadece görselleştirme, arşivleme veya yeniden üretim farklı çıktılar gerektirir. Hangi amaçla kullanılacağını teklif öncesinde belirtin."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket revizyonlarını yapı, çevre ve kaide düzeyinde takip etme',summary='Cephe veya yerleşim değişikliklerini maketin hangi modüllerine yansıdığını gösteren bir kayıtla yönetin.',sections='[{"title":"Değişiklik alanını çizim üzerinde sınırlayın","body":"Etkilenen blok ve yüzeyler işaretlenir. Üretimi tamamlanan bölüm ile henüz hazırlanacak bölüm ayrıldığında değişikliğin zaman ve iş kapsamına etkisi daha anlaşılır olur."},{"title":"Onay örneklerini sürümle eşleştirin","body":"Renk numunesi, küçük cephe parçası ve genel yerleşim farklı tarihlerde onaylanabilir. Her onayın hangi model revizyonuna ait olduğu belirtilmelidir. Kaide yazısı veya etiket değişikliği de teslim kontrolüne dâhil edilerek son dakika hataları azaltılabilir."}]'::jsonb,faq='[{"q":"Son mimari revizyon otomatik olarak bütün makete uygulanır mı?","a":"Revizyonun kapsamı ve üretimdeki mevcut durum karşılaştırılır. Etkilenen işlerin yeniden hazırlanması ve teslim planı ayrıca kararlaştırılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Yeni bir kat, cephe rengi veya peyzaj kararı yalnızca tek dosya adıyla tarif edilmemelidir.","takeaways":["Etkilenen blok ve cephelerin işaretlenmesi","Onaylı renk ve detay örnekleri","Kaide metninin son sürümü"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/numune-ve-revizyon' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Numuneden tekrar siparişe","summary":"Parçayı onaylamak ve doğru revizyonla devam etmek. maketyanımda ile mimari maket & proje sunumu için proje bazlı değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu projelerinde","body":"Kütle ve cephe kararlarını fizikselleştiren, tasarım aşamasına uygun detay seviyesinde maketler."},{"title":"İlk kontrol","body":"Numuneyi gerçek montaj ortamında değerlendirin. Uyum, erişim ve kullanım sırasında karşılaşılan noktaları fotoğraf ve ölçüyle kaydedin."},{"title":"Revizyon kararı","body":"Değişen ölçüleri açıkça belirtin. Tasarım güncellemelerinin eski dosyayla karışmaması için yeni bir revizyon adı kullanın."},{"title":"Tekrar üretim","body":"Onaylanan dosya, malzeme ve üretim ayarları tekrar talebin başlangıcıdır. Malzeme veya kullanım koşulu değiştiğinde yeniden değerlendirme gerekir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mimari modelin baskı için STL hazırlığı',summary='Bina modelindeki duvar, açıklık ve ayrı kütleleri maket ölçeğinde üretilebilir bir ağ yapısına dönüştürün.',sections='[{"title":"Ölçeği dış ölçüyle doğrulayın","body":"Ölçeklendirmeden sonra toplam taban ve bina yüksekliğini yeniden kontrol edin. Gerçekte ince olan bir duvarın makette çok narin kalacağı bölgeleri ayrı listeleyerek temsil biçimini kararlaştırın."},{"title":"Üretim parçalarını açıkça ayırın","body":"Çatı, kat, cephe ve arazi bölümleri ayrı basılacaksa isimlendirme ile montaj yönleri anlaşılır olmalıdır. İç içe geçen yüzeyler veya kapalı olmayan duvarlar ağ kontrolünde incelenir. Mimari modelde faydalı olan her iç elemanın makete taşınması gerekmez; seçilen görünür kapsam korunur."}]'::jsonb,faq='[{"q":"Mimari modeldeki tüm detaylar aynı oranda küçültülür mü?","a":"Her ayrıntı fiziksel ölçekte okunamaz veya üretilemez. Sadeleştirme, kalınlaştırma ve ayrı üretim kararları mimari temsil onayıyla yapılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Kaynak model metre, dışa aktarım yazılımı milimetre kullanıyorsa boyut yorumu değişebilir.","takeaways":["Son modelin milimetre dış ölçüleri","Üretim için ayrılan kütleler","Ölçekte kaybolan ince detaylar"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/stl-dosya-hazirlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"STL dosyası hazırlama kontrol listesi","summary":"Tekliften önce birim, dış ölçü, yüzey bütünlüğü ve revizyon bilgisini aynı kontrol listesiyle gözden geçirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Birim ve ölçek","body":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"title":"Yüzey ve ayrıntı","body":"Modelde açık yüzey, üst üste geometri veya istenmeyen iç parçalar olup olmadığını CAD yazılımınızda kontrol edin. Görüntüleyicide kesit almak iç ilişkileri anlamayı kolaylaştırır; ancak otomatik üretilebilirlik doğrulamasının yerini tutmaz."},{"title":"Dosya paketi","body":"Parça kodu ve revizyonu dosya adına ekleyin. Adet, kritik ölçü ve kullanım koşullarını ayrı not edin. Birden fazla dosyada aynı kodu farklı revizyonlarla karıştırmayın; onaylanmış sürümü açıkça işaretleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mevcut yapı veya maket taramasını sunum modeline dönüştürme',summary='Yüzey verisini temiz bir maket geometrisine aktarırken ölçek, eksik alan ve gösterilecek kapsamı belirleyin.',sections='[{"title":"Verinin neyi kapsadığını işaretleyin","body":"Çatı, arka cephe ve kapalı boşlukların veride bulunup bulunmadığı kontrol edilir. Tamamlanacak alanlar proje çiziminden mi yoksa modelleme yorumundan mı geleceği açıkça belirtilir."},{"title":"Maket için gerekli sadeleştirmeyi seçin","body":"Düzensiz yüzey ayrıntısının tamamı küçük ölçekte anlamlı olmayabilir. Silüet, karakteristik cephe ve arazi ilişkisi gibi korunacak özellikler listelenir. Üretim dosyasının sadeleşmesi, referans verinin kaybolması anlamına gelmemeli; kaynak tarama ve çıktı sürümleri ayrı tutulmalıdır."}]'::jsonb,faq='[{"q":"Tarama hataları baskıda görünür mü?","a":"Ağdaki eksik veya bozuk yüzeyler üretim geometrisini etkileyebilir. Temizlik ve kapatma işlemleri tamamlandıktan sonra ölçekli model ayrıca incelenmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Tarama bir objeyi veya yapının yalnızca görülebilen yüzlerini içeriyor olabilir.","takeaways":["Taramanın kapsadığı görünür yüzeyler","Eksik alanlar için ek proje verisi","Korunacak karakteristik mimari çizgiler"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/tarama-verisinden-cad' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Tarama verisinden CAD modeline","summary":"Nokta bulutu, yüzey ağı ve düzenlenebilir CAD çıktısını ayırarak tersine mühendislik talebinizi doğru kapsamlandırın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hangi veri elinizde?","body":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"title":"Fonksiyonel yüzeyler","body":"Delik, mil yatağı, oturma yüzeyi ve bağlantı eksenlerini işaretleyin. Aşınmış veya kırılmış bölgeyi olduğu gibi kopyalamak yerine korunması gereken tasarım ilişkisini açıklayın. Gerekirse sağlam karşı parça da değerlendirmeye eklenir."},{"title":"Teslim ve kontrol","body":"İstenen formatı, revizyon kapsamını ve kontrol edilecek ölçüleri baştan belirleyin. Tarama ile CAD arasındaki farkların nasıl değerlendirileceğini kararlaştırın. Sadece görsel benzerlik, ölçüsel kabulün yerine geçmez."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket kesitinde iç mekânı ve kat ilişkisini gösterme',summary='Kesit düzlemini anlatılacak mekânsal ilişkiye göre seçerek maketin nasıl açılıp okunacağını planlayın.',sections='[{"title":"Kesiti hikâyenin içinden geçirin","body":"Sadece yapıyı ortadan bölmek her zaman iyi bir anlatım vermez. Kesitte kalan duvarların maket ölçeğinde okunabilirliği ve birleşimin dış görünüşe etkisi birlikte değerlendirilir."},{"title":"Açılan parçanın tutulmasını tasarlayın","body":"Çıkarılabilir kat veya yapı yarısı için elin kavrayacağı bir bölge gerekir. Küçük cephe elemanlarının tutma sırasında zarar görmemesi düşünülür. Sökülen parçaların masada nerede duracağı ve tekrar hangi yönde takılacağı sunum akışına eklenir."}]'::jsonb,faq='[{"q":"Dijital kesit fiziksel makette otomatik oluşur mu?","a":"Hayır; baskı için bölme, birleşim ve destek geometrileri ayrıca hazırlanmalıdır. Görüntüleyicide seçilen düzlem bir anlatım kararı olarak modellemeye aktarılır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Merdiven, atrium veya katlar arası ilişki gösterilecekse kesit bu alanları anlamlı biçimde açmalıdır.","takeaways":["Anlatılacak iç mekân ilişkisi","Kesit düzleminin yeri","Sökülen parçanın tutma ve saklama yüzeyi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/kesit-nasil-incelenir' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D modelde kesit nasıl incelenir?","summary":"Kesit düzlemini kullanarak iç boşlukları, montaj ilişkilerini ve beklenmeyen yüzeyleri görünür hale getirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Düzlem yönünü seçin","body":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"title":"Görsel kesitin sınırları","body":"Tarayıcıdaki araç yüzeyleri düzleme göre gizler. Açılan kesiti kapatmaz, takım yolu veya baskı katmanı üretmez. Duvar kalınlığı ya da tolerans raporu gerekiyorsa ölçüm ve üretim yazılımlarındaki uygun araçlarla doğrulama yapın."},{"title":"Bulgunuzu tarif edin","body":"İncelediğiniz ekseni, düzlem konumunu ve sorunlu bölgeyi not edin. Talebe dosyanın aynı revizyonunu ekleyin. Bir ekran görüntüsünde görünen boşluğun tasarım amacı mı, dosya hatası mı olduğunu açıklamadan üretim kararı vermeyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Mimari maket için üretim ve teslim şartları dosyası',summary='Ölçek, model sınırı, bitiş örneği ve sunum donanımını tek bir teslim listesinde tanımlayın.',sections='[{"title":"Görünür kapsamı maddelerle yazın","body":"Her bileşenin renk ve yüzey beklentisi, mümkünse örnekle eşleştirilir. Belirli bir bloğun çıkarılabilir olması gibi işlevler genel maket adı altında kaybolmamalıdır."},{"title":"Teslim mekânını planın parçası yapın","body":"Kapı ve asansör ölçüsü, taşıma kasası, kurulum yüzeyi ve elektrik ihtiyacı varsa talepte belirtilir. Teknik teslim ile sunum günü farklı olabilir. Nakliye, yerinde kurulum ve sonraki onarım beklentileri teklif kapsamında ayrı değerlendirilmelidir."}]'::jsonb,faq='[{"q":"Teklifte yalnızca ölçek belirtmek yeterli mi?","a":"Ölçek dışında alan sınırı, detay, bitiş ve teslim donanımı gerekir. Aynı ölçek çok farklı iş kapsamları oluşturabilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Bina kabuğu, iç mekân, çevre yapıları ve peyzajın hangi düzeyde gösterileceği açıklanmalıdır.","takeaways":["Model sınırı ve görünür bileşenler","Renk, yüzey ve çıkarılabilir bölümler","Teslim mekânı ve kurulum koşulları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/teknik-teklif-dosyasi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Teknik teklif dosyası nasıl hazırlanır?","summary":"Satın alma ve teknik ekiplerin aynı dosya üzerinden ilerlemesi için parça, adet, revizyon ve kabul bilgilerini düzenleyin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Tek bir parça tablosu","body":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"title":"Kabul beklentisi","body":"Kritik ölçüler, görünür yüzeyler, işlevsel kontroller ve numune onayını kimin vereceği talepte yer alsın. Belgelenmeyen bir beklentinin teklif kapsamına otomatik girdiğini varsaymayın. Teslim dosyası ve fiziksel ürün kapsamını ayrı yazın."},{"title":"Takvim ve değişiklik","body":"Hedef tarihi, ara onay adımlarını ve revizyon için ayrılan süreyi belirtin. Talep sonrası geometri veya adet değişirse teklif yeniden değerlendirilebilir. Onaylanan sürümü teknik ekip ve satın alma arasında ortak referans yapın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket malzemesini seçerken görünüş ve kullanım soruları',summary='Sergileme, dokunma, taşınma ve yüzey beklentisini malzeme kararına taşıyın.',sections='[{"title":"İzleyicinin modelle ilişkisini tarif edin","body":"Hangi parçaların elle tutulacağı ve hangi yüzlerin yakın mesafeden inceleneceği seçilir. Bu bilgiler hem geometriyi hem de parça bazında malzeme kararını etkiler."},{"title":"Baskı rengini bitmiş yüzeyden ayırın","body":"Ham baskı, astarlı yüzey ve boyalı görünüş farklı teslim seçenekleridir. Saydam veya metalik görünüş istendiğinde fiziksel örnekle beklenti netleştirilir. Sergileme ortamındaki güneş ve ısı koşulları da değerlendirilerek sadece estetik tercihle malzeme seçilmez."}]'::jsonb,faq='[{"q":"Bütün maket aynı malzemeden mi olmalı?","a":"Farklı görevdeki bölümler için farklı yöntemler değerlendirilebilir. Görünüş uyumu ve birleşim biçimi toplam model üzerinde birlikte kontrol edilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Vitrin arkasındaki maket ile eğitim sırasında sürekli açılan model aynı kullanım yükünü görmez.","takeaways":["Elle tutulacak ve yalnız izlenecek bölgeler","Ham veya boyalı bitiş tercihi","Sergileme ve taşıma koşulları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/malzeme-secim-sorulari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Malzeme seçmeden önce sorulacak sorular","summary":"Malzeme kararını yalnızca isim veya renge göre değil, parçanın işlevi ve çalışma koşullarına göre hazırlayın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ortamı tanımlayın","body":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"title":"Geometriyi birlikte düşünün","body":"İnce bağlantılar, esneyen tırnaklar ve büyük düz yüzeyler farklı tasarım değerlendirmeleri gerektirir. Malzeme, yönlendirme ve üretim yöntemi birlikte ele alınmalıdır. Sadece doluluk oranını artırmak her işlevsel problemi çözmez."},{"title":"Numuneyle karar verin","body":"Kritik kullanımlarda numuneyi hedef ortama uygun bir kontrol planıyla değerlendirin. Malzeme veri sayfasını, üretim ayarlarını ve test koşullarını birbirine karıştırmayın. Nihai kabul ölçütünü üretimden önce belirleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket ölçeğini taban ve parça boyutuyla kontrol etme',summary='Seçilen ölçeğin gerçek sunum boyutuna dönüşümünü hesaplayıp üretim ve taşımayı aynı plan üzerinde değerlendirin.',sections='[{"title":"Gerçek boyutu aynı birime çevirin","body":"Örneğin 12 metre, modelde 120 milimetre olur. Yapı yüksekliği kadar bütün arazi sınırını da hesaplayın; küçük bir bina modeli geniş çevreyle birlikte çok büyük taban gerektirebilir."},{"title":"Bölmeyi son aşamaya bırakmayın","body":"Toplam boyut üretim hacmini veya taşıma sınırını aşıyorsa modüller planlanır. Birleşim hattının görünüşe etkisi, hizalama ve kurulum sırası değerlendirilir. İnce detayların hedef ölçekte ne kadar kalacağı kontrol edilerek gerekirse temsil biçimi değiştirilir."}]'::jsonb,faq='[{"q":"300 mm sığan modelin tamamı tek seferde basılır mı?","a":"Makine hacmine sığmak tek koşul değildir. Yönlendirme, destek, yüzey ve parçanın sağlam çıkarılması gibi etkenler üretim değerlendirmesine girer."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"1:100 ölçekte gerçek uzunluk aynı birimde yüze bölünür.","takeaways":["Ölçek ve aynı birimde hesaplanmış boyutlar","Çevre dahil toplam taban alanı","Üretim ve taşıma için modül sınırları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/maket-olcek-planlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Maket ölçeği ve parçalara ayırma","summary":"Mimari modelin fiziksel ölçüsünü, okunabilir detayını ve taşıma ihtiyacını tek üretim planında birleştirin. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçeği hesaplayın","body":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"title":"Detay seviyesini seçin","body":"Pencere, korkuluk ve peyzaj gibi öğeleri her ölçekte aynı biçimde üretmek uygun olmayabilir. Anlatım açısından gerekli ayrıntıları listeleyin. Fiziksel sınırlar nedeniyle sadeleştirilecek bölgeler için dijital onay alın."},{"title":"Taşıma ve montaj","body":"Taban ölçüsü, birleşim yerleri ve sökülebilir parçaları kutulama planıyla birlikte değerlendirin. Parçaları kodlayın ve yerleşim şemasını saklayın. Sergileme sırasında sık taşınacak bir maket için servis erişimini de planlayın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Maket numunesinde ölçek, detay ve bitiş onayı',summary='Tüm modeli tamamlamadan önce bir köşe, cephe veya modül üzerinde önemli sunum kararlarını doğrulayın.',sections='[{"title":"Temsilî numuneyi doğru seçin","body":"Örnekte pencere çizgisi, birleşim ve boya beklentisi görülebilir. Numunenin hangi ölçek ve model revizyonuna ait olduğu yazılmalıdır; farklı ölçekteki bir parçadan aynı detay sonucu beklenmez."},{"title":"Görünüşü gerçek mesafeden inceleyin","body":"Yakından görülen katman izi ile sunum mesafesindeki algı farklı olabilir. Modelin kullanılacağı ışık ve izleme biçimi göz önünde bulundurulur. Kabul kaydı; renk, birleşim, modül hareketi ve metin doğruluğunu ayrı başlıklarda ele alarak düzeltilecek alanları belirtir."}]'::jsonb,faq='[{"q":"Ekran görüntüsü renk onayı için yeterli mi?","a":"Ekran ve ışık renk algısını değiştirir. Kritik bir renk eşleşmesi gerekiyorsa fiziksel örnek veya belirlenmiş renk referansı üzerinden karar verilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"En kolay düz yüzey yerine maketin karakterini anlatan bir bölüm seçmek daha yararlıdır.","takeaways":["Temsilî cephe veya birleşim örneği","Gerçek sunum mesafesi ve ışık","Renk, metin ve modül kontrolü"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/rehber/numune-kabul-plani' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Numune kabul planı","summary":"Bir prototipin hangi koşullarda onaylanacağını üretimden önce tanımlayarak revizyon görüşmelerini somutlaştırın. maketyanımda: mimari maket & proje sunumu odağında değerlendirme.","sections":[{"title":"Mimari maket & proje sunumu","body":"maketyanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Mimari maket & proje sunumu için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kontrol maddeleri","body":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"title":"Kayıt düzeni","body":"Numunenin dosya revizyonu, malzemesi, adedi ve test tarihi bir arada tutulmalıdır. Test sırasında yapılan elle düzeltmeler varsa bunları da kaydedin. Yeni baskıda aynı düzeltmenin yeniden gerekmemesi için dijital modele geri işleyin."},{"title":"Onaydan tekrar siparişe","body":"Hangi maddelerin geçtiğini ve hangilerinin açık kaldığını listeleyin. Koşullu onayı nihai onaydan ayırın. Tekrar sipariş verirken aynı revizyonu, değişen adetleri ve yeni kullanım koşullarını belirtin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/architecture.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Kırık veya kayıp parça için ilk talep nasıl hazırlanır?',summary='Parçanın işlevini, montaj yerini ve eldeki referansları teknik değerlendirmeye hazır bir fotoğraf ve ölçü paketine dönüştürün.',sections='[{"title":"Sadece kırığı değil çevresini gösterin","body":"Ön, arka ve yan yüzleri ekleyin. Ölçü cetvelinin fotoğrafta bulunması yardımcı olabilir, fakat kritik boyutlar ayrıca ölçülüp yazılmalıdır."},{"title":"Eldeki referansları sınıflandırın","body":"Kırık örnek, sağlam eş parça, eski çizim ve internet görseli farklı güvenilirlikte girdilerdir. Hangisinin size ait ürünü gerçekten temsil ettiğini belirtin. Parça kayıpsa yuva ve işlev üzerinden yeni tasarım gerekeceği açıkça konuşulur."}]'::jsonb,faq='[{"q":"Tek fotoğraftan kesin fiyat ve uyum söylenebilir mi?","a":"Görünmeyen bağlantılar ve ölçüler fiyatı değiştirebilir. İlk görsel kapsamı anlamaya yardımcı olur; modelleme ve numune ihtiyacı netleşmeden kesin uyum varsayılmaz."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Yakın çekim hasarı gösterir; parçanın nerede durduğunu anlatan geniş fotoğraf ise görevini açıklar.","takeaways":["Montaj yerinin geniş fotoğrafı","Ön, arka ve yan yüzler","Kritik ölçüler ve referansın kaynağı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/teklif-icin-dosya-hazirlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Teklif için dosyanızı nasıl hazırlarsınız?","summary":"Teklif talebinde model kadar kullanım bilgisi de önemlidir. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv projelerinde","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"Dosyanın birimini belirtin","body":"STL dosyası birim bilgisi taşımaz. Modelinizi milimetre olarak dışa aktarın ve Studio’da görünen boyutları kontrol edin. STEP dosyanız varsa montaj ilişkilerini değerlendirmek için ayrıca paylaşabilirsiniz."},{"title":"Teknik ihtiyacı tarif edin","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Sürümü takip edin","body":"Dosya adına parça kodu ve revizyon ekleyin. Birden fazla parçanın set halinde üretilmesini istiyorsanız her parça için adet belirtin."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Tek adet özel parçanın fiyatında neler bulunur?',summary='Yeniden modelleme, bağlantı denemesi, parça üretimi ve görünür yüzey işini ayrı kalemler olarak değerlendirin.',sections='[{"title":"Bir parçanın tasarım emeğini görün","body":"Karşı parçanın ölçülmesi ve eksik bölgenin tasarlanması ilk siparişe özgü hazırlık olabilir. Tek adet talepte bu emek toplam bedelin önemli bölümünü oluşturabilir; yalnızca gramla açıklanamaz."},{"title":"Uyum denemesi ve bitişi sıraya koyun","body":"Önce bağlantı bölgesi onaylanıp sonra görünür yüzey işi yapılacaksa kapsam iki aşamada ele alınabilir. Renk veya doku düzeltmesinin ne kadar beklendiği belirtilmelidir. Tekrar sipariş, onaylı dosya ve değişmeyen montaj koşulları üzerinden ayrıca değerlendirilir."}]'::jsonb,faq='[{"q":"Tek parça neden hazır seri üründen pahalı olabilir?","a":"Seri üründeki tasarım ve kalıp maliyeti çok sayıda parçaya dağılır. Özel tek parçada ölçü, modelleme ve deneme işleri yalnızca o talebe ait olabilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Kayıp veya kırık örnekten geometri kurmak, hazır dosyayı basmaktan farklı iştir.","takeaways":["Hazır dosya veya modelleme ihtiyacı","Bağlantı numunesinin kapsamı","Görünür yüzey ve tekrar adetleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/3d-baski-fiyatlandirma' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D baskı fiyatı nasıl belirlenir?","summary":"Malzeme, üretim süresi ve teknik ihtiyaçlar birlikte değerlendirilir.","sections":[{"title":"Özel plastik parça & otomotiv projelerinde","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"Hacim ve malzeme","body":"Aynı dış boyuttaki iki model farklı hacim ve duvar yapısına sahip olabilir. Malzeme tüketimi, destekler ve fire üretim hazırlığında değerlendirilir."},{"title":"Adet ve işlem süresi","body":"Tekrarlanan parçaların planlaması, kurulum ve son işlem toplam maliyeti etkiler. Büyük bir parçanın üretimi ile küçük parçaların toplu üretimi aynı değerlendirme değildir."},{"title":"Ön tahmin ve kesin teklif","body":"Studio hesabı bir bütçe göstergesidir. Dilimleme, üretilebilirlik, montaj gereksinimi ve teslimat kontrolü sonrası resmi teklif netleşir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Kırık parçayı taramak eksik kısmı tamamlar mı?',summary='Taramanın kaydettiği mevcut yüzeyi, eksik geometriyi yeniden kurmak için gereken referanslardan ayırın.',sections='[{"title":"Veride olmayan biçimi ayrıca çözün","body":"Sağlam karşı örnek, simetri, yuva veya teknik çizim destekleyici veri olabilir. Hangi bölgenin ölçüldüğü, hangisinin yorumlanarak modellendiği çalışmanın başlangıcında anlaşılmalıdır."},{"title":"Gereken yöntemi parçaya göre seçin","body":"Basit düz yüzeyli bir bağlantı ölçüyle modellenebilirken karmaşık serbest biçim için tarama yararlı olabilir. Her parçayı taramak zorunlu değildir. Hedef çıktı ve kritik yüzeyler belirlenerek ölçü, tarama ve modellemenin ne kadar gerektiği değerlendirilir."}]'::jsonb,faq='[{"q":"Kırık örnek yapıştırılıp taranmalı mı?","a":"Örneği değiştirmeden önce nasıl kullanılacağını görüşmek yararlı olur. Hatalı hizalanmış bir tamir referansı bozabilir; tüm kırık parçalar ayrı gösterilmelidir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Kırılan tırnağın yalnızca kökü kalmışsa tarayıcı tırnağın eski boyunu bilmez.","takeaways":["Eksik ve sağlam bölgelerin ayrımı","Karşı örnek veya montaj yuvası","Ölçüyle çözülebilen yüzeyler"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/tarama-ve-tersine-muhendislik' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D tarama mı, tersine mühendislik mi?","summary":"Ölçülen yüzey ile yeniden tasarlanmış CAD modelinin farkı. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv projelerinde","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"Yüzey verisi","body":"Tarama dış yüzeyin ölçümünü sağlar. Delikler, iç kanallar ve erişilemeyen alanlar için ek ölçüm gerekebilir."},{"title":"Düzenlenebilir model","body":"CAD modelleme, işlevi tanımlanan yüzeyler ve ölçüler üzerinden yeni bir dijital tasarım oluşturur. Geometriyi düzenlemek ve üretim için değiştirmek bu aşamada mümkündür."},{"title":"Doğru teslim tanımı","body":"Sadece görselleştirme, arşivleme veya yeniden üretim farklı çıktılar gerektirir. Hangi amaçla kullanılacağını teklif öncesinde belirtin."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Özel parçanın ilk uyum denemesini kaydetme',summary='Takılma, boşluk ve sökme sorunlarını fotoğrafla belirleyerek revizyonu montaj koşuluna bağlayın.',sections='[{"title":"Uyumsuzluğu belirli noktada tarif edin","body":"“Biraz küçültelim” kararı bütün geometriyi etkileyebilir; sorun yalnızca tek tırnakta olabilir. İlk denemede kullanılan cihaz veya araç varyantı da kayıt altına alınmalıdır."},{"title":"Düzeltmeden sonra aynı kontrolü tekrarlayın","body":"Yeni numune farklı bir yuvada denenirse önceki bulguyla doğrudan karşılaştırılamayabilir. Referans montajı koruyun. Uyum onayı ile renk veya görünüş onayı ayrı verilebilir; sonraki üretimde hangi örneğin referans olduğu açık tutulur."}]'::jsonb,faq='[{"q":"Parçayı kendim eğip keserek denemeli miyim?","a":"Yapılan müdahale ölçü yorumunu değiştirebilir. Önce fotoğraf ve gözlem paylaşmak, gerekli revizyonun dosyada kontrollü biçimde yapılmasına yardımcı olur."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Parça hiç girmiyorsa zorlanan kenarı, gevşekse hareket yönünü gösterin.","takeaways":["Sürtme veya boşluk noktasının fotoğrafı","Denemenin yapıldığı gerçek yuva","Uyum ve görünüş kararlarının ayrımı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/numune-ve-revizyon' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Numuneden tekrar siparişe","summary":"Parçayı onaylamak ve doğru revizyonla devam etmek. parçayanımda ile özel plastik parça & otomotiv için proje bazlı değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv projelerinde","body":"Bulunamayan iç trim, kapak ve plastik aksesuarları kullanım senaryosu ve örnek parça üzerinden değerlendirelim."},{"title":"İlk kontrol","body":"Numuneyi gerçek montaj ortamında değerlendirin. Uyum, erişim ve kullanım sırasında karşılaşılan noktaları fotoğraf ve ölçüyle kaydedin."},{"title":"Revizyon kararı","body":"Değişen ölçüleri açıkça belirtin. Tasarım güncellemelerinin eski dosyayla karışmaması için yeni bir revizyon adı kullanın."},{"title":"Tekrar üretim","body":"Onaylanan dosya, malzeme ve üretim ayarları tekrar talebin başlangıcıdır. Malzeme veya kullanım koşulu değiştiğinde yeniden değerlendirme gerekir."}],"faq":[],"image":"","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='İndirilen yedek parça STL dosyasını kontrol etme',summary='Hazır dosyanın cihazınıza uygunluğunu, ölçü birimini ve kullanım iznini baskıdan önce gözden geçirin.',sections='[{"title":"Benzer model adını uyum kanıtı saymayın","body":"Dosyanın açıklamasındaki model listesiyle kendi parçanızı karşılaştırın. Önemli bağlantı ölçülerini gerçek yuvadan kontrol ederek eksik veya farklı alanları işaretleyin."},{"title":"Dosyanın üretim yapısını inceleyin","body":"Bir STL birden fazla kabuk, açık yüzey veya çok ince bölge içerebilir. Ölçek ve dış boyut kontrolünden sonra bu alanlar incelenir. Parçanın kullanıma uygunluğu dosyanın indirilebilir olmasından kaynaklanmaz; görev ve malzeme değerlendirmesi ayrıca yapılır."}]'::jsonb,faq='[{"q":"Ücretsiz indirilen her dosya ticari üretimde kullanılabilir mi?","a":"Dosyanın lisansı ve kullanım şartları kontrol edilmelidir. İndirilebilir olması her kullanım veya satış biçimine izin verildiği anlamına gelmez."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Aynı cihaz ailesindeki revizyonlar delik, tırnak veya konektör yerini değiştirebilir.","takeaways":["Desteklenen cihaz revizyonu","Gerçek yuvadan kritik ölçüler","Dosyanın lisans ve kaynak bağlantısı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/stl-dosya-hazirlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"STL dosyası hazırlama kontrol listesi","summary":"Tekliften önce birim, dış ölçü, yüzey bütünlüğü ve revizyon bilgisini aynı kontrol listesiyle gözden geçirin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Birim ve ölçek","body":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"title":"Yüzey ve ayrıntı","body":"Modelde açık yüzey, üst üste geometri veya istenmeyen iç parçalar olup olmadığını CAD yazılımınızda kontrol edin. Görüntüleyicide kesit almak iç ilişkileri anlamayı kolaylaştırır; ancak otomatik üretilebilirlik doğrulamasının yerini tutmaz."},{"title":"Dosya paketi","body":"Parça kodu ve revizyonu dosya adına ekleyin. Adet, kritik ölçü ve kullanım koşullarını ayrı not edin. Birden fazla dosyada aynı kodu farklı revizyonlarla karıştırmayın; onaylanmış sürümü açıkça işaretleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"STL dosyasındaki koordinatları hangi birimde dışa aktardığınızı kaydedin. Önizleyicide dış ölçüleri tasarımınızla karşılaştırın. Milimetre ve inç karışıklığı, görünüş aynı olsa da üretilecek parçanın boyutunu değiştirir."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Aşınmış numuneden sağlam bağlantı geometrisi kurma',summary='Yüzey kopyasından üretilebilir özel parçaya geçerken yuva, eksen ve simetri referanslarını açıkça belirleyin.',sections='[{"title":"Hasarlı yüzeyi referans olarak seçmeyin","body":"Bu yüzeyin tarama verisinde bulunması onu nominal ölçü yapmaz. Karşı bağlantı elemanı ve sağlam bölgeler kullanılarak yeni geometrinin neye dayanacağı belirlenir."},{"title":"Küçük arayüz numunesiyle varsayımı kontrol edin","body":"Ana parçanın yalnızca geçme veya vida bölgesini içeren bir test baskısı düşünülebilir. Buradan gelen ölçü düzeltmesi ana modele kontrollü biçimde aktarılır. Nihai dosyayla onaylanan numunenin ilişkisi kaydedilerek farklı sürümlerin karışması önlenir."}]'::jsonb,faq='[{"q":"Tarama dosyasındaki her pürüz korunmalı mı?","a":"Yüzey dokusu, aşınma ve tasarım biçimi farklı değerlendirilir. Hangi özelliğin işlev veya görünüş için korunacağı modelleme kapsamının parçasıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Aşınmış bir delik ovalleşmiş veya kırık bir kenar yer değiştirmiş olabilir.","takeaways":["Sağlam referans yüzeyleri","Eşleşen bağlantı elemanı","Test edilecek küçük arayüz bölgesi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/tarama-verisinden-cad' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Tarama verisinden CAD modeline","summary":"Nokta bulutu, yüzey ağı ve düzenlenebilir CAD çıktısını ayırarak tersine mühendislik talebinizi doğru kapsamlandırın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Hangi veri elinizde?","body":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"title":"Fonksiyonel yüzeyler","body":"Delik, mil yatağı, oturma yüzeyi ve bağlantı eksenlerini işaretleyin. Aşınmış veya kırılmış bölgeyi olduğu gibi kopyalamak yerine korunması gereken tasarım ilişkisini açıklayın. Gerekirse sağlam karşı parça da değerlendirmeye eklenir."},{"title":"Teslim ve kontrol","body":"İstenen formatı, revizyon kapsamını ve kontrol edilecek ölçüleri baştan belirleyin. Tarama ile CAD arasındaki farkların nasıl değerlendirileceğini kararlaştırın. Sadece görsel benzerlik, ölçüsel kabulün yerine geçmez."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Tarama sonucunuz nokta verisi veya üçgen yüzey ağı olabilir. Düzenlenebilir katı model gereksinimini ayrıca belirtin. Görüntülenebilen bir dosyanın otomatik olarak parametrik CAD dosyası olduğu varsayılmaz."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Özel parçada tırnak, yuva ve iç boşluğu kesitte inceleme',summary='Dış fotoğrafta görünmeyen bağlantı ilişkilerini kesitle açarak uyum probleminin yerini belirleyin.',sections='[{"title":"Tırnağın hareket yolunu gösterin","body":"Kesit düzlemi bu hareketi gösterecek şekilde seçilir. Tırnak boyu ve altında kalan gövde, üretim yönü ve malzemeyle birlikte değerlendirilmelidir; tek bir görüntü işlev onayı değildir."},{"title":"Karşı parçayı aynı referansta düşünün","body":"Yuva ölçüsü bilinmeden sadece yeni parçanın kesitine bakmak ilişkiyi eksik bırakır. Karşı geometri veya ölçülü eskiz eklenerek oturma ve durma yüzeyleri seçilir. En dar bölge için küçük deneme numunesi hazırlanması revizyonun etkisini daha erken gösterebilir."}]'::jsonb,faq='[{"q":"Kesitte görünen boşluk baskıda aynen oluşur mu?","a":"Üretim ve montaj değişkenleri nedeniyle numune kontrolü gerekir. Görüntülenen geometri hedefi gösterir; gerçek uygunluk denemeyle değerlendirilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Esnek bağlantı yalnızca son konumda değil takılma sırasında da boşluğa ihtiyaç duyar.","takeaways":["Tırnağın takılma ve çalışma konumu","Karşı yuvanın kesit ölçüleri","En dar veya sürten bağlantı bölgesi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/kesit-nasil-incelenir' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"3D modelde kesit nasıl incelenir?","summary":"Kesit düzlemini kullanarak iç boşlukları, montaj ilişkilerini ve beklenmeyen yüzeyleri görünür hale getirin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Düzlem yönünü seçin","body":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"title":"Görsel kesitin sınırları","body":"Tarayıcıdaki araç yüzeyleri düzleme göre gizler. Açılan kesiti kapatmaz, takım yolu veya baskı katmanı üretmez. Duvar kalınlığı ya da tolerans raporu gerekiyorsa ölçüm ve üretim yazılımlarındaki uygun araçlarla doğrulama yapın."},{"title":"Bulgunuzu tarif edin","body":"İncelediğiniz ekseni, düzlem konumunu ve sorunlu bölgeyi not edin. Talebe dosyanın aynı revizyonunu ekleyin. Bir ekran görüntüsünde görünen boşluğun tasarım amacı mı, dosya hatası mı olduğunu açıklamadan üretim kararı vermeyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"İncelemek istediğiniz detayın geçtiği ekseni bulun. X, Y ve Z yönlerini sırayla deneyin; sonra düzlemi yavaşça modelin içinden geçirin. Modeli döndürmek, birbirinin arkasında kalan yüzeyleri ayırt etmeye yardımcı olur."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Servis ve restorasyon için parça talep kartı',summary='Cihaz kimliği, numune, kullanım koşulu ve istenen çıktı bilgilerini tek bir parça kaydında toplayın.',sections='[{"title":"Her parçaya ayrı kimlik verin","body":"Fotoğraf üzerinde bir kod kullanın ve örneği bu kodla etiketleyin. Cihazın modeli, varsa parça numarası ve montaj konumu talep kartında yer almalıdır."},{"title":"Beklenen sonucu işlevle açıklayın","body":"Parçanın yerinde durması, kolay sökülmesi veya belirli bir görünüşe yaklaşması farklı kabul başlıklarıdır. İstenen adet ve kullanım ortamı da yazılır. Modelleme dosyasının teslimi veya sonraki tekrar sipariş hakkındaki beklentiler, fiziksel parçadan ayrı kapsam olarak konuşulur."}]'::jsonb,faq='[{"q":"Araç veya cihazın tüm bilgilerini paylaşmak gerekir mi?","a":"Teknik değerlendirme için ilgili model ve varyant bilgisi yeterli olabilir. Gereksiz kişisel veya ticari veriyi eklemek yerine parçanın uyumunu etkileyen bilgiler seçilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Benzer görünen kapaklar veya sağ-sol parçalar aynı talep içinde karışabilir.","takeaways":["Parça kodu ve etiketli fotoğraf","Cihaz modeli ve montaj konumu","İşlev, görünüş ve adet beklentisi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/teknik-teklif-dosyasi' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Teknik teklif dosyası nasıl hazırlanır?","summary":"Satın alma ve teknik ekiplerin aynı dosya üzerinden ilerlemesi için parça, adet, revizyon ve kabul bilgilerini düzenleyin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Tek bir parça tablosu","body":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"title":"Kabul beklentisi","body":"Kritik ölçüler, görünür yüzeyler, işlevsel kontroller ve numune onayını kimin vereceği talepte yer alsın. Belgelenmeyen bir beklentinin teklif kapsamına otomatik girdiğini varsaymayın. Teslim dosyası ve fiziksel ürün kapsamını ayrı yazın."},{"title":"Takvim ve değişiklik","body":"Hedef tarihi, ara onay adımlarını ve revizyon için ayrılan süreyi belirtin. Talep sonrası geometri veya adet değişirse teklif yeniden değerlendirilebilir. Onaylanan sürümü teknik ekip ve satın alma arasında ortak referans yapın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Her satırda parça kodu, dosya adı, revizyon ve adet bulunsun. Alternatif tasarımları aynı satırda birleştirmeyin. Hangi parçaların birlikte monte edileceğini belirtin ve montaj çizimini ilişkilendirin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Yedek parça malzemesi için kullanım koşullarını tarif etme',summary='Kırılan parçanın nerede, nasıl ve ne kadar süre kullanıldığını yeni malzeme değerlendirmesine taşıyın.',sections='[{"title":"Arıza biçimini tarif ederek başlayın","body":"Bu gözlemler tek başına kesin neden teşhisi değildir fakat değerlendirmeye yön verir. Yeni malzeme kadar geometri ve bağlantı biçiminin de değişmesi gerekebilir."},{"title":"Sıcaklık ve temas verisini somutlaştırın","body":"Araç içi, güneş alan yüzey veya sıcak cihaz yakınlığı gibi konumları açıklayın. Yağ, temizleyici ya da suyla temas varsa ürün ve süre bilgisi ekleyin. Malzeme seçiminde bilinmeyen bir koşulu kesin kabul etmek yerine açık soru olarak tutmak gerekir."}]'::jsonb,faq='[{"q":"Eski parça sertse yenisi de aynı sertlikte mi olmalı?","a":"İşlevi belirleyen tek özellik sertlik değildir. Darbe, esneme, aşınma ve bağlantı davranışı birlikte değerlendirilerek uygun aday seçilir."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Parça darbeden sonra mı kırıldı, sıcakta mı şekil değiştirdi, yoksa sürekli gerildiği bir noktadan mı ayrıldı?","takeaways":["Kırılmanın gözlendiği kullanım anı","Isı ve sıvı temasının biçimi","Bağlantıda oluşan yük yönü"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/malzeme-secim-sorulari' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Malzeme seçmeden önce sorulacak sorular","summary":"Malzeme kararını yalnızca isim veya renge göre değil, parçanın işlevi ve çalışma koşullarına göre hazırlayın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ortamı tanımlayın","body":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"title":"Geometriyi birlikte düşünün","body":"İnce bağlantılar, esneyen tırnaklar ve büyük düz yüzeyler farklı tasarım değerlendirmeleri gerektirir. Malzeme, yönlendirme ve üretim yöntemi birlikte ele alınmalıdır. Sadece doluluk oranını artırmak her işlevsel problemi çözmez."},{"title":"Numuneyle karar verin","body":"Kritik kullanımlarda numuneyi hedef ortama uygun bir kontrol planıyla değerlendirin. Malzeme veri sayfasını, üretim ayarlarını ve test koşullarını birbirine karıştırmayın. Nihai kabul ölçütünü üretimden önce belirleyin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Parça nerede çalışacak? Sıcaklık, güneş, nem ve kimyasal temas var mı? Sürekli yük mü taşıyacak, aralıklı darbe mi alacak? Bu sorulara sayısal bilgi verebiliyorsanız talebe ekleyin; bilinmeyen koşulları da açıkça yazın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Yedek parça dosyasını ölçeklemek neden her zaman çözüm olmaz?',summary='Bir parçanın toplam boyutunu değiştirmeden önce sabit bağlantıları ve yeniden tasarlanması gereken bölgeleri ayırın.',sections='[{"title":"Genel ölçekleme bütün ölçüleri değiştirir","body":"Sorun tek bir boşlukta ise bütün parçayı ölçeklemek yeni uyumsuzluk yaratabilir. Kritik arayüzler işaretlenerek yerel model düzeltmesi gerekip gerekmediği değerlendirilir."},{"title":"Birim hatasıyla uyum hatasını ayırın","body":"Dosya yanlış birimde açılmışsa modelin tamamı belirgin biçimde büyük veya küçük görünebilir. Bilinen bir dış ölçüyle birim kontrolü yapılır. Birim doğru olduğu hâlde bağlantı uymuyorsa bu farklı bir geometri sorunudur; ölçüden sapma ayrıca ele alınmalıdır."}]'::jsonb,faq='[{"q":"Parçayı yüzde iki küçültmek sıkışmayı çözer mi?","a":"Bazı alanlarda boşluk açarken diğer bağlantıları da bozabilir. Sürtmenin nerede olduğunu belirleyip ilgili geometri üzerinde kontrollü değişiklik yapmak daha anlamlıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Modeli yüzde olarak büyütmek dış boyutla birlikte vida aralığını, tırnak kalınlığını ve yuva çapını da değiştirir.","takeaways":["Bilinen dış ölçü ve dosya birimi","Değişmemesi gereken bağlantı aralıkları","Sıkışmanın gerçekleştiği yerel yüzey"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/maket-olcek-planlama' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Maket ölçeği ve parçalara ayırma","summary":"Mimari modelin fiziksel ölçüsünü, okunabilir detayını ve taşıma ihtiyacını tek üretim planında birleştirin. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Ölçeği hesaplayın","body":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"title":"Detay seviyesini seçin","body":"Pencere, korkuluk ve peyzaj gibi öğeleri her ölçekte aynı biçimde üretmek uygun olmayabilir. Anlatım açısından gerekli ayrıntıları listeleyin. Fiziksel sınırlar nedeniyle sadeleştirilecek bölgeler için dijital onay alın."},{"title":"Taşıma ve montaj","body":"Taban ölçüsü, birleşim yerleri ve sökülebilir parçaları kutulama planıyla birlikte değerlendirin. Parçaları kodlayın ve yerleşim şemasını saklayın. Sergileme sırasında sık taşınacak bir maket için servis erişimini de planlayın."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Gerçek boyutu ölçek paydasına bölerek maket boyutunu bulun. Örneğin 10 metrelik bir uzunluk 1:100 ölçekte 100 milimetredir. Kaynak dosyanın metre veya milimetre oluşunu ayrıca kontrol edin."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='Özel yedek parçayı teslim alırken uyum kontrolü',summary='Parçanın takılması, yerinde kalması ve amaçlanan hareketi yapmasını görünüş beklentisinden ayrı değerlendirin.',sections='[{"title":"Kontrolü doğru ürün varyantında yapın","body":"Montajın zorlanmadan yapılması, komşu parçalara sürtmemesi ve sökme yolunun açık kalması gözlenebilir. Yüzeyin güzel görünmesi bu kontrollerin yerine geçmez."},{"title":"Kullanım denemesinin sınırını yazın","body":"Kısa montaj kontrolü uzun dönem dayanım testini temsil etmez. Sıcaklık, sürekli yük veya tekrar kullanım gerekiyorsa uygun değerlendirme planı belirlenir. Kabul edilen sürüm ve varsa açık bulgular tekrar siparişten önce netleştirilir."}]'::jsonb,faq='[{"q":"Numune uyduğunda bütün varyantlara sipariş verilebilir mi?","a":"Farklı yuva veya ürün revizyonlarında ayrıca uyum kontrolü gerekebilir. İlk onayın hangi varyantı kapsadığı korunmalıdır."}]'::jsonb,image='',local_context='',logistics='',editorial='{"answer":"Numune hangi cihaz veya araç üzerinde denendiyse bu bilgi kayıt altına alınmalıdır.","takeaways":["Denemenin yapıldığı ürün kimliği","Takma, tutunma ve sökme gözlemleri","Onay kapsamı ve açık kullanım koşulları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/rehber/numune-kabul-plani' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"Numune kabul planı","summary":"Bir prototipin hangi koşullarda onaylanacağını üretimden önce tanımlayarak revizyon görüşmelerini somutlaştırın. parçayanımda: özel plastik parça & otomotiv odağında değerlendirme.","sections":[{"title":"Özel plastik parça & otomotiv","body":"parçayanımda: İstanbul’da 3D baskı, 3D tarama ve 3D modelleme. Özel plastik parça & otomotiv için proje bazlı üretim. Projenizde 3D baskı, 3D tarama ve 3D modelleme adımlarından hangilerinin gerekli olduğunu kullanım amacınızla birlikte belirleyin."},{"title":"Kontrol maddeleri","body":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"title":"Kayıt düzeni","body":"Numunenin dosya revizyonu, malzemesi, adedi ve test tarihi bir arada tutulmalıdır. Test sırasında yapılan elle düzeltmeler varsa bunları da kaydedin. Yeni baskıda aynı düzeltmenin yeniden gerekmemesi için dijital modele geri işleyin."},{"title":"Onaydan tekrar siparişe","body":"Hangi maddelerin geçtiğini ve hangilerinin açık kaldığını listeleyin. Koşullu onayı nihai onaydan ayırın. Tekrar sipariş verirken aynı revizyonu, değişen adetleri ve yeni kullanım koşullarını belirtin."}],"faq":[{"q":"İlk değerlendirme için ne paylaşmalıyım?","a":"Görünüş, montaj uyumu, ölçü ve işlevi ayrı maddeler halinde yazın. Her maddenin kontrol yöntemini ve karar verecek kişiyi belirleyin. Sadece fotoğraftan onaylanamayacak beklentileri fiziksel deneme aşamasına bırakın."},{"q":"Talebe nasıl başlayabilirim?","a":"3D Studio üzerinden dosyanızı, adet ve kullanım koşullarınızı paylaşabilirsiniz. Dosyanız yoksa fotoğraf, ölçü ve beklenen çıktıyla modelleme değerlendirmesi isteyin."}],"image":"/brand/industrial/parts.webp","local_context":"","logistics":""}'::jsonb;

UPDATE public.landing_pages AS p SET title='İstanbul’da ürün prototipi ve 3D üretim talebi',summary='İstanbul’daki ürün geliştirme projeniz için dijital dosya, numune amacı ve ilk deneme kapsamını tek talepte toplayın.',sections='[{"title":"Dosyayla başlayacağınız adımı seçin","body":"İstanbul içindeki toplantı veya sunum tarihinizi numunenin kullanılacağı gün olarak belirtin. Dosyanın hazırlanması, fiziksel üretim ve taşıma sürelerini aynı işlem gibi değerlendirmeyin."},{"title":"Numuneyi teslimden önce tanımlayın","body":"Gönderilecek fiziksel örnek varsa hangi model revizyonunu temsil ettiğini yazın. Kırılgan yüzey ve aksesuarları fotoğrafla belgeleyin. Numune değerlendirmesiyle tekrar üretim kararının farklı tarihlerde olabileceğini planlayın; tüm ürün ekibinin aynı dosya sürümünü değerlendirmesini sağlayın."}]'::jsonb,faq='[{"q":"İstanbul’un başka bir ilçesinden dosyayla başlayabilir miyim?","a":"Evet; dijital talepte kullanım amacı, yaklaşık ölçü ve numune beklentisi paylaşılabilir. Fiziksel referans gerekip gerekmediği dosya değerlendirmesinin ardından netleştirilir."},{"q":"İlk prototip onayını kim vermeli?","a":"Form, montaj ve görünüş kararları için yetkili proje kişisini belirleyin. Farklı ekiplerin aynı revizyonu değerlendirmesi, tekrar üretim kapsamının netleşmesini sağlar."}]'::jsonb,image='',local_context='İstanbul’daki ürün ekiplerinin dijital ön değerlendirmeye başlaması için atölyeye yolculuk yapması gerekmez. Mevcut işletme beyanında çalışma noktası Ataşehir, Örnek Mahallesi olarak kayıtlıdır. Gönderilecek örneğin hangi karar için inceleneceğini ve ürün ekibinin güncel revizyonunu paylaşın; şehir içindeki toplantınızın tarihi numunenin üretim ve taşıma planından ayrı değerlendirilir.',logistics='Fiziksel prototip gönderiminde kutu içindeki parçaları revizyon ve adet listesiyle eşleştirin. Hassas dış yüzeyleri ayrı koruyun. Teslim alacak kişinin bilgisi ile gerekli gün talep görüşmesinde belirlenir; İstanbul içi ulaşım için süre ayrıca teyit edilir.',editorial='{"answer":"Yeni bir ürün fikrinde form denemesi için eskiz ve dış ölçüler, montaj kontrolü için bileşen bilgileri gerekir.","takeaways":["Prototipin kullanılacağı görüşme tarihi","Bileşen veya gövde referansları","Dijital veri ile fiziksel numunenin eşleştirilmesi"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/bolgeler/istanbul' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"İstanbul 3D üretim","summary":"İstanbul için prototip & kurumsal üretim odağında 3D baskı, 3D tarama ve 3D modelleme talepleri.","sections":[{"title":"Prototip & kurumsal üretim","body":"Bir tasarımı doğrulamak, montajı kolaylaştırmak veya az adetli bir ihtiyacı karşılamak için. Üretim yöntemini kullanım koşulları, adet ve hedeflenen işlevle birlikte değerlendiriyoruz."},{"title":"Talebi doğru hazırlayın","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Üç hizmeti birlikte değerlendirin","body":"Üretime hazır dosyanız varsa 3D baskıyla başlayabilirsiniz. Fiziksel parçanın geometrisi gerekiyorsa tarama, ölçü veya eskizden yeni bir tasarım gerekiyorsa modelleme kapsamı belirlenir. Talebiniz tek bir hizmetle sınırlı olmak zorunda değildir."}],"faq":[{"q":"İstanbul’un her ilçesinde şubeniz var mı?","a":"Hayır. Çalışma noktamız Ataşehir, Örnek Mahallesi’dir. İlçe seçimi talebinizin ve teslimat planının değerlendirilmesine yardımcı olur; ayrı şube anlamına gelmez."},{"q":"Ön değerlendirme için atölyeye gelmem gerekir mi?","a":"Dosya, fotoğraf ve ihtiyaç bilgisiyle uzaktan başlayabilirsiniz. Fiziksel numune veya görüşme gerektiğinde uygun yöntem birlikte belirlenir."}],"image":"","local_context":"İstanbul’daki projenizi dosya veya numuneyle başlatabilirsiniz. Çalışma noktamız Ataşehir, Örnek Mahallesi’dir. İlk değerlendirme için şehir içinde yolculuk yapmanız gerekmez: kullanım amacını, yaklaşık boyutları ve adedi talebinize ekleyin. Numunenin fiziksel olarak görülmesi gerekiyorsa bunun hangi aşamada gerekli olduğu birlikte belirlenir. Böylece sadece form kontrolü isteyen bir prototiple montaj uyumu gerektiren bir parça için aynı hazırlık süreci varsayılmaz.","logistics":"STL dosyanızı online Studio üzerinden paylaşın; numune gereken işlerde taşıma biçimini ön görüşmede belirleyelim. İstanbul içindeki üretim ve teslimat planını ayrı değerlendirelim. İlçeye göre otomatik aynı gün teslim sözü verilmez."}'::jsonb;

UPDATE public.landing_pages AS p SET title='İstanbul üretim ekipleri için aparat ve fikstür talebi',summary='İş istasyonu görüntüleri, iş parçası referansı ve numune kabul planıyla İstanbul’daki üretim ihtiyacınızı teknik talebe dönüştürün.',sections='[{"title":"Saha bilgisini dosya paketine alın","body":"Makine üzerindeki erişim, çalışma alanı ve iş parçasının yükleme biçimini gösterin. Saha ziyareti gerektiği düşünülüyorsa bunu ayrı ihtiyaç olarak belirtin; başlangıçta dijital veriyle hangi kararların verilebileceği değerlendirilebilir."},{"title":"Üretim denemesini vardiya planına bağlayın","body":"Aparat numunesini istasyonda deneyecek kişi ve uygun deneme aralığı belli olmalıdır. Numunenin atölyeden çıkışıyla üretim kabulünün aynı gün gerçekleşeceği varsayılmaz. Uygun parça varyantları, ölçüm cihazı ve kontrol sorumluları hazır olduğunda denemenin sonucu daha açık kaydedilebilir."}]'::jsonb,faq='[{"q":"Saha kurulumu üretim fiyatına dâhil midir?","a":"Kurulum, ziyaret veya yerinde ölçüm ihtiyacı teknik teklifte ayrıca belirtilir. Yalnızca bir parça üretim talebinin bunları otomatik kapsadığı düşünülmemelidir."},{"q":"Üretim denemesi ne zaman planlanır?","a":"İş istasyonu, kontrol sorumlusu ve uygun iş parçası hazır olduğunda deneme aralığı belirlenir. Numunenin teslim edilmesi üretim kabulünün tamamlandığı anlamına gelmez."}]'::jsonb,image='',local_context='İstanbul genelindeki üretim taleplerinde öncelikle istasyon verisi ile iş parçası referansını birlikte inceleriz. Çalışma yeri için eldeki işletme beyanı Ataşehir, Örnek Mahallesi’ni belirtir; ilçe listesi ayrı tesisler bulunduğunu ifade etmez. Fabrikadan fiziksel numune gönderilecekse bunun üretimi aksatıp aksatmayacağı ve aynı örneğin kabul denemesinde gerekli olup olmadığı talep aşamasında konuşulur.',logistics='İş parçasını gönderirken aparat talep kodunu ve numuneye zarar verilmemesi gereken yüzeyleri ambalaj notuna ekleyin. Gelen referansın geri dönüş ihtiyacı ayrıca kaydedilir. Sevkiyat, kurulum ve üretim denemesi farklı adımlar olarak planlanır; ilçe seçimi teslim süresi taahhüdü oluşturmaz.',editorial='{"answer":"Atölye veya fabrikanın bulunduğu ilçe tek başına aparat kapsamını açıklamaz.","takeaways":["İstasyon fotoğrafları ve iş parçası kodu","Numune denemesine uygun vardiya aralığı","Kalite ve üretim kabul sorumluları"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/bolgeler/istanbul' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"İstanbul 3D üretim","summary":"İstanbul için endüstriyel parça & fikstür odağında 3D baskı, 3D tarama ve 3D modelleme talepleri.","sections":[{"title":"Endüstriyel parça & fikstür","body":"Üretim ve bakım ekiplerinin kullanım senaryosuna özel parçalar. Geometri, yük, ortam koşulları ve montaj ilişkisi değerlendirilerek üretim kapsamı netleştirilir."},{"title":"Talebi doğru hazırlayın","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Üç hizmeti birlikte değerlendirin","body":"Üretime hazır dosyanız varsa 3D baskıyla başlayabilirsiniz. Fiziksel parçanın geometrisi gerekiyorsa tarama, ölçü veya eskizden yeni bir tasarım gerekiyorsa modelleme kapsamı belirlenir. Talebiniz tek bir hizmetle sınırlı olmak zorunda değildir."}],"faq":[{"q":"İstanbul’un her ilçesinde şubeniz var mı?","a":"Hayır. Çalışma noktamız Ataşehir, Örnek Mahallesi’dir. İlçe seçimi talebinizin ve teslimat planının değerlendirilmesine yardımcı olur; ayrı şube anlamına gelmez."},{"q":"Ön değerlendirme için atölyeye gelmem gerekir mi?","a":"Dosya, fotoğraf ve ihtiyaç bilgisiyle uzaktan başlayabilirsiniz. Fiziksel numune veya görüşme gerektiğinde uygun yöntem birlikte belirlenir."}],"image":"","local_context":"İstanbul’daki üretim, bakım ve satın alma ekipleri için talebin başlangıcı teknik kapsamdır. Ataşehir’in Örnek Mahallesi’ndeki çalışma noktamıza bir parçayı iletmeden önce parça kodunu, revizyonu ve kullanım koşullarını paylaşın. Hattaki montaj konumu, eşleşen bileşenler ve kritik ölçüler değerlendirmeyi kolaylaştırır. Birden çok departmanın aynı talebi takip ettiği projelerde tek bir dosya sürümü ve onay sorumlusu üzerinden ilerlemek karışıklığı azaltır.","logistics":"Fiziksel numunenin şirketinizden gönderilmesi gerekiyorsa irtibat kişisi ve parça kimliği bilgisini talebe ekleyin. Numune kabulü, üretim hazırlığı ve son teslim için ihtiyaç duyulan adımlar teklif kapsamında birlikte belirlenir."}'::jsonb;

UPDATE public.landing_pages AS p SET title='İstanbul’daki mimari sunumlar için maket proje planı',summary='Maketin ölçeğini, sunum mekânını ve taşıma sınırlarını mimari dosyalarla birlikte değerlendirin.',sections='[{"title":"Sunum mekânının ölçülerini paylaşın","body":"Maketin geçeceği kapı, asansör veya merdiven ölçüsü büyük modellerde tasarımı etkileyebilir. İstanbul içindeki sunum noktası, yalnızca teslim adresi olarak değil kurulum gereksinimiyle birlikte ele alınmalıdır."},{"title":"Kurulumla sunumu ayrı tarihlendirin","body":"Maket parçalıysa mekânda birleştirme ve son kontrol için uygun zaman ayrılmalıdır. Hangi parçaların yerinde takılacağı, kaidenin kim tarafından hazırlanacağı ve taşıma kutusunun nerede tutulacağı belirtilir. Mimari model revizyonu devam ediyorsa son dosya tarihinin sunum takvimiyle ilişkisi ayrıca değerlendirilir."}]'::jsonb,faq='[{"q":"Maket İstanbul içinde tek parça taşınır mı?","a":"Toplam boyut, narin elemanlar ve giriş koşullarına göre karar verilir. Modüler tasarım veya ayrı taşıma kasası gerekiyorsa bunlar teklif kapsamına eklenir."},{"q":"Yerinde kurulum gerekiyorsa ne paylaşmalıyım?","a":"Kaidenin yerini, mekâna giriş ölçülerini ve kurulum için uygun zaman aralığını talebe ekleyin. Kurulum desteğinin teklif kapsamı ayrıca görüşülür."}]'::jsonb,image='',local_context='İstanbul’daki mimarlık ve gayrimenkul sunumlarında maketin kullanılacağı mekân, ölçek seçiminin bir parçasıdır. Proje çalışma noktası mevcut beyana göre Ataşehir, Örnek Mahallesi’ndedir. Avrupa ve Anadolu yakasındaki teslimler için modelin tek parça mı modüler mi taşınacağı, giriş koşulları ve kurulum zamanı talep görüşmesinde değerlendirilir; sunum günüyle taşıma gününü aynı kabul etmeyin.',logistics='Toplam taban ölçüsü, ambalaj hacmi ve çıkarılabilir parçalar taşıma planına yazılır. Teslim yerindeki kapı ve asansör bilgisi büyük maketlerde gereklidir. Kaideye yerleştirme, yerinde kurulum ve taşıma kutusu ayrı kapsam olabilir; kesin gün ve yöntem teklif değerlendirmesinden sonra belirlenir.',editorial='{"answer":"Bir ofis masası, satış alanı veya etkinlik mekânı farklı taban ve izleme koşulları yaratır.","takeaways":["Sunum yerinin giriş ve kaide ölçüleri","Son mimari dosya ve sunum günü","Kurulum gerektiren maket modülleri"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/bolgeler/istanbul' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"İstanbul 3D üretim","summary":"İstanbul için mimari maket & proje sunumu odağında 3D baskı, 3D tarama ve 3D modelleme talepleri.","sections":[{"title":"Mimari maket & proje sunumu","body":"Kütle, cephe, topoğrafya ve yerleşim ilişkisini görünür kılan maket çözümleri. Ölçek ve detay seviyesini hedef kitleniz, sunum amacı ve proje takviminiz belirler."},{"title":"Talebi doğru hazırlayın","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Üç hizmeti birlikte değerlendirin","body":"Üretime hazır dosyanız varsa 3D baskıyla başlayabilirsiniz. Fiziksel parçanın geometrisi gerekiyorsa tarama, ölçü veya eskizden yeni bir tasarım gerekiyorsa modelleme kapsamı belirlenir. Talebiniz tek bir hizmetle sınırlı olmak zorunda değildir."}],"faq":[{"q":"İstanbul’un her ilçesinde şubeniz var mı?","a":"Hayır. Çalışma noktamız Ataşehir, Örnek Mahallesi’dir. İlçe seçimi talebinizin ve teslimat planının değerlendirilmesine yardımcı olur; ayrı şube anlamına gelmez."},{"q":"Ön değerlendirme için atölyeye gelmem gerekir mi?","a":"Dosya, fotoğraf ve ihtiyaç bilgisiyle uzaktan başlayabilirsiniz. Fiziksel numune veya görüşme gerektiğinde uygun yöntem birlikte belirlenir."}],"image":"","local_context":"İstanbul’daki mimari maket projelerinde ölçek, sunum yeri ve modelin taşınma biçimi birlikte düşünülmelidir. Çalışma noktamız Ataşehir, Örnek Mahallesi’dir. İlk görüşme için mimari dosyanın güncel sürümü, hedef ölçek ve sunum tarihi yeterli bir başlangıç oluşturur. Arazi veya yerleşim modeli birden fazla modülden oluşacaksa birleşim çizgileri ve kaide ölçüsü daha tasarım aşamasında değerlendirilir. Mevcut bir fiziksel modelin sayısallaştırılması ayrıca tarama kapsamında ele alınır.","logistics":"Maketin teslim edileceği adres ve paketli halde geçmesi gereken açıklıklar boyut planını etkileyebilir. Kaide, sökülebilir parçalar ve taşıma hazırlığı kapsamını baştan paylaşın. Teslim tarihi modelin detay seviyesi ve sunum planıyla birlikte netleştirilir."}'::jsonb;

UPDATE public.landing_pages AS p SET title='İstanbul’da kırık veya eksik plastik parça değerlendirmesi',summary='Parçanızın fotoğrafını, montaj yuvasını ve kullanım görevini paylaşarak özel üretim için gerekli referansları belirleyin.',sections='[{"title":"Parçayı göndermeden fotoğraflayın","body":"Montaj yuvası cihaz üzerinde kalacaksa ölçü ve geniş görüntüsü ayrıca gerekir. Numuneyi evden veya servisten göndermeden önce gerçekten hangi bölümün incelenmesi gerektiği netleştirilebilir."},{"title":"İlk uyum denemesini aynı yuvada yapın","body":"İstanbul içindeki talepte numune elinize ulaştığında hangi cihaz veya araçta deneneceği belli olmalıdır. Farklı varyantta yapılan kontrol ilk ölçüyü temsil etmeyebilir. Takılma, boşluk veya sürtme noktalarını fotoğraflayıp parça revizyonuyla birlikte paylaşın; renk ve görünüş onayını uyumdan ayrı tutabilirsiniz."}]'::jsonb,faq='[{"q":"Kırık parçanın tüm parçalarını göndermeli miyim?","a":"Küçük kopmuş bölgeler geometriyi anlamaya yardımcı olabilir. Önce fotoğrafla nelerin bulunduğunu gösterin; gönderim kapsamı ve referansların geri dönüşü görüşmede belirlenir."},{"q":"Numune geri gönderilecekse bunu belirtmeli miyim?","a":"Evet. Fiziksel örneğin korunması ve iade ihtiyacı baştan kayda alınmalıdır; yeni üretilen numuneyle eski referans birbirine karıştırılmaz."}]'::jsonb,image='',local_context='İstanbul’dan gelen özel parça taleplerinde ilk ayrım, elde sağlam örnek mi kırık numune mi yoksa yalnızca montaj yuvası mı bulunduğudur. Kayıtlı çalışma yeri beyanı Ataşehir, Örnek Mahallesi’dir. İlçenizi seçmek taşıma planına yardımcı olur; her ilçede fiziksel başvuru noktası olduğu anlamına gelmez. Ön fotoğraflar, parçayı cihazdan sökmeden hangi ölçülerin gerekli olduğunu konuşmayı sağlar.',logistics='Küçük tırnak ve kopmuş parçaları ana numuneyle aynı kimlik altında ayrı koruyun. Montaj yerine ait fotoğrafı talebe ekleyin; örneğin geri gönderilmesi gerekiyorsa bunu belirtin. Yeni numunenin teslimi ve cihaz üzerindeki uyum kontrolü ayrı planlanır; otomatik aynı gün üretim veya kurye taahhüdü verilmez.',editorial='{"answer":"Kırık örneğin konumu, sağlam yüzeyleri ve ayrılan küçük parçaları fotoğrafta gösterin.","takeaways":["Kırık örneğin tüm görünen yüzleri","Cihazda kalan montaj yuvası","İlk numunenin deneneceği ürün varyantı"],"relatedPaths":["/3d-modelleme","/3d-tarama","/3d-baski"]}'::jsonb,updated_at=now() WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/bolgeler/istanbul' AND status='draft' AND editorial='{}'::jsonb AND to_jsonb(p) @> '{"title":"İstanbul 3D üretim","summary":"İstanbul için özel plastik parça & otomotiv odağında 3D baskı, 3D tarama ve 3D modelleme talepleri.","sections":[{"title":"Özel plastik parça & otomotiv","body":"Kapak, iç trim, bağlantı elemanı ve adaptör ihtiyaçları için ölçüye özel tasarım. Bağlantı geometrisi, kullanım koşulları ve malzeme seçimini birlikte ele alıyoruz."},{"title":"Talebi doğru hazırlayın","body":"Adet, renk, yük, sıcaklık, eşleşen parçalar ve kritik ölçüleri yazın. Tüm ölçülerin eşit derecede kritik olduğunu varsaymak teklifin kapsamını belirsizleştirir."},{"title":"Üç hizmeti birlikte değerlendirin","body":"Üretime hazır dosyanız varsa 3D baskıyla başlayabilirsiniz. Fiziksel parçanın geometrisi gerekiyorsa tarama, ölçü veya eskizden yeni bir tasarım gerekiyorsa modelleme kapsamı belirlenir. Talebiniz tek bir hizmetle sınırlı olmak zorunda değildir."}],"faq":[{"q":"İstanbul’un her ilçesinde şubeniz var mı?","a":"Hayır. Çalışma noktamız Ataşehir, Örnek Mahallesi’dir. İlçe seçimi talebinizin ve teslimat planının değerlendirilmesine yardımcı olur; ayrı şube anlamına gelmez."},{"q":"Ön değerlendirme için atölyeye gelmem gerekir mi?","a":"Dosya, fotoğraf ve ihtiyaç bilgisiyle uzaktan başlayabilirsiniz. Fiziksel numune veya görüşme gerektiğinde uygun yöntem birlikte belirlenir."}],"image":"","local_context":"İstanbul’da bulunamayan bir plastik parça için talep oluştururken önce fotoğrafları, yaklaşık ölçüleri ve parçanın görevini paylaşın. Numune değerlendirmesi için çalışma noktamız Ataşehir, Örnek Mahallesi’dir. Kırık parçanın yalnızca sağlam yüzünü değil, bağlantı ve montaj bölgelerini de göstermek yararlıdır. Eş parça veya karşılıklı bir yüz varsa bunun bilgisi eksik geometrinin yorumlanmasına yardımcı olur. Yeniden üretim kararı parçanın görevi ve çalışma koşulları incelendikten sonra verilir.","logistics":"Orijinal numuneyi göndermeden önce hangi parçaların birlikte inceleneceğini belirleyelim. Eşleşen kapak veya bağlantı elemanı varsa fotoğrafını da talebe ekleyin. Numunenin gönderimi, iadesi ve yeni parçanın teslimi proje planında ayrı ayrı değerlendirilir."}'::jsonb;
